/* gerado por _fonte/enem/gerar.py a partir de _fonte/enem/cards: não edite à mão */
window.ENEM_BANCO = [{"id":"bio","nome":"Biologia","ic":"🧬","cards":[{"t":"P","top":"Ecologia","f":"O que é nicho ecológico?","v":"O \"modo de vida\" da espécie: o que come, quando age, onde vive, como interage. Habitat é só o \"endereço\".","id":"bio0"},{"t":"P","top":"Ecologia","f":"Cadeia alimentar: o que acontece com a energia a cada nível trófico?","v":"Diminui (cerca de 10% passa adiante). O resto se perde como calor na respiração. Por isso cadeias são curtas.","m":"Regra dos 10%: de cada 100 que entram, só 10 sobem um degrau.","img":"bio_piramide_energia","id":"bio1"},{"t":"P","top":"Ecologia","f":"Diferença entre pirâmide de energia e pirâmide de biomassa/números","v":"A de energia NUNCA é invertida. Biomassa pode inverter (fitoplâncton no mar) e números pode inverter (uma árvore com milhares de insetos).","m":"Energia \"não volta atrás\": a pirâmide de energia NUNCA fica de cabeça para baixo.","id":"bio2"},{"t":"P","top":"Ecologia","f":"O que é magnificação (bioacumulação) trófica?","v":"Substâncias não biodegradáveis (mercúrio, DDT, metais pesados) se acumulam e ficam mais concentradas nos níveis tróficos mais altos. Predadores de topo são os mais contaminados.","m":"Quem come mais no topo, acumula mais veneno: \"o tubarão paga a conta\".","img":"bio_magnificacao","id":"bio3"},{"t":"P","top":"Ecologia","f":"Mutualismo x protocooperação","v":"Ambos +/+. No mutualismo a relação é obrigatória (líquen, cupim e protozoário). Na protocooperação é facultativa (pássaro-palito e crocodilo).","m":"MUtualismo = MUito ligado (não vive sem). PROTOcooperação = só uma \"PROpostinha\" de parceria, opcional.","id":"bio4"},{"t":"P","top":"Ecologia","f":"Comensalismo x inquilinismo","v":"Ambos +/0. Comensalismo: aproveita restos de alimento (rêmora e tubarão). Inquilinismo: usa como abrigo ou suporte (epífitas como orquídeas, peixe-agulha no pepino-do-mar).","m":"COMensalismo = COMe as sobras. INQUILINismo = mora de favor (inquilino).","id":"bio5"},{"t":"P","top":"Ecologia","f":"Amensalismo (antibiose)","v":"Uma espécie libera substância que prejudica outra (-/0). Ex.: fungo Penicillium e bactérias; maré vermelha.","id":"bio6"},{"t":"P","top":"Ecologia","f":"Competição intraespecífica x interespecífica","v":"Intra: entre indivíduos da mesma espécie. Inter: entre espécies diferentes que disputam recurso; pode levar à exclusão competitiva (princípio de Gause).","id":"bio7"},{"t":"P","top":"Ecologia","f":"Sucessão ecológica primária x secundária","v":"Primária: começa em área nunca habitada (rocha nua), com pioneiras como liquens. Secundária: em área já habitada e perturbada (incêndio, roça abandonada). Comunidade final = clímax.","m":"Primária = Primeira vez (rocha nua). Secundária = Segunda chance (já tinha vida).","img":"bio_sucessao","id":"bio8"},{"t":"P","top":"Ecologia","f":"O que muda ao longo da sucessão ecológica?","v":"Aumentam biodiversidade, biomassa e complexidade das teias. A produtividade líquida tende a cair perto do clímax (quase tudo que é produzido é consumido).","id":"bio9"},{"t":"P","top":"Ecologia","f":"Ciclo do nitrogênio: etapas e organismos","v":"Fixação (N2 → NH3, bactérias Rhizobium nas leguminosas e cianobactérias), nitrificação (NH3 → NO2- → NO3-, Nitrosomonas e Nitrobacter), assimilação pelas plantas, desnitrificação (NO3- → N2, Pseudomonas).","m":"Ordem: Fixa → Nitrifica → Assimila → Desnitrifica (\"Fui Na Academia Domingo\").","img":"bio_ciclo_nitrogenio","id":"bio10"},{"t":"P","top":"Ecologia","f":"Por que rotação de culturas com leguminosas (feijão, soja) é usada na agricultura?","v":"As raízes têm nódulos com bactérias fixadoras de nitrogênio (Rhizobium), que enriquecem o solo e reduzem a necessidade de adubo nitrogenado.","id":"bio11"},{"t":"P","top":"Ecologia","f":"Ciclo do carbono: o que retira e o que devolve CO2 à atmosfera?","v":"Retira: fotossíntese (e dissolução nos oceanos). Devolve: respiração, decomposição, queima de combustíveis fósseis e queimadas.","id":"bio12"},{"t":"P","top":"Ecologia","f":"Efeito estufa x aquecimento global","v":"Efeito estufa é natural e mantém a Terra habitável (CO2, CH4, vapor d'água retêm calor). Aquecimento global é a intensificação dele pela emissão humana de gases.","id":"bio13"},{"t":"P","top":"Ecologia","f":"O que é eutrofização?","v":"Excesso de nutrientes (esgoto, fertilizantes com N e P) → explosão de algas → algas morrem → decompositores aeróbios consomem o O2 → morte de peixes. Aumenta a DBO.","m":"\"Excesso de comida mata de fome de ar\": nutriente demais → falta O2.","img":"bio_eutrofizacao","id":"bio14"},{"t":"P","top":"Ecologia","f":"O que é DBO (demanda bioquímica de oxigênio)?","v":"Quantidade de O2 que os microrganismos consomem para decompor a matéria orgânica da água. DBO alta = água muito poluída por matéria orgânica.","id":"bio15"},{"t":"P","top":"Ecologia","f":"Camada de ozônio: o que a destrói e por que importa?","v":"CFCs liberam cloro que quebra O3 na estratosfera. O ozônio filtra radiação UV, que causa câncer de pele e mutações.","id":"bio16"},{"t":"P","top":"Ecologia","f":"Chuva ácida: causa e efeitos","v":"Óxidos de enxofre (SO2, da queima de carvão e diesel) e de nitrogênio (NOx) reagem com água formando H2SO4 e HNO3. Corrói monumentos de mármore (CaCO3), acidifica lagos e solos.","id":"bio17"},{"t":"P","top":"Ecologia","f":"Biomas brasileiros: características da Caatinga","v":"Semiárido, chuvas irregulares, plantas xerófitas (cactos, folhas reduzidas, espinhos), caducifólia na seca. Bioma exclusivamente brasileiro.","id":"bio18"},{"t":"P","top":"Ecologia","f":"Biomas brasileiros: características do Cerrado","v":"Savana, árvores tortuosas de casca grossa (resistência ao fogo), raízes profundas que alcançam lençol freático, solo ácido rico em alumínio. \"Berço das águas\". Ameaçado pela soja.","m":"Cerrado = árvore \"torta e de casca grossa, com raiz de poço profundo\".","id":"bio19"},{"t":"P","top":"Ecologia","f":"Biomas brasileiros: Pampa","v":"Campos do sul do RS, vegetação rasteira (gramíneas), clima subtropical. Ameaçado pela pecuária extensiva, silvicultura (eucalipto) e arenização.","id":"bio20"},{"t":"P","top":"Ecologia","f":"Biomas brasileiros: Mata Atlântica e Pantanal","v":"Mata Atlântica: floresta úmida costeira, altíssima biodiversidade e endemismo, só ~12% restante. Pantanal: maior planície alagável do mundo, ciclo de cheia e seca.","id":"bio21"},{"t":"P","top":"Ecologia","f":"Por que o solo da Amazônia é pobre apesar da floresta exuberante?","v":"Os nutrientes estão na biomassa e na serrapilheira, reciclados rapidamente. Desmatado, o solo fica exposto à lixiviação pelas chuvas e perde fertilidade.","id":"bio22"},{"t":"P","top":"Ecologia","f":"Controle biológico de pragas","v":"Uso de um inimigo natural (predador, parasita, patógeno) para controlar uma praga, reduzindo agrotóxicos. Ex.: vespas contra lagartas, Bacillus thuringiensis.","id":"bio23"},{"t":"P","top":"Ecologia","f":"Espécie exótica invasora: por que é problema?","v":"Sem predadores ou competidores naturais, cresce sem controle e desloca espécies nativas. Ex.: mexilhão-dourado, javali, caramujo-africano.","id":"bio24"},{"t":"P","top":"Citologia e bioquímica","f":"Diferença entre célula procariota e eucariota","v":"Procariota (bactérias): sem núcleo (DNA no citoplasma, nucleoide) e sem organelas membranosas; tem ribossomos. Eucariota: núcleo com carioteca e organelas membranosas.","id":"bio25"},{"t":"P","top":"Citologia e bioquímica","f":"Diferença entre célula animal e vegetal","v":"Vegetal tem parede celular de celulose, cloroplastos e grande vacúolo central. Animal tem centríolos e lisossomos mais evidentes, e reserva glicogênio (vegetal reserva amido).","id":"bio26"},{"t":"P","top":"Citologia e bioquímica","f":"Função das mitocôndrias","v":"Respiração celular aeróbia (ciclo de Krebs e cadeia respiratória) → produção de ATP. Têm DNA próprio, herança materna (teoria endossimbiótica).","m":"Mitocôndria = \"usina de energia\" (ATP). DNA só da mãe: herança materna.","id":"bio27"},{"t":"P","top":"Citologia e bioquímica","f":"Função do retículo endoplasmático rugoso x liso","v":"Rugoso (com ribossomos): síntese de proteínas para exportação. Liso: síntese de lipídios (esteroides) e desintoxicação (abundante no fígado).","id":"bio28"},{"t":"P","top":"Citologia e bioquímica","f":"Função do complexo golgiense","v":"Modifica, empacota e secreta substâncias; forma lisossomos e o acrossomo do espermatozoide.","id":"bio29"},{"t":"P","top":"Citologia e bioquímica","f":"Função dos lisossomos","v":"Digestão intracelular com enzimas hidrolíticas; autofagia (reciclagem de organelas).","id":"bio30"},{"t":"P","top":"Citologia e bioquímica","f":"Transporte passivo x ativo pela membrana","v":"Passivo: a favor do gradiente, sem ATP (difusão simples, facilitada, osmose). Ativo: contra o gradiente, gasta ATP (bomba de sódio e potássio).","m":"Ativo = gasta ATP (ATivo, ATP). Passivo = de graça, a favor do gradiente.","id":"bio31"},{"t":"P","top":"Citologia e bioquímica","f":"Osmose: célula em meio hipertônico e hipotônico","v":"Hipertônico: célula perde água e murcha (plasmólise na vegetal). Hipotônico: ganha água; hemácia pode estourar (hemólise), vegetal fica túrgida (parede impede ruptura).","m":"\"A água vai para onde tem mais sal\" (sai do lado diluído para o concentrado).","img":"bio_osmose","id":"bio32"},{"t":"P","top":"Citologia e bioquímica","f":"Por que salgar a carne a conserva?","v":"Meio hipertônico: os microrganismos perdem água por osmose e não conseguem se multiplicar. O mesmo vale para doces com muito açúcar.","id":"bio33"},{"t":"P","top":"Citologia e bioquímica","f":"Bomba de sódio e potássio","v":"Transporte ativo que joga 3 Na+ para fora e traz 2 K+ para dentro, gastando ATP. Mantém o potencial de membrana (essencial nos neurônios).","id":"bio34"},{"t":"P","top":"Citologia e bioquímica","f":"Enzimas: o que são e o que afeta sua atividade","v":"Proteínas catalisadoras (diminuem a energia de ativação). Afetadas por temperatura e pH: acima do ótimo, desnaturam (perdem a forma do sítio ativo).","id":"bio35"},{"t":"P","top":"Citologia e bioquímica","f":"Fotossíntese: equação geral e onde ocorre","v":"6CO2 + 6H2O + luz → C6H12O6 + 6O2, no cloroplasto. O O2 liberado vem da água (fotólise).","m":"A fotossíntese é a respiração \"de trás para frente\": CO2 + H2O entram, glicose + O2 saem.","id":"bio36"},{"t":"P","top":"Citologia e bioquímica","f":"Fotossíntese: fase clara x fase escura","v":"Clara (tilacoides): luz quebra água, libera O2, produz ATP e NADPH. Química/escura (estroma): ciclo de Calvin fixa CO2 em glicose usando ATP e NADPH.","m":"CLARA = Luz e tiLacoide. ESCURA (química) = Estroma e ciclo de Calvin.","id":"bio37"},{"t":"P","top":"Citologia e bioquímica","f":"Respiração aeróbia: equação e saldo","v":"C6H12O6 + 6O2 → 6CO2 + 6H2O + energia. Saldo de ~30 a 38 ATP por glicose. Etapas: glicólise (citoplasma), Krebs e cadeia respiratória (mitocôndria).","id":"bio38"},{"t":"P","top":"Citologia e bioquímica","f":"Fermentação alcoólica x lática","v":"Alcoólica (leveduras): glicose → etanol + CO2 (pão, cerveja). Lática (bactérias, músculo em esforço): glicose → ácido lático (iogurte). Ambas rendem só 2 ATP.","id":"bio39"},{"t":"P","top":"Citologia e bioquímica","f":"Por que a massa do pão cresce?","v":"As leveduras (Saccharomyces) fazem fermentação alcoólica e liberam CO2, que forma bolhas na massa. O álcool evapora no forno.","id":"bio40"},{"t":"P","top":"Citologia e bioquímica","f":"Mitose x meiose","v":"Mitose: 1 célula → 2 idênticas (2n → 2n), crescimento e reparo. Meiose: 1 célula → 4 com metade dos cromossomos (2n → n), forma gametas, tem crossing-over (variabilidade).","m":"MEIOse divide pela MEtade (2n → n). MITOse faz cópias IdênTicas.","img":"bio_mitose_meiose","id":"bio41"},{"t":"P","top":"Citologia e bioquímica","f":"Por que a meiose gera variabilidade genética?","v":"Crossing-over (permutação) na prófase I e segregação independente dos cromossomos homólogos na anáfase I.","id":"bio42"},{"t":"P","top":"Citologia e bioquímica","f":"O que é o câncer do ponto de vista celular?","v":"Divisão celular descontrolada por mutações em genes que regulam o ciclo (proto-oncogenes e supressores de tumor). Metástase = células migram para outros tecidos.","id":"bio43"},{"t":"P","top":"Citologia e bioquímica","f":"Principais funções de carboidratos, lipídios e proteínas","v":"Carboidratos: energia rápida (glicose) e estrutura (celulose). Lipídios: reserva de energia, membranas, hormônios esteroides. Proteínas: estrutura, enzimas, anticorpos, transporte.","id":"bio44"},{"t":"P","top":"Citologia e bioquímica","f":"Vitaminas: deficiências clássicas (A, C, D, K, B12)","v":"A: cegueira noturna. C: escorbuto (gengiva sangrando). D: raquitismo. K: problemas de coagulação. B12: anemia perniciosa.","m":"\"A-olho, C-gengiva, D-osso, K-coágulo (K de Koagulação, do alemão), B12-sangue\".","id":"bio45"},{"t":"P","top":"Genética","f":"1ª Lei de Mendel","v":"Cada característica é determinada por um par de fatores (alelos) que se separam na formação dos gametas. Cruzamento Aa x Aa → 1 AA : 2 Aa : 1 aa (fenótipo 3:1).","m":"Aa x Aa → 3:1 no fenótipo, 1:2:1 no genótipo.","img":"bio_punnett_mono","id":"bio46"},{"t":"P","top":"Genética","f":"2ª Lei de Mendel (segregação independente)","v":"Genes em cromossomos diferentes se distribuem independentemente. AaBb x AaBb → proporção fenotípica 9:3:3:1.","m":"Di-hibridismo: 9:3:3:1 (soma 16 = 4 x 4 gametas).","img":"bio_punnett_di","id":"bio47"},{"t":"P","top":"Genética","f":"Genótipo x fenótipo","v":"Genótipo: constituição genética (AA, Aa). Fenótipo: característica observável, resultado do genótipo + ambiente.","id":"bio48"},{"t":"P","top":"Genética","f":"Codominância x dominância incompleta","v":"Codominância: os dois alelos se expressam juntos (sangue AB). Dominância incompleta: heterozigoto tem fenótipo intermediário (flor rosa entre vermelha e branca).","id":"bio49"},{"t":"P","top":"Genética","f":"Sistema ABO: quem doa e quem recebe?","v":"O (sem aglutinogênios) é doador universal. AB (sem anticorpos anti-A e anti-B) é receptor universal. A recebe de A e O; B recebe de B e O.","m":"O = \"Oferece para todos\". AB = \"Aceita de Bastante gente\".","img":"bio_abo","id":"bio50"},{"t":"P","top":"Genética","f":"Fator Rh e eritroblastose fetal","v":"Ocorre com mãe Rh- e feto Rh+, geralmente na 2ª gestação: a mãe sensibilizada produz anti-Rh que destrói hemácias do feto. Prevenção: imunoglobulina anti-Rh após o 1º parto.","m":"\"Mãe NEGATIVA, filho POSITIVO, problema no SEGUNDO\".","id":"bio51"},{"t":"P","top":"Genética","f":"Herança ligada ao X: exemplos e padrão","v":"Daltonismo e hemofilia (recessivas no X). São mais comuns em homens (XY, basta um alelo). O pai passa o X para todas as filhas; o filho recebe o X da mãe.","m":"Pai daltônico passa o X afetado para TODAS as filhas; nunca para os filhos homens (que recebem o Y).","id":"bio52"},{"t":"P","top":"Genética","f":"Como saber em um heredograma se a herança é recessiva?","v":"Pais normais com filho afetado → a característica é recessiva (os pais são heterozigotos).","id":"bio53"},{"t":"P","top":"Genética","f":"Probabilidade em genética: regra do \"e\" e do \"ou\"","v":"\"E\" (eventos independentes simultâneos): multiplica. \"Ou\" (mutuamente exclusivos): soma. Ex.: chance de menino E afetado = 1/2 x 1/4 = 1/8.","id":"bio54"},{"t":"P","top":"Genética","f":"DNA x RNA","v":"DNA: dupla hélice, desoxirribose, bases A T C G. RNA: fita simples, ribose, bases A U C G. DNA guarda a informação; RNA participa da síntese de proteínas.","m":"RNA troca T por U (\"no RNA, o T vira U\") e é de fita simples.","id":"bio55"},{"t":"P","top":"Genética","f":"Replicação, transcrição e tradução","v":"Replicação: DNA → DNA (semiconservativa). Transcrição: DNA → RNAm (no núcleo). Tradução: RNAm → proteína (no ribossomo, RNAt traz aminoácidos).","m":"TranScrição = Script (DNA vira texto de RNA). TraDUção = traDUz para a língua das proteínas.","img":"bio_dogma","id":"bio56"},{"t":"P","top":"Genética","f":"Código genético é \"degenerado\": o que significa?","v":"Vários códons diferentes codificam o mesmo aminoácido. Por isso algumas mutações pontuais são silenciosas (não alteram a proteína).","id":"bio57"},{"t":"P","top":"Genética","f":"O que é um organismo transgênico?","v":"Organismo que recebeu gene de outra espécie por engenharia genética. Ex.: milho Bt (gene de bactéria que produz toxina contra insetos), bactéria que produz insulina humana.","id":"bio58"},{"t":"P","top":"Genética","f":"Clonagem: o que é e qual o exemplo clássico?","v":"Produção de indivíduo geneticamente idêntico a partir do núcleo de uma célula somática transferido para um óvulo sem núcleo. Ex.: ovelha Dolly.","id":"bio59"},{"t":"P","top":"Genética","f":"Teste de DNA de paternidade: como funciona?","v":"Compara bandas de DNA (marcadores, eletroforese). Toda banda do filho que não veio da mãe tem de estar no pai.","id":"bio60"},{"t":"P","top":"Genética","f":"Células-tronco embrionárias x adultas","v":"Embrionárias: pluripotentes (formam qualquer tecido). Adultas (medula óssea, cordão umbilical): multipotentes, mais limitadas. iPS: células adultas reprogramadas.","id":"bio61"},{"t":"P","top":"Genética","f":"Síndrome de Down e outras aneuploidias","v":"Down: trissomia do 21 (47 cromossomos). Turner: 45,X0 (mulher). Klinefelter: 47,XXY (homem). Causa: não disjunção na meiose.","id":"bio62"},{"t":"P","top":"Evolução","f":"Lamarck x Darwin","v":"Lamarck: uso e desuso + herança de caracteres adquiridos (errado). Darwin: variação + seleção natural; os mais aptos sobrevivem e deixam mais descendentes.","m":"Lamarck = \"Lei do uso e desuso\" (L com L). Darwin = \"a natureza Decide quem fica\" (seleção).","id":"bio63"},{"t":"P","top":"Evolução","f":"Teoria sintética (neodarwinismo)","v":"Seleção natural + genética: mutação e recombinação geram variabilidade; seleção natural, deriva genética e migração alteram as frequências gênicas.","id":"bio64"},{"t":"P","top":"Evolução","f":"Como surgem bactérias resistentes a antibióticos?","v":"O antibiótico não cria a resistência: seleciona bactérias que já tinham mutação de resistência. Elas sobrevivem e se multiplicam. Uso incorreto acelera isso.","m":"O antibiótico é o \"juiz\", não o \"criador\": ele só seleciona quem já era resistente.","id":"bio65"},{"t":"P","top":"Evolução","f":"Órgãos homólogos x análogos","v":"Homólogos: mesma origem embrionária, função pode diferir (braço humano e asa de morcego) → divergência. Análogos: mesma função, origens diferentes (asa de inseto e de ave) → convergência.","m":"HOMÓlogo = mesma ORIGEM (homo = igual). ANÁlogo = mesma função, \"ANAlogia\" de uso.","id":"bio66"},{"t":"P","top":"Evolução","f":"Especiação alopátrica","v":"Barreira geográfica separa populações; com o tempo acumulam diferenças até isolamento reprodutivo (não geram descendentes férteis) → novas espécies.","id":"bio67"},{"t":"P","top":"Evolução","f":"O que é deriva genética?","v":"Mudança aleatória nas frequências gênicas, forte em populações pequenas. Inclui efeito fundador e efeito gargalo.","id":"bio68"},{"t":"P","top":"Evolução","f":"Equilíbrio de Hardy-Weinberg: fórmula","v":"p + q = 1 e p² + 2pq + q² = 1. Vale para populações grandes, sem seleção, mutação, migração e com cruzamentos aleatórios.","id":"bio69"},{"t":"P","top":"Fisiologia humana","f":"Digestão: onde começa a de carboidratos, proteínas e lipídios?","v":"Carboidratos: boca (amilase salivar). Proteínas: estômago (pepsina, meio ácido). Lipídios: intestino delgado (lipase pancreática + bile emulsificando).","m":"Boca = Amido; Estômago = Proteína; Intestino = Gordura (\"A-P-G\" na ordem do caminho).","id":"bio70"},{"t":"P","top":"Fisiologia humana","f":"Função da bile","v":"Produzida no fígado, armazenada na vesícula. Não é enzima: emulsifica gorduras (quebra em gotas menores), facilitando a ação da lipase.","id":"bio71"},{"t":"P","top":"Fisiologia humana","f":"Onde ocorre a maior parte da absorção de nutrientes?","v":"No intestino delgado, graças às vilosidades e microvilosidades que aumentam a superfície. O intestino grosso absorve principalmente água.","id":"bio72"},{"t":"P","top":"Fisiologia humana","f":"Pequena e grande circulação","v":"Pequena (pulmonar): ventrículo direito → artéria pulmonar → pulmões → veias pulmonares → átrio esquerdo. Grande (sistêmica): ventrículo esquerdo → aorta → corpo → veias cavas → átrio direito.","m":"Pequena = Pulmão (as duas com P). Ventrículo esquerdo = o mais musculoso, bombeia para o corpo todo.","img":"bio_circulacao","id":"bio73"},{"t":"P","top":"Fisiologia humana","f":"Artéria x veia","v":"Artéria sai do coração (parede espessa, alta pressão). Veia chega ao coração (parede fina, válvulas). Artéria pulmonar leva sangue venoso; veia pulmonar leva sangue arterial.","m":"Artéria = A sai (Away do coração). Veia = Volta ao coração.","id":"bio74"},{"t":"P","top":"Fisiologia humana","f":"Hematose","v":"Troca gasosa nos alvéolos: O2 passa para o sangue e CO2 sai, por difusão.","id":"bio75"},{"t":"P","top":"Fisiologia humana","f":"Por que o monóxido de carbono (CO) é tão perigoso?","v":"Liga-se à hemoglobina com afinidade muito maior que o O2 (carboxiemoglobina) e impede o transporte de oxigênio.","id":"bio76"},{"t":"P","top":"Fisiologia humana","f":"Néfron: etapas da formação da urina","v":"Filtração (glomérulo/cápsula de Bowman), reabsorção (glicose, água, sais no túbulo) e secreção. ADH aumenta a reabsorção de água.","id":"bio77"},{"t":"P","top":"Fisiologia humana","f":"Por que bebida alcoólica faz urinar mais?","v":"O álcool inibe o ADH (hormônio antidiurético), então os rins reabsorvem menos água.","id":"bio78"},{"t":"P","top":"Fisiologia humana","f":"Insulina x glucagon","v":"Ambos do pâncreas. Insulina baixa a glicemia (glicose entra nas células, vira glicogênio). Glucagon sobe a glicemia (quebra glicogênio no fígado).","m":"Insulina INSere glicose nas células (glicemia cai). GLUCAgon GERA GLUcose no sangue (glicemia sobe).","img":"bio_glicemia","id":"bio79"},{"t":"P","top":"Fisiologia humana","f":"Diabetes tipo 1 x tipo 2","v":"Tipo 1: autoimune, pâncreas não produz insulina (precisa aplicar). Tipo 2: resistência à insulina, ligada a obesidade e sedentarismo.","id":"bio80"},{"t":"P","top":"Fisiologia humana","f":"Hormônios da tireoide e o papel do iodo","v":"T3 e T4 regulam o metabolismo; precisam de iodo. Falta de iodo → bócio. Por isso o sal é iodado no Brasil.","id":"bio81"},{"t":"P","top":"Fisiologia humana","f":"Hormônios do ciclo menstrual","v":"FSH (amadurece o folículo, estimula estrogênio), LH (pico causa a ovulação, forma o corpo lúteo), estrogênio (espessa endométrio), progesterona (mantém o endométrio).","m":"\"FSH Faz o folículo, LH Libera o óvulo, Progesterona Protege a gravidez\".","img":"bio_ciclo_menstrual","id":"bio82"},{"t":"P","top":"Fisiologia humana","f":"Como age a pílula anticoncepcional?","v":"Estrogênio e progesterona sintéticos inibem FSH e LH na hipófise, impedindo a ovulação.","id":"bio83"},{"t":"P","top":"Fisiologia humana","f":"Qual hormônio o teste de gravidez detecta?","v":"hCG (gonadotrofina coriônica), produzido pelo embrião/placenta; mantém o corpo lúteo no início da gestação.","id":"bio84"},{"t":"P","top":"Fisiologia humana","f":"Sistema nervoso simpático x parassimpático","v":"Simpático: \"luta ou fuga\" (acelera coração, dilata pupila e brônquios, inibe digestão; noradrenalina). Parassimpático: repouso (desacelera coração, estimula digestão; acetilcolina).","m":"SIMpático = \"SIM, vamos lutar!\" (acelera). PARAssimpático = \"PARA e descansa\".","id":"bio85"},{"t":"P","top":"Fisiologia humana","f":"Arco reflexo","v":"Resposta rápida e involuntária coordenada pela medula espinhal: receptor → neurônio sensitivo → medula → neurônio motor → efetor. Ex.: reflexo patelar.","id":"bio86"},{"t":"P","top":"Imunologia e saúde","f":"Vacina x soro","v":"Vacina: antígeno → imunização ativa, memória, prevenção, demora a agir. Soro: anticorpos prontos → imunização passiva, ação imediata, sem memória (picada de cobra, tétano).","m":"VaCina = Cria memória (prevenção). SOro = SOcorro imediato (tratamento).","img":"bio_vacina_soro","id":"bio87"},{"t":"P","top":"Imunologia e saúde","f":"Por que antibiótico não serve para gripe ou covid?","v":"Antibióticos atuam em estruturas de bactérias (parede, ribossomos bacterianos). Vírus não têm metabolismo próprio; usam a célula do hospedeiro.","id":"bio88"},{"t":"P","top":"Imunologia e saúde","f":"Imunidade de rebanho","v":"Com grande parte da população vacinada, o patógeno circula pouco e protege até quem não pode se vacinar.","id":"bio89"},{"t":"P","top":"Imunologia e saúde","f":"O que é o HIV e qual célula ele ataca?","v":"Retrovírus (RNA → DNA pela transcriptase reversa) que destrói linfócitos T CD4 (auxiliares), enfraquecendo a imunidade (aids).","id":"bio90"},{"t":"P","top":"Imunologia e saúde","f":"Dengue, zika, chikungunya e febre amarela: transmissor e prevenção","v":"Mosquito Aedes aegypti (fêmea). Prevenção: eliminar água parada (criadouros das larvas). Febre amarela tem vacina.","m":"Aedes = \"Água parada Em Dias de Sol\" → acabar com criadouros.","id":"bio91"},{"t":"P","top":"Imunologia e saúde","f":"Malária: agente e transmissor","v":"Protozoário Plasmodium, transmitido pela fêmea do mosquito Anopheles. Destrói hemácias, febre em ciclos.","id":"bio92"},{"t":"P","top":"Imunologia e saúde","f":"Doença de Chagas: agente e transmissão","v":"Protozoário Trypanosoma cruzi. Transmitido pelas fezes do barbeiro (triatomíneo) na pele ou mucosa, e por alimentos contaminados (açaí, caldo de cana).","m":"CHAgas = barbeiro CHAto que pica e defeca; o Trypanosoma entra pela ferida.","id":"bio93"},{"t":"P","top":"Imunologia e saúde","f":"Esquistossomose: agente e ciclo","v":"Verme Schistosoma mansoni. Hospedeiro intermediário: caramujo Biomphalaria. A cercária penetra na pele em água doce contaminada (\"barriga d'água\"). Prevenção: saneamento.","m":"\"Barriga d'água\" pega na água: caramujo + pele na lagoa contaminada.","id":"bio94"},{"t":"P","top":"Imunologia e saúde","f":"Teníase x cisticercose","v":"Teníase: comer carne de porco ou boi malcozida com cisticercos (adulto no intestino). Cisticercose: ingerir OVOS da Taenia solium (água e verduras contaminadas), larvas vão a músculos e cérebro.","id":"bio95"},{"t":"P","top":"Imunologia e saúde","f":"Leptospirose: agente e transmissão","v":"Bactéria Leptospira, na urina de ratos. Contato com água de enchente e esgoto.","id":"bio96"},{"t":"P","top":"Imunologia e saúde","f":"Doenças causadas por bactérias mais cobradas","v":"Tuberculose, hanseníase, cólera, tétano, leptospirose, sífilis, gonorreia, coqueluche, meningite bacteriana.","id":"bio97"},{"t":"P","top":"Botânica e diversidade","f":"Briófitas, pteridófitas, gimnospermas, angiospermas: o que cada grupo \"inventa\"?","v":"Briófitas: sem vasos (musgos). Pteridófitas: vasos condutores (samambaias). Gimnospermas: sementes nuas (pinheiros, araucária). Angiospermas: flores e frutos.","m":"\"Musgo sem Vaso, Samambaia com Vaso, Pinheiro com Semente, Angiosperma com Fruto\" (V-S-F na ordem).","id":"bio98"},{"t":"P","top":"Botânica e diversidade","f":"Xilema x floema","v":"Xilema: seiva bruta (água e sais) da raiz para as folhas. Floema: seiva elaborada (açúcares) das folhas para o resto da planta.","m":"XIlema = XIxi da planta: sobe água (seiva bruta). FLOema = FLuxo de açúcar (seiva elaborada) que desce.","id":"bio99"},{"t":"P","top":"Botânica e diversidade","f":"Função dos estômatos","v":"Trocas gasosas e transpiração. Abrem com luz e água disponível; fecham na falta de água para evitar perda.","id":"bio100"},{"t":"P","top":"Botânica e diversidade","f":"Hormônios vegetais: auxina e etileno","v":"Auxina: crescimento, fototropismo (cresce em direção à luz) e dominância apical. Etileno: amadurecimento dos frutos (por isso banana madura acelera as outras).","m":"Etileno = \"Esconde a banana madura no saco com a verde e ela amadurece\".","id":"bio101"},{"t":"P","top":"Botânica e diversidade","f":"Fungos: características principais","v":"Eucariontes heterotróficos por absorção, parede de quitina, reserva glicogênio. Decompositores, fazem fermentação (leveduras) e antibióticos (Penicillium).","id":"bio102"},{"t":"P","top":"Botânica e diversidade","f":"Vírus: por que se diz que não são seres vivos \"completos\"?","v":"São acelulares, sem metabolismo próprio: só se reproduzem dentro de células (parasitas intracelulares obrigatórios).","id":"bio103"},{"t":"C","top":"Ecologia","f":"Na fixação biológica do nitrogênio, bactérias do gênero ⟦1⟧ vivem em nódulos nas raízes de ⟦2⟧ (feijão, soja).","l":{"1":"Rhizobium","2":"leguminosas"},"id":"bio104"},{"t":"C","top":"Ecologia","f":"Na eutrofização, a decomposição das algas mortas por bactérias ⟦1⟧ reduz o ⟦2⟧ e aumenta a ⟦3⟧.","l":{"1":"aeróbias","2":"oxigênio dissolvido","3":"DBO"},"id":"bio105"},{"t":"C","top":"Ecologia","f":"Na cadeia alimentar, a energia é ⟦1⟧ (não volta), enquanto a matéria é ⟦2⟧ (decompositores devolvem ao ambiente).","l":{"1":"unidirecional","2":"cíclica"},"id":"bio106"},{"t":"C","top":"Ecologia","f":"Comunidade final e estável de uma sucessão ecológica: ⟦1⟧. Primeiros colonizadores de rocha nua: ⟦2⟧.","l":{"1":"clímax","2":"liquens"},"id":"bio107"},{"t":"C","top":"Ecologia","f":"Gases do efeito estufa: ⟦1⟧, ⟦2⟧ e vapor d'água. A destruição da camada de ozônio é causada pelos ⟦3⟧.","l":{"1":"CO2","2":"metano (CH4)","3":"CFCs"},"id":"bio108"},{"t":"R","top":"Ecologia","f":"Predatismo","v":"Relação +/-: um animal mata e come o outro (onça e capivara).","id":"bio109"},{"t":"R","top":"Ecologia","f":"Parasitismo","v":"Relação +/-: um vive à custa do outro sem matá-lo rápido (carrapato e cão).","id":"bio110"},{"t":"R","top":"Ecologia","f":"Herbivoria","v":"Animal se alimentando de planta (+/-).","id":"bio111"},{"t":"V","top":"Ecologia","f":"A pirâmide de biomassa nunca pode ser invertida.","ok":false,"x":"Pode inverter no mar: o fitoplâncton tem pouca biomassa em um dado momento, mas se reproduz muito rápido. Quem NUNCA inverte é a de energia.","id":"bio112"},{"t":"V","top":"Ecologia","f":"Os decompositores ocupam o último nível trófico da cadeia.","ok":false,"x":"Decompositores atuam em TODOS os níveis, reciclando a matéria de qualquer ser morto.","id":"bio113"},{"t":"F","top":"Citologia e bioquímica","f":"Identifique as estruturas 1 a 5.","v":"1: <b>núcleo</b> (com nucléolo). 2: <b>mitocôndria</b> (respiração, ATP). 3: <b>complexo golgiense</b> (empacota e secreta). 4: <b>lisossomo</b> (digestão intracelular). 5: <b>ribossomos</b> (síntese de proteínas).","img":"bio_celula_rotulos","id":"bio114"},{"t":"F","top":"Citologia e bioquímica","f":"Por que a hemácia da direita pode estourar?","v":"Ela está em meio <b>hipotônico</b> (menos concentrado): a água entra por osmose e, como a célula animal não tem parede celular, ela pode romper (hemólise).","img":"bio_osmose","id":"bio115"},{"t":"C","top":"Citologia e bioquímica","f":"Organela da respiração celular: ⟦1⟧. Organela da fotossíntese: ⟦2⟧. Organela da síntese de proteínas: ⟦3⟧.","l":{"1":"mitocôndria","2":"cloroplasto","3":"ribossomo"},"id":"bio116"},{"t":"C","top":"Citologia e bioquímica","f":"Respiração aeróbia: glicose + ⟦1⟧ → ⟦2⟧ + H2O + energia (ATP).","l":{"1":"O2","2":"CO2"},"id":"bio117"},{"t":"C","top":"Citologia e bioquímica","f":"Fermentação alcoólica produz ⟦1⟧ e ⟦2⟧; fermentação lática produz ⟦3⟧. Ambas rendem apenas ⟦4⟧ ATP.","l":{"1":"etanol","2":"CO2","3":"ácido lático","4":"2"},"id":"bio118"},{"t":"C","top":"Citologia e bioquímica","f":"A parede celular vegetal é feita de ⟦1⟧; a dos fungos, de ⟦2⟧.","l":{"1":"celulose","2":"quitina"},"id":"bio119"},{"t":"D","top":"Citologia e bioquímica","f":"Qual é o saldo de ATP da fermentação por molécula de glicose?","v":"2","x":"Só a glicólise, sem mitocôndria.","id":"bio120"},{"t":"D","top":"Citologia e bioquímica","f":"Qual organela faz a digestão intracelular?","v":"lisossomo","x":"Enzimas hidrolíticas; também faz autofagia.","id":"bio121"},{"t":"V","top":"Citologia e bioquímica","f":"Bactérias não têm ribossomos porque são procariontes.","ok":false,"x":"Bactérias TÊM ribossomos (menores, 70S). O que falta nelas é núcleo e organelas membranosas.","id":"bio122"},{"t":"V","top":"Citologia e bioquímica","f":"Enzimas são consumidas durante a reação que catalisam.","ok":false,"x":"Enzimas não são consumidas: podem ser reutilizadas. Mas desnaturam com calor ou pH inadequado.","id":"bio123"},{"t":"C","top":"Genética","f":"No DNA, adenina pareia com ⟦1⟧ e citosina com ⟦2⟧. No RNA, a timina é substituída por ⟦3⟧.","l":{"1":"timina","2":"guanina","3":"uracila"},"id":"bio124"},{"t":"C","top":"Genética","f":"O processo DNA → RNAm chama-se ⟦1⟧ e ocorre no ⟦2⟧; RNAm → proteína chama-se ⟦3⟧ e ocorre no ⟦4⟧.","l":{"1":"transcrição","2":"núcleo","3":"tradução","4":"ribossomo"},"id":"bio125"},{"t":"C","top":"Genética","f":"Cruzamento Aa x Aa gera proporção fenotípica ⟦1⟧ e genotípica ⟦2⟧.","l":{"1":"3:1","2":"1:2:1"},"id":"bio126"},{"t":"C","top":"Genética","f":"A chance de um casal Aa x Aa ter um filho aa é ⟦1⟧; e de ser menino E aa é ⟦2⟧.","l":{"1":"1/4","2":"1/8"},"id":"bio127"},{"t":"D","top":"Genética","f":"Proporção fenotípica do cruzamento AaBb x AaBb (genes independentes)?","v":"9:3:3:1","x":"Use o quadro de Punnett 4x4 ou multiplique (3:1) x (3:1).","id":"bio128"},{"t":"D","top":"Genética","f":"Qual o tipo sanguíneo doador universal (ABO)?","v":"O","x":"Não tem aglutinogênios A nem B nas hemácias.","id":"bio129"},{"t":"F","top":"Genética","f":"Qual a probabilidade de um descendente ser aabb?","v":"1/16 (só o quadrado vermelho). Multiplicando: 1/4 (aa) x 1/4 (bb) = 1/16.","img":"bio_punnett_di","id":"bio130"},{"t":"V","top":"Genética","f":"Uma pessoa com sangue AB tem anticorpos anti-A e anti-B no plasma.","ok":false,"x":"AB não tem nenhum dos dois anticorpos; por isso é receptor universal.","id":"bio131"},{"t":"V","top":"Genética","f":"Daltonismo é mais comum em mulheres porque elas têm dois cromossomos X.","ok":false,"x":"É mais comum em HOMENS: com um X só, basta um alelo recessivo para manifestar.","id":"bio132"},{"t":"C","top":"Evolução","f":"Segundo Darwin, o mecanismo da evolução é a ⟦1⟧; a teoria sintética acrescenta ⟦2⟧ e ⟦3⟧ como fontes de variabilidade.","l":{"1":"seleção natural","2":"mutação","3":"recombinação gênica"},"id":"bio133"},{"t":"C","top":"Evolução","f":"Asa de morcego e braço humano são órgãos ⟦1⟧ (divergência evolutiva); asa de inseto e asa de ave são ⟦2⟧ (convergência evolutiva).","l":{"1":"homólogos","2":"análogos"},"id":"bio134"},{"t":"V","top":"Evolução","f":"Girafas desenvolveram pescoço longo de tanto esticá-lo, e passaram isso aos filhos.","ok":false,"x":"Essa é a ideia de Lamarck. Para Darwin, girafas que já nasciam com pescoço maior sobreviviam mais e deixavam mais filhos.","id":"bio135"},{"t":"F","top":"Fisiologia humana","f":"Descreva a pequena circulação seguindo os números.","v":"<b>VD</b> → artéria pulmonar (sangue venoso) → <b>pulmões</b> (hematose) → veias pulmonares (sangue arterial) → <b>AE</b>. Depois AE → VE e começa a grande circulação.","img":"bio_circulacao","id":"bio136"},{"t":"C","top":"Fisiologia humana","f":"O sangue sai do ventrículo ⟦1⟧ pela artéria ⟦2⟧ e volta ao átrio ⟦3⟧ pelas veias ⟦4⟧.","l":{"1":"esquerdo","2":"aorta","3":"direito","4":"cavas"},"id":"bio137"},{"t":"C","top":"Fisiologia humana","f":"O hormônio ⟦1⟧ aumenta a reabsorção de água nos rins; o álcool ⟦2⟧ esse hormônio, aumentando a urina.","l":{"1":"ADH","2":"inibe"},"id":"bio138"},{"t":"C","top":"Fisiologia humana","f":"A pílula anticoncepcional inibe a liberação de ⟦1⟧ e ⟦2⟧, impedindo a ⟦3⟧.","l":{"1":"FSH","2":"LH","3":"ovulação"},"id":"bio139"},{"t":"C","top":"Fisiologia humana","f":"A troca gasosa nos alvéolos chama-se ⟦1⟧ e ocorre por ⟦2⟧.","l":{"1":"hematose","2":"difusão"},"id":"bio140"},{"t":"D","top":"Fisiologia humana","f":"Que hormônio é detectado no teste de gravidez?","v":"hCG","x":"Gonadotrofina coriônica humana, produzida pelo embrião/placenta.","id":"bio141"},{"t":"D","top":"Fisiologia humana","f":"Qual hormônio pancreático aumenta a glicemia?","v":"glucagon","x":"Quebra o glicogênio do fígado em glicose.","id":"bio142"},{"t":"V","top":"Fisiologia humana","f":"A artéria pulmonar transporta sangue rico em oxigênio.","ok":false,"x":"Transporta sangue VENOSO (pobre em O2) do ventrículo direito para os pulmões. Artéria = sai do coração, não importa o tipo de sangue.","id":"bio143"},{"t":"V","top":"Fisiologia humana","f":"A bile é uma enzima que digere gorduras.","ok":false,"x":"A bile NÃO é enzima: ela emulsifica a gordura (quebra em gotículas) para a lipase agir.","id":"bio144"},{"t":"F","top":"Imunologia e saúde","f":"Qual curva representa o soro e por que ela cai?","v":"A <b>vermelha</b>. O soro traz anticorpos prontos (imunização passiva): age na hora, mas os anticorpos são degradados e não há memória.","img":"bio_vacina_soro","id":"bio145"},{"t":"R","top":"Imunologia e saúde","f":"Vírus → doenças","v":"Gripe, covid-19, dengue, zika, chikungunya, febre amarela, sarampo, HIV/aids, HPV, hepatites, raiva.","id":"bio146"},{"t":"R","top":"Imunologia e saúde","f":"Protozoários → doenças","v":"Malária, doença de Chagas, leishmaniose, toxoplasmose, amebíase, giardíase.","id":"bio147"},{"t":"R","top":"Imunologia e saúde","f":"Vermes (helmintos) → doenças","v":"Esquistossomose, teníase/cisticercose, ascaridíase (lombriga), ancilostomose (amarelão), filariose (elefantíase).","id":"bio148"},{"t":"C","top":"Imunologia e saúde","f":"A malária é causada pelo protozoário ⟦1⟧ e transmitida pela fêmea do mosquito ⟦2⟧.","l":{"1":"Plasmodium","2":"Anopheles"},"id":"bio149"},{"t":"C","top":"Imunologia e saúde","f":"A leptospirose é causada por ⟦1⟧ e transmitida pela ⟦2⟧, comum em ⟦3⟧.","l":{"1":"bactéria","2":"urina de ratos","3":"enchentes"},"id":"bio150"},{"t":"C","top":"Imunologia e saúde","f":"A cisticercose humana ocorre ao ingerir ⟦1⟧ de Taenia solium; a teníase, ao comer ⟦2⟧ com cisticercos.","l":{"1":"ovos","2":"carne de porco malcozida"},"id":"bio151"},{"t":"D","top":"Imunologia e saúde","f":"Que mosquito transmite dengue, zika e chikungunya?","v":"Aedes aegypti","x":"Prevenção: eliminar água parada.","id":"bio152"},{"t":"V","top":"Imunologia e saúde","f":"Tomar antibiótico ajuda a curar a gripe mais rápido.","ok":false,"x":"Gripe é causada por vírus; antibióticos agem só em bactérias. O uso desnecessário seleciona bactérias resistentes.","id":"bio153"},{"t":"C","top":"Botânica e diversidade","f":"Seiva bruta sobe pelo ⟦1⟧; seiva elaborada é distribuída pelo ⟦2⟧.","l":{"1":"xilema","2":"floema"},"id":"bio154"},{"t":"C","top":"Botânica e diversidade","f":"Grupo de plantas com flores e frutos: ⟦1⟧. Com sementes nuas: ⟦2⟧. Primeiras com vasos condutores: ⟦3⟧.","l":{"1":"angiospermas","2":"gimnospermas","3":"pteridófitas"},"id":"bio155"},{"t":"D","top":"Botânica e diversidade","f":"Que hormônio vegetal acelera o amadurecimento dos frutos?","v":"etileno","x":"Um gás; frutas maduras liberam e aceleram as vizinhas.","id":"bio156"}]},{"id":"qui","nome":"Química","ic":"⚗️","cards":[{"t":"P","top":"Química geral e atomística","f":"Número atômico (Z), número de massa (A) e nêutrons","v":"Z = prótons. A = prótons + nêutrons. Nêutrons = A - Z.","id":"qui0"},{"t":"P","top":"Química geral e atomística","f":"Isótopos, isóbaros e isótonos","v":"IsótoPos: mesmo nº de Prótons (mesmo elemento). IsóbAros: mesma massa (A). IsótoNos: mesmo nº de Nêutrons.","m":"isótoPos = Prótons, isóbAros = mAssa, isótoNos = Nêutrons.","id":"qui1"},{"t":"P","top":"Química geral e atomística","f":"Cátion x ânion","v":"Cátion: perdeu elétrons, carga positiva (metais tendem a formar). Ânion: ganhou elétrons, carga negativa (ametais).","m":"CátIon = \"gaTo positivo\" (perdeu elétron, +). ÂNIon = \"Ânimo Negativo\" (ganhou elétron, −).","id":"qui2"},{"t":"P","top":"Química geral e atomística","f":"Propriedades periódicas: raio atômico","v":"Aumenta para baixo no grupo (mais camadas) e para a esquerda no período (menos prótons puxando). Frâncio é o maior.","m":"Raio cresce para o canto inferior esquerdo (Frâncio); eletronegatividade para o superior direito (Flúor). As setas são opostas.","img":"qui_tabela_tendencias","id":"qui3"},{"t":"P","top":"Química geral e atomística","f":"Eletronegatividade: tendência na tabela","v":"Aumenta para cima e para a direita. Ordem a decorar: F &gt; O &gt; N &gt; Cl &gt; Br &gt; I &gt; S &gt; C &gt; P &gt; H (\"Fui Ontem No Clube, Briguei, I Saí Correndo Para Hospital\").","m":"","img":"qui_tabela_tendencias","id":"qui4"},{"t":"P","top":"Química geral e atomística","f":"Ligação iônica, covalente e metálica","v":"Iônica: metal + ametal, transferência de elétrons (NaCl). Covalente: ametal + ametal, compartilhamento (H2O). Metálica: metal + metal, \"mar de elétrons\" (conduz eletricidade).","id":"qui5"},{"t":"P","top":"Química geral e atomística","f":"Propriedades de compostos iônicos","v":"Sólidos com altos pontos de fusão; conduzem corrente quando fundidos ou em solução aquosa (íons livres), não no estado sólido.","id":"qui6"},{"t":"P","top":"Química geral e atomística","f":"Molécula polar x apolar","v":"Polar: momento dipolar resultante diferente de zero (H2O, NH3, HCl). Apolar: dipolos se anulam (CO2, CH4, O2). \"Semelhante dissolve semelhante\".","id":"qui7"},{"t":"P","top":"Química geral e atomística","f":"Forças intermoleculares em ordem de intensidade","v":"Ligação de hidrogênio (H ligado a F, O ou N) &gt; dipolo-dipolo &gt; dipolo induzido (London). Mais forte = maior ponto de ebulição.","m":"Ligação de hidrogênio só com \"FON\": H ligado a F, O ou N.","id":"qui8"},{"t":"P","top":"Química geral e atomística","f":"Por que a água tem ponto de ebulição alto para uma molécula tão pequena?","v":"Ligações de hidrogênio entre as moléculas.","id":"qui9"},{"t":"P","top":"Química geral e atomística","f":"Por que o gelo flutua?","v":"As ligações de hidrogênio organizam o gelo numa estrutura hexagonal com espaços vazios: o gelo é menos denso que a água líquida.","id":"qui10"},{"t":"P","top":"Química geral e atomística","f":"Alotropia: exemplos do carbono e oxigênio","v":"Carbono: grafite (conduz, macio), diamante (duro, isolante), fulereno, grafeno. Oxigênio: O2 e O3 (ozônio).","id":"qui11"},{"t":"P","top":"Química geral e atomística","f":"Separação de misturas: destilação simples x fracionada","v":"Simples: sólido dissolvido em líquido (água e sal). Fracionada: líquidos miscíveis com pontos de ebulição diferentes (petróleo, álcool e água).","m":"Destilação separa por PONTO DE EBULIÇÃO; decantação e centrifugação por DENSIDADE; filtração por TAMANHO.","id":"qui12"},{"t":"P","top":"Química geral e atomística","f":"Separação de misturas: decantação, filtração, centrifugação","v":"Decantação: sólido-líquido ou líquidos imiscíveis (funil de bromo para água e óleo). Filtração: sólido retido no filtro. Centrifugação: acelera a decantação (separar plasma do sangue).","id":"qui13"},{"t":"P","top":"Química geral e atomística","f":"Etapas do tratamento de água","v":"Coagulação/floculação (sulfato de alumínio forma flocos), decantação, filtração (areia e cascalho), desinfecção (cloro) e fluoretação.","m":"\"Coagula, Flocula, Decanta, Filtra, Desinfeta\" (CFDFD): primeiro junta a sujeira, depois deixa cair, depois coa e mata os micróbios.","id":"qui14"},{"t":"P","top":"Química geral e atomística","f":"Mistura homogênea x heterogênea","v":"Homogênea: uma fase (água e sal dissolvido, ar). Heterogênea: duas ou mais fases (água e óleo, granito).","id":"qui15"},{"t":"P","top":"Química geral e atomística","f":"Fenômeno físico x químico","v":"Físico: não forma substância nova (mudança de estado, dissolução). Químico: forma nova substância (queima, ferrugem, cozimento).","m":"Pergunta-chave: \"surgiu substância NOVA?\" Se sim, é químico.","id":"qui16"},{"t":"P","top":"Estequiometria e soluções","f":"Quanto vale 1 mol?","v":"6,02 x 10^23 partículas (constante de Avogadro). A massa de 1 mol em gramas = massa molar.","m":"Mol é uma \"dúzia gigante\": 1 dúzia = 12, 1 mol = 6 x 10²³.","id":"qui17"},{"t":"P","top":"Estequiometria e soluções","f":"Volume molar dos gases nas CNTP","v":"22,4 L por mol (0 °C, 1 atm). Nas CATP (25 °C, 1 atm) cerca de 24,5 L.","id":"qui18"},{"t":"P","top":"Estequiometria e soluções","f":"Roteiro de estequiometria","v":"1) Escreva e balanceie a equação. 2) Relacione mols pelos coeficientes. 3) Converta para a unidade pedida (massa, volume, partículas). Atenção a pureza e rendimento.","m":"\"Balanceia, Proporciona, Converte\" e só no final confira pureza e rendimento.","id":"qui19"},{"t":"P","top":"Estequiometria e soluções","f":"Reagente limitante","v":"O que acaba primeiro e limita a quantidade de produto. O outro está em excesso. Compare a proporção estequiométrica com a quantidade disponível.","id":"qui20"},{"t":"P","top":"Estequiometria e soluções","f":"Concentração comum x molaridade","v":"Comum: C = massa do soluto (g) / volume (L). Molaridade: M = mols do soluto / volume (L). Relação: C = M x massa molar.","id":"qui21"},{"t":"P","top":"Estequiometria e soluções","f":"Diluição: fórmula","v":"C1 x V1 = C2 x V2 (a quantidade de soluto não muda, só o volume aumenta).","m":"Diluir é só pôr água: a quantidade de soluto não muda, então \"C x V antes = C x V depois\".","id":"qui22"},{"t":"P","top":"Estequiometria e soluções","f":"O que significa ppm?","v":"Partes por milhão: 1 ppm = 1 mg de soluto por kg de solução (ou cerca de 1 mg/L em água). Usado para poluentes e flúor na água.","id":"qui23"},{"t":"P","top":"Estequiometria e soluções","f":"Título e porcentagem em massa","v":"τ = massa do soluto / massa da solução. Em % basta multiplicar por 100. Ex.: álcool 70% em massa.","id":"qui24"},{"t":"P","top":"Estequiometria e soluções","f":"Propriedades coligativas: o que são?","v":"Dependem só do NÚMERO de partículas dissolvidas, não da natureza. Tonoscopia, ebulioscopia, crioscopia e osmoscopia.","m":"COLIGATIVA = conta as partículas (\"colig\" = coleção): não importa QUEM, importa QUANTAS.","id":"qui25"},{"t":"P","top":"Estequiometria e soluções","f":"Exemplos de efeito crioscópico e ebulioscópico","v":"Sal nas estradas derrete o gelo (baixa o ponto de congelamento). Água com sal ferve a temperatura maior. Aditivo no radiador.","id":"qui26"},{"t":"P","top":"Estequiometria e soluções","f":"Por que NaCl tem efeito coligativo maior que a glicose na mesma concentração?","v":"NaCl se dissocia em 2 íons (Na+ e Cl-), dobrando o número de partículas. Glicose não se dissocia.","id":"qui27"},{"t":"P","top":"Físico-química","f":"Reação exotérmica x endotérmica","v":"Exo: libera calor, ΔH &lt; 0 (combustão). Endo: absorve calor, ΔH &gt; 0 (fotossíntese, derreter gelo, compressa fria).","m":"EXOtérmica = calor EXIT (sai), ΔH negativo. ENDOtérmica = calor ENTRA, ΔH positivo.","img":"qui_entalpia","id":"qui28"},{"t":"P","top":"Físico-química","f":"Lei de Hess","v":"O ΔH de uma reação depende só dos estados inicial e final. Pode-se somar equações (inverter troca o sinal; multiplicar multiplica o ΔH).","id":"qui29"},{"t":"P","top":"Físico-química","f":"Fatores que aumentam a velocidade de reação","v":"Maior temperatura, maior concentração, maior superfície de contato (comprimido em pó dissolve mais rápido) e catalisador.","id":"qui30"},{"t":"P","top":"Físico-química","f":"Como age o catalisador?","v":"Diminui a energia de ativação, acelerando a reação. Não é consumido e NÃO altera o ΔH nem o equilíbrio (só faz chegar a ele mais rápido).","m":"Catalisador é um \"atalho na montanha\": diminui a subida (energia de ativação), mas não muda o ponto de partida nem o de chegada (ΔH).","img":"qui_entalpia","id":"qui31"},{"t":"P","top":"Físico-química","f":"Por que guardar alimentos na geladeira os conserva?","v":"Temperatura menor diminui a velocidade das reações químicas e da atividade microbiana.","id":"qui32"},{"t":"P","top":"Físico-química","f":"Princípio de Le Chatelier","v":"Um sistema em equilíbrio perturbado se desloca para minimizar a perturbação (concentração, pressão, temperatura).","id":"qui33"},{"t":"P","top":"Físico-química","f":"Le Chatelier: efeito da pressão","v":"Aumentar pressão desloca para o lado com MENOR número de mols de gás. Diminuir, para o lado com mais mols.","m":"\"Apertou, vai para onde tem menos gás.\"","id":"qui34"},{"t":"P","top":"Físico-química","f":"Le Chatelier: efeito da temperatura","v":"Aumentar a temperatura favorece o sentido endotérmico. Diminuir favorece o exotérmico. Temperatura é o único fator que muda o valor de K.","m":"\"Esquentou, favorece quem ABSORVE calor (endo).\"","id":"qui35"},{"t":"P","top":"Físico-química","f":"Escala de pH","v":"pH = -log[H+]. pH &lt; 7 ácido, = 7 neutro, &gt; 7 básico (a 25 °C). pH + pOH = 14. Cada unidade = fator 10 na [H+].","m":"pH baixo = muito H+ = ácido. Cada 1 de pH = 10x.","img":"qui_ph","id":"qui36"},{"t":"P","top":"Físico-química","f":"Exemplo: pH 3 x pH 5","v":"A solução de pH 3 tem [H+] 100 vezes maior (10^-3 x 10^-5).","id":"qui37"},{"t":"P","top":"Físico-química","f":"Ácidos e bases de Arrhenius","v":"Ácido libera H+ (H3O+) em água. Base libera OH-. Neutralização: ácido + base → sal + água.","id":"qui38"},{"t":"P","top":"Físico-química","f":"Hidrólise salina: pH de sais","v":"Ácido forte + base fraca → sal ácido (NH4Cl). Ácido fraco + base forte → sal básico (NaHCO3, Na2CO3). Forte + forte → neutro (NaCl).","id":"qui39"},{"t":"P","top":"Físico-química","f":"Por que o bicarbonato de sódio alivia a azia?","v":"É um sal de caráter básico (hidrólise) que neutraliza o excesso de HCl no estômago.","id":"qui40"},{"t":"P","top":"Físico-química","f":"Calagem do solo","v":"Adição de calcário (CaCO3) ou cal para neutralizar a acidez do solo e corrigir o pH.","id":"qui41"},{"t":"P","top":"Físico-química","f":"Pilha (célula galvânica): ânodo e cátodo","v":"Ânodo: polo negativo, OXIDAÇÃO (perde elétrons, a placa corrói). Cátodo: polo positivo, REDUÇÃO (ganha elétrons, a placa engrossa). Elétrons vão do ânodo ao cátodo.","m":"\"ÂNODO OXIDA, CÁTODO REDUZ\" (vogais com vogais, consoantes com consoantes: Ânodo-Oxidação, Cátodo-Redução).","img":"qui_pilha","id":"qui42"},{"t":"P","top":"Físico-química","f":"Potencial de redução e quem oxida","v":"Maior E° de redução → reduz (cátodo). Menor E° → oxida (ânodo). ddp = E°maior - E°menor.","id":"qui43"},{"t":"P","top":"Físico-química","f":"Oxidação e redução: definição","v":"Oxidação: perde elétrons, NOX aumenta (agente redutor). Redução: ganha elétrons, NOX diminui (agente oxidante). \"Quem oxida é redutor\".","m":"\"PERDEU é OXIDOU\": quem perde elétrons oxida. \"GANHOU REDUZ\" (a carga reduz, fica mais negativa).","id":"qui44"},{"t":"P","top":"Físico-química","f":"Metal de sacrifício","v":"Metal mais reativo (menor potencial de redução, ex.: zinco ou magnésio) é ligado ao ferro para oxidar no lugar dele. Ex.: cascos de navio, galvanização.","id":"qui45"},{"t":"P","top":"Físico-química","f":"Eletrólise: o que é?","v":"Processo NÃO espontâneo: usa corrente elétrica para provocar reação redox. Usada para obter alumínio, cloro, soda, galvanoplastia (cromar, niquelar).","id":"qui46"},{"t":"P","top":"Físico-química","f":"Radioatividade: partículas alfa, beta e gama","v":"Alfa: núcleo de He (2p+2n), pouco penetrante, A -4 e Z -2. Beta: elétron, Z +1, A igual. Gama: onda eletromagnética, muito penetrante, sem massa.","m":"Alfa é \"gordinha\" (He, para no papel); beta passa o papel mas para no alumínio; gama atravessa quase tudo.","img":"qui_radiacao","id":"qui47"},{"t":"P","top":"Físico-química","f":"Meia-vida: definição e cálculo","v":"Tempo para metade dos núcleos decair. Após n meias-vidas sobra m0 / 2^n. Ex.: 3 meias-vidas → 1/8.","m":"Cada meia-vida corta pela metade: 100 → 50 → 25 → 12,5.","img":"qui_meia_vida","id":"qui48"},{"t":"P","top":"Físico-química","f":"Datação por carbono-14","v":"C-14 tem meia-vida de ~5.730 anos; serve para datar restos de seres vivos de até ~50 mil anos.","id":"qui49"},{"t":"P","top":"Físico-química","f":"Fissão x fusão nuclear","v":"Fissão: núcleo pesado (urânio-235) se divide; usinas como Angra e bomba atômica. Fusão: núcleos leves (hidrogênio) se unem; energia do Sol.","id":"qui50"},{"t":"P","top":"Química orgânica","f":"Funções orgânicas: grupos característicos (1)","v":"Álcool: -OH em carbono saturado. Fenol: -OH no anel aromático. Aldeído: -CHO na ponta. Cetona: C=O no meio. Ácido carboxílico: -COOH.","m":"","img":"qui_funcoes","id":"qui51"},{"t":"P","top":"Química orgânica","f":"Funções orgânicas: grupos característicos (2)","v":"Éster: -COO- entre carbonos (aromas, gorduras). Éter: -O- entre carbonos. Amina: -NH2 (derivado da amônia). Amida: -CONH2.","m":"ÉSTER tem \"dois O\" (–COO–), ÉTER tem \"um O\" (–O–): éster é o maior nome, tem mais oxigênio.","img":"qui_funcoes","id":"qui52"},{"t":"P","top":"Química orgânica","f":"Prefixos de cadeia carbônica","v":"1 met, 2 et, 3 prop, 4 but, 5 pent, 6 hex, 7 hept, 8 oct. Infixo: an (simples), en (dupla), in (tripla).","m":"\"MET-ET-PROP-BUT\" decore como \"Meu Elefante Pula Bonito\"; de 5 em diante é igual ao grego (pent, hex...).","id":"qui53"},{"t":"P","top":"Química orgânica","f":"Isomeria: o que é e tipos","v":"Mesma fórmula molecular, estruturas diferentes. Plana: cadeia, posição, função, metameria, tautomeria. Espacial: geométrica (cis-trans) e óptica.","id":"qui54"},{"t":"P","top":"Química orgânica","f":"Isomeria geométrica (cis-trans): condição","v":"Dupla ligação (ou ciclo) com cada carbono ligado a dois grupos diferentes. Cis: grupos iguais do mesmo lado; trans: lados opostos.","id":"qui55"},{"t":"P","top":"Química orgânica","f":"Isomeria óptica: condição","v":"Carbono quiral (assimétrico): ligado a 4 grupos diferentes. Gera enantiômeros que desviam a luz polarizada. Importante em fármacos (talidomida).","m":"Carbono quiral = \"4 vizinhos diferentes\", como uma mão: a imagem no espelho não se sobrepõe.","id":"qui56"},{"t":"P","top":"Química orgânica","f":"Esterificação","v":"Ácido carboxílico + álcool → éster + água. Reação reversível. Ésteres dão aroma de frutas.","id":"qui57"},{"t":"P","top":"Química orgânica","f":"Saponificação","v":"Gordura/óleo (triglicerídeo) + base forte (NaOH) → sabão (sal de ácido graxo) + glicerol.","m":"SAPOnificação = faz SAbãO: gordura + base.","id":"qui58"},{"t":"P","top":"Química orgânica","f":"Como o sabão limpa a gordura?","v":"A molécula tem cauda apolar (cadeia longa, se liga à gordura) e cabeça polar (iônica, se liga à água). Forma micelas que envolvem a gordura.","m":"Sabão é um \"cabo de guerra\": cabeça na água, cauda na gordura.","img":"qui_micela","id":"qui59"},{"t":"P","top":"Química orgânica","f":"Transesterificação e biodiesel","v":"Óleo vegetal ou gordura + álcool (metanol ou etanol), com catalisador → biodiesel (ésteres) + glicerina.","id":"qui60"},{"t":"P","top":"Química orgânica","f":"Polímeros de adição x condensação","v":"Adição: monômeros com dupla ligação se somam sem perder nada (polietileno, PVC, isopor). Condensação: monômeros se unem liberando molécula pequena, como água (PET, náilon).","m":"Condensação \"condensa\" água: libera molécula pequena. Adição só \"soma\" monômeros.","id":"qui61"},{"t":"P","top":"Química orgânica","f":"Por que plásticos comuns causam problema ambiental?","v":"São muito estáveis e quase não biodegradáveis; persistem por séculos e geram microplásticos. Alternativas: reciclagem, plásticos biodegradáveis (PLA).","id":"qui62"},{"t":"P","top":"Química orgânica","f":"Combustão completa x incompleta","v":"Completa: combustível + O2 suficiente → CO2 + H2O. Incompleta: pouco O2 → CO (tóxico) e/ou C (fuligem).","m":"Falta de ar → CO (monóxido, mata) e fuligem. Ar sobrando → CO2 + H2O.","id":"qui63"},{"t":"P","top":"Química orgânica","f":"Etanol x gasolina como combustível","v":"Etanol: renovável (cana), CO2 emitido é reabsorvido no plantio, menos poluentes de enxofre. Gasolina: fóssil, rende mais energia por litro.","id":"qui64"},{"t":"P","top":"Química orgânica","f":"Destilação fracionada do petróleo","v":"Separa frações por ponto de ebulição: gás (GLP), gasolina, querosene, diesel, óleos lubrificantes, e o resíduo (asfalto, piche).","m":"Quanto mais leve a fração, mais alto ela sai na torre (gás no topo, asfalto embaixo).","img":"qui_petroleo","id":"qui65"},{"t":"P","top":"Química orgânica","f":"Hidrocarbonetos: características gerais","v":"Só C e H, apolares, insolúveis em água, menos densos que ela. Principal fonte: petróleo e gás natural (metano).","id":"qui66"},{"t":"P","top":"Química orgânica","f":"Biomoléculas: gordura saturada x insaturada","v":"Saturada: só ligações simples, sólida à temperatura ambiente (gordura animal). Insaturada: duplas ligações, líquida (óleos vegetais). Hidrogenação transforma óleo em margarina.","id":"qui67"},{"t":"P","top":"Química orgânica","f":"Química verde: ideias centrais","v":"Prevenir resíduos, usar matérias-primas renováveis, catalisadores, solventes menos tóxicos, economia de átomos e eficiência energética.","id":"qui68"},{"t":"P","top":"Química orgânica","f":"Métodos de reciclagem ou destino de lixo mais cobrados","v":"Aterro sanitário (impermeabilizado, trata o chorume e o gás) é melhor que lixão. Compostagem: matéria orgânica vira adubo. Incineração reduz volume mas emite gases.","id":"qui69"},{"t":"F","top":"Química geral e atomística","f":"Qual elemento tem o maior raio e qual tem a maior eletronegatividade?","v":"<b>Maior raio:</b> frâncio (Fr), no canto inferior esquerdo. <b>Maior eletronegatividade:</b> flúor (F), no canto superior direito (gases nobres não entram).","img":"qui_tabela_tendencias","id":"qui70"},{"t":"C","top":"Química geral e atomística","f":"Número de massa A = número de ⟦1⟧ + número de ⟦2⟧. O número atômico Z é o número de ⟦3⟧.","l":{"1":"prótons","2":"nêutrons","3":"prótons"},"id":"qui71"},{"t":"C","top":"Química geral e atomística","f":"Ligação ⟦1⟧: metal + ametal, transfere elétrons. Ligação ⟦2⟧: ametal + ametal, compartilha elétrons. Ligação ⟦3⟧: \"mar de elétrons\".","l":{"1":"iônica","2":"covalente","3":"metálica"},"id":"qui72"},{"t":"C","top":"Química geral e atomística","f":"Moléculas ⟦1⟧ dissolvem-se em solventes polares, e apolares em apolares: \"semelhante dissolve ⟦2⟧\".","l":{"1":"polares","2":"semelhante"},"id":"qui73"},{"t":"C","top":"Química geral e atomística","f":"Para separar água e óleo usa-se o funil de ⟦1⟧; para separar álcool e água, a destilação ⟦2⟧.","l":{"1":"decantação (bromo)","2":"fracionada"},"id":"qui74"},{"t":"D","top":"Química geral e atomística","f":"Elemento mais eletronegativo da tabela periódica?","v":"flúor","x":"Topo direito (gases nobres à parte).","id":"qui75"},{"t":"D","top":"Química geral e atomística","f":"Nêutrons de um átomo com A = 23 e Z = 11?","v":"12","x":"n = A − Z = 23 − 11.","id":"qui76"},{"t":"V","top":"Química geral e atomística","f":"Compostos iônicos conduzem corrente elétrica no estado sólido.","ok":false,"x":"Só conduzem fundidos ou dissolvidos em água, quando os íons ficam livres para se mover.","id":"qui77"},{"t":"V","top":"Química geral e atomística","f":"O gelo flutua porque é mais denso que a água líquida.","ok":false,"x":"Flutua porque é MENOS denso: as ligações de hidrogênio formam uma rede com espaços vazios.","id":"qui78"},{"t":"C","top":"Estequiometria e soluções","f":"A concentração comum é C = ⟦1⟧ / ⟦2⟧; a molaridade é M = ⟦3⟧ / volume (L).","l":{"1":"massa do soluto","2":"volume da solução","3":"mols do soluto"},"id":"qui79"},{"t":"C","top":"Estequiometria e soluções","f":"Na diluição vale C1·V1 = ⟦1⟧, pois a quantidade de ⟦2⟧ permanece constante.","l":{"1":"C2·V2","2":"soluto"},"id":"qui80"},{"t":"C","top":"Estequiometria e soluções","f":"Nas CNTP, 1 mol de qualquer gás ocupa ⟦1⟧ L.","l":{"1":"22,4"},"id":"qui81"},{"t":"D","top":"Estequiometria e soluções","f":"Quantas partículas há em 1 mol?","v":"6,02 x 10^23","x":"Constante de Avogadro.","id":"qui82"},{"t":"D","top":"Estequiometria e soluções","f":"Uma solução de 2 L contém 0,5 mol de soluto. Qual a molaridade (mol/L)?","v":"0,25","x":"M = n / V = 0,5 / 2.","id":"qui83"},{"t":"V","top":"Estequiometria e soluções","f":"1 mol de NaCl e 1 mol de glicose dissolvidos em 1 L de água baixam igualmente o ponto de congelamento.","ok":false,"x":"NaCl se dissocia em 2 íons: tem o dobro de partículas, então o efeito coligativo é aproximadamente o dobro.","id":"qui84"},{"t":"F","top":"Físico-química","f":"O que a linha tracejada mostra e o que ela NÃO muda?","v":"A reação <b>com catalisador</b>: o pico (energia de ativação) fica mais baixo. Ela <b>não muda o ΔH</b>, porque reagentes e produtos continuam no mesmo nível de energia.","img":"qui_entalpia","id":"qui85"},{"t":"F","top":"Físico-química","f":"Qual placa perde massa e para onde vão os elétrons?","v":"A de <b>zinco</b> (ânodo, oxida e corrói). Os elétrons vão pelo fio <b>do zinco para o cobre</b> (cátodo), onde Cu²⁺ vira Cu e a placa engrossa.","img":"qui_pilha","id":"qui86"},{"t":"F","top":"Físico-química","f":"Uma solução de pH 2 tem quantas vezes mais H+ que uma de pH 4?","v":"<b>100 vezes</b> (10 x 10). Cada unidade de pH equivale a um fator 10.","img":"qui_ph","id":"qui87"},{"t":"C","top":"Físico-química","f":"Na pilha, o ⟦1⟧ é o polo negativo onde ocorre ⟦2⟧; o ⟦3⟧ é o polo positivo onde ocorre ⟦4⟧.","l":{"1":"ânodo","2":"oxidação","3":"cátodo","4":"redução"},"id":"qui88"},{"t":"C","top":"Físico-química","f":"Reação exotérmica tem ΔH ⟦1⟧ e ⟦2⟧ calor; endotérmica tem ΔH ⟦3⟧ e ⟦4⟧ calor.","l":{"1":"negativo","2":"libera","3":"positivo","4":"absorve"},"id":"qui89"},{"t":"C","top":"Físico-química","f":"Aumentar a temperatura favorece o sentido ⟦1⟧; aumentar a pressão desloca para o lado com ⟦2⟧.","l":{"1":"endotérmico","2":"menos mols de gás"},"id":"qui90"},{"t":"C","top":"Físico-química","f":"Sal de ácido fraco com base forte (como o bicarbonato de sódio) forma solução ⟦1⟧; sal de ácido forte com base fraca (como o NH4Cl), solução ⟦2⟧.","l":{"1":"básica","2":"ácida"},"id":"qui91"},{"t":"C","top":"Físico-química","f":"Partícula alfa: A diminui ⟦1⟧ e Z diminui ⟦2⟧. Partícula beta: Z aumenta ⟦3⟧ e A ⟦4⟧.","l":{"1":"4","2":"2","3":"1","4":"não muda"},"id":"qui92"},{"t":"D","top":"Físico-química","f":"Qual o pH de uma solução neutra a 25 °C?","v":"7","x":"pH + pOH = 14.","id":"qui93"},{"t":"D","top":"Físico-química","f":"Uma amostra de 80 g tem meia-vida de 5 anos. Quantos gramas restam após 15 anos?","v":"10","x":"15 anos = 3 meias-vidas: 80 → 40 → 20 → 10.","id":"qui94"},{"t":"V","top":"Físico-química","f":"O catalisador desloca o equilíbrio no sentido dos produtos.","ok":false,"x":"Catalisador acelera os dois sentidos igualmente: o equilíbrio chega mais rápido, mas não se desloca.","id":"qui95"},{"t":"V","top":"Físico-química","f":"Na pilha, a placa do cátodo sofre corrosão.","ok":false,"x":"Quem corrói é o ÂNODO (oxidação). O cátodo recebe metal depositado e engrossa.","id":"qui96"},{"t":"F","top":"Química orgânica","f":"Explique a figura: o que cada parte da molécula de sabão faz?","v":"A <b>cauda apolar</b> (cadeia longa) entra na gordura; a <b>cabeça polar</b> (iônica, azul) fica voltada para a água. Assim forma-se a <b>micela</b>, que é arrastada pela água levando a gordura.","img":"qui_micela","id":"qui97"},{"t":"F","top":"Química orgânica","f":"Qual fração sai no topo da torre e por quê?","v":"O <b>gás (GLP)</b>: tem o menor ponto de ebulição, então continua gasoso e sobe até o topo, que é a parte mais fria.","img":"qui_petroleo","id":"qui98"},{"t":"R","top":"Química orgânica","f":"R–OH (OH em carbono saturado)","v":"Álcool","id":"qui99"},{"t":"R","top":"Química orgânica","f":"R–CHO (carbonila na ponta)","v":"Aldeído","id":"qui100"},{"t":"R","top":"Química orgânica","f":"R–CO–R (carbonila no meio)","v":"Cetona","id":"qui101"},{"t":"R","top":"Química orgânica","f":"R–COOH","v":"Ácido carboxílico","id":"qui102"},{"t":"R","top":"Química orgânica","f":"R–COO–R","v":"Éster","id":"qui103"},{"t":"R","top":"Química orgânica","f":"R–O–R","v":"Éter","id":"qui104"},{"t":"R","top":"Química orgânica","f":"R–NH2","v":"Amina","id":"qui105"},{"t":"R","top":"Química orgânica","f":"R–CONH2","v":"Amida","id":"qui106"},{"t":"C","top":"Química orgânica","f":"Ácido carboxílico + álcool → ⟦1⟧ + água. Esse processo é a ⟦2⟧.","l":{"1":"éster","2":"esterificação"},"id":"qui107"},{"t":"C","top":"Química orgânica","f":"Óleo + álcool (com catalisador) → ⟦1⟧ + ⟦2⟧: é a ⟦3⟧.","l":{"1":"biodiesel","2":"glicerina","3":"transesterificação"},"id":"qui108"},{"t":"C","top":"Química orgânica","f":"Polietileno, PVC e isopor são polímeros de ⟦1⟧; PET e náilon são polímeros de ⟦2⟧.","l":{"1":"adição","2":"condensação"},"id":"qui109"},{"t":"C","top":"Química orgânica","f":"O nome \"but-2-eno\" indica cadeia com ⟦1⟧ carbonos e uma ligação ⟦2⟧ no carbono ⟦3⟧.","l":{"1":"4","2":"dupla","3":"2"},"id":"qui110"},{"t":"D","top":"Química orgânica","f":"Quantos carbonos tem uma cadeia com prefixo \"pent\"?","v":"5","x":"met 1, et 2, prop 3, but 4, pent 5, hex 6.","id":"qui111"},{"t":"D","top":"Química orgânica","f":"Qual gás tóxico se forma na combustão incompleta?","v":"monóxido de carbono","x":"CO: liga-se à hemoglobina e impede o transporte de O2.","id":"qui112"},{"t":"V","top":"Química orgânica","f":"O biodiesel é produzido por saponificação de óleos vegetais.","ok":false,"x":"Biodiesel é feito por TRANSESTERIFICAÇÃO (óleo + álcool). Saponificação (óleo + base) produz sabão.","id":"qui113"},{"t":"V","top":"Química orgânica","f":"Gorduras saturadas são geralmente líquidas à temperatura ambiente.","ok":false,"x":"Saturadas (gordura animal, manteiga) são sólidas. Insaturadas (óleos vegetais) são líquidas.","id":"qui114"}]},{"id":"fis","nome":"Física","ic":"⚡","cards":[{"t":"P","top":"Cinemática","f":"Velocidade média","v":"v = Δs / Δt. Para converter: km/h ÷ 3,6 = m/s; m/s x 3,6 = km/h.","m":"Para converter: de km/h para m/s \"desce dividindo por 3,6\"; de m/s para km/h \"sobe multiplicando\".","id":"fis0"},{"t":"P","top":"Cinemática","f":"Movimento uniforme (MU): função horária","v":"s = s0 + v·t. Velocidade constante, aceleração zero. Gráfico s x t é uma reta.","m":"\"Sorvete\": s = s0 + v·t.","img":"fis_graficos_mov","id":"fis1"},{"t":"P","top":"Cinemática","f":"MUV: função horária da posição e da velocidade","v":"s = s0 + v0·t + a·t²/2 e v = v0 + a·t.","m":"\"Sorvetão\": s = s0 + v0·t + a·t²/2. \"Vovô ateu\": v = v0 + a·t.","img":"fis_graficos_mov","id":"fis2"},{"t":"P","top":"Cinemática","f":"Equação de Torricelli","v":"v² = v0² + 2·a·Δs. Use quando o problema não fala de tempo.","m":"Torricelli = \"sem tempo, irmão\": use quando não há t.","id":"fis3"},{"t":"P","top":"Cinemática","f":"Gráfico v x t: o que a área e a inclinação representam?","v":"Área sob a curva = deslocamento. Inclinação (coeficiente angular) = aceleração.","m":"No v x t: ÁREA = Andou (deslocamento); inclinação = aceleração.","img":"fis_graficos_mov","id":"fis4"},{"t":"P","top":"Cinemática","f":"Queda livre","v":"MUV com a = g ≈ 10 m/s². Sem resistência do ar, todos os corpos caem juntos, independentemente da massa. h = g·t²/2.","id":"fis5"},{"t":"P","top":"Cinemática","f":"Lançamento oblíquo: o que acontece em cada eixo?","v":"Horizontal: MU (velocidade constante). Vertical: MUV (g para baixo). Alcance máximo com ângulo de 45°.","m":"Horizontal \"anda reto\" (MU), vertical \"sobe e desce\" (MUV). Ângulos complementares (30° e 60°) têm o mesmo alcance.","img":"fis_obliquo","id":"fis6"},{"t":"P","top":"Cinemática","f":"Movimento circular uniforme: relações","v":"v = ω·R; ω = 2π/T = 2πf; aceleração centrípeta a = v²/R (aponta para o centro).","id":"fis7"},{"t":"P","top":"Cinemática","f":"Engrenagens e polias ligadas por correia","v":"Mesma velocidade linear nas bordas: R1·f1 = R2·f2. A polia menor gira mais rápido. Em mesmo eixo, mesma frequência.","m":"Correia/encostadas: mesma velocidade linear. Mesmo eixo: mesma frequência.","id":"fis8"},{"t":"P","top":"Dinâmica e energia","f":"1ª Lei de Newton (inércia)","v":"Corpo sem força resultante mantém repouso ou MRU. Ex.: passageiro é \"jogado\" para frente quando o ônibus freia; função do cinto de segurança.","m":"Inércia = \"preguiça\" do corpo de mudar seu estado.","id":"fis9"},{"t":"P","top":"Dinâmica e energia","f":"2ª Lei de Newton","v":"F resultante = m·a. A aceleração tem a mesma direção e sentido da força resultante.","m":"\"FMA\": F = m·a.","id":"fis10"},{"t":"P","top":"Dinâmica e energia","f":"3ª Lei de Newton (ação e reação)","v":"Forças de mesma intensidade, mesma direção, sentidos opostos, aplicadas em CORPOS DIFERENTES (por isso não se anulam).","m":"Ação e reação em corpos DIFERENTES: por isso nunca se anulam.","id":"fis11"},{"t":"P","top":"Dinâmica e energia","f":"Peso x massa","v":"Massa (kg) é a quantidade de matéria, igual em qualquer lugar. Peso é força: P = m·g (newtons), varia com a gravidade.","id":"fis12"},{"t":"P","top":"Dinâmica e energia","f":"Força de atrito","v":"Fat = μ·N. Atrito estático máximo é maior que o cinético (é mais difícil começar a empurrar). ABS evita travar a roda para manter atrito estático.","id":"fis13"},{"t":"P","top":"Dinâmica e energia","f":"Força elástica (Lei de Hooke)","v":"F = k·x (k: constante da mola; x: deformação).","id":"fis14"},{"t":"P","top":"Dinâmica e energia","f":"Trabalho de uma força","v":"τ = F·d·cos θ. Força perpendicular ao deslocamento não realiza trabalho. Trabalho da resultante = variação da energia cinética.","id":"fis15"},{"t":"P","top":"Dinâmica e energia","f":"Energia cinética, potencial gravitacional e elástica","v":"Ec = m·v²/2. Epg = m·g·h. Epe = k·x²/2.","m":"Cinética = \"Ec = mv²/2\" (movimento). Potencial gravitacional = \"mgh\" (\"mega-h\", altura).","id":"fis16"},{"t":"P","top":"Dinâmica e energia","f":"Conservação da energia mecânica","v":"Sem atrito: Ec + Ep = constante. Ex.: na montanha-russa, v no ponto mais baixo = √(2gh).","m":"Na queda, troca altura por velocidade: v = √(2gh), sem depender da massa.","id":"fis17"},{"t":"P","top":"Dinâmica e energia","f":"Potência e rendimento","v":"P = energia / tempo (W = J/s). Rendimento η = potência útil / potência total. 1 kWh = 3,6 x 10^6 J.","id":"fis18"},{"t":"P","top":"Dinâmica e energia","f":"Quantidade de movimento e conservação","v":"Q = m·v. Em sistema isolado (colisões, explosões, recuo da arma) Q total se conserva.","id":"fis19"},{"t":"P","top":"Dinâmica e energia","f":"Impulso","v":"I = F·Δt = ΔQ. Airbag e capacete aumentam o tempo de colisão, diminuindo a força.","m":"Airbag não reduz a variação de velocidade, aumenta o TEMPO, e por isso reduz a FORÇA.","id":"fis20"},{"t":"P","top":"Dinâmica e energia","f":"Lei da gravitação universal","v":"F = G·M·m/d². Dobrar a distância → força cai para 1/4.","id":"fis21"},{"t":"P","top":"Dinâmica e energia","f":"Por que astronautas \"flutuam\" na estação espacial?","v":"Não é falta de gravidade: estão em queda livre contínua ao redor da Terra, junto com a estação.","id":"fis22"},{"t":"P","top":"Hidrostática","f":"Densidade e pressão","v":"d = m/V. Pressão p = F/A: mesma força em área menor → maior pressão (faca afiada, salto agulha).","id":"fis23"},{"t":"P","top":"Hidrostática","f":"Pressão hidrostática (Lei de Stevin)","v":"p = p0 + d·g·h. A cada 10 m de água, a pressão aumenta cerca de 1 atm.","m":"\"A cada 10 metros de mergulho, +1 atm.\"","id":"fis24"},{"t":"P","top":"Hidrostática","f":"Princípio de Pascal e prensa hidráulica","v":"A pressão aplicada é transmitida igualmente: F1/A1 = F2/A2. Usado em freios e elevadores hidráulicos.","m":"Prensa: área maior = força maior (F1/A1 = F2/A2).","id":"fis25"},{"t":"P","top":"Hidrostática","f":"Empuxo (Princípio de Arquimedes)","v":"E = d(líquido)·V(submerso)·g. Corpo flutua se for menos denso que o líquido.","m":"Empuxo = peso do líquido deslocado (\"o que sai de água te empurra\").","id":"fis26"},{"t":"P","top":"Hidrostática","f":"Por que um navio de aço flutua?","v":"Seu formato oco desloca grande volume de água: a densidade média (aço + ar) é menor que a da água.","id":"fis27"},{"t":"P","top":"Termologia","f":"Conversão Celsius, Fahrenheit e Kelvin","v":"C/5 = (F - 32)/9 = (K - 273)/5. K = C + 273.","m":"Pontos fixos: água congela a 0 °C = 32 °F = 273 K, e ferve a 100 °C = 212 °F = 373 K.","id":"fis28"},{"t":"P","top":"Termologia","f":"Calor sensível x calor latente","v":"Sensível: muda temperatura, Q = m·c·ΔT. Latente: muda de estado sem mudar temperatura, Q = m·L.","m":"\"Que macete\": Q = m·c·ΔT. Latente: Q = m·L (\"mL\" como mililitro). Na mudança de estado, a temperatura PARA.","id":"fis29"},{"t":"P","top":"Termologia","f":"Calor específico: o que significa ter valor alto?","v":"Precisa de muito calor para variar a temperatura. A água (c = 1 cal/g°C) esquenta e esfria devagar: regula o clima litorâneo.","id":"fis30"},{"t":"P","top":"Termologia","f":"Condução, convecção e irradiação","v":"Condução: contato, partícula a partícula (metais). Convecção: correntes no fluido (ar-condicionado no alto, freezer em cima). Irradiação: ondas eletromagnéticas, inclusive no vácuo (Sol).","m":"Condução = Contato. Convecção = Corrente no fluido. Irradiação = Raios (até no vácuo).","id":"fis31"},{"t":"P","top":"Termologia","f":"Como funciona a garrafa térmica?","v":"Vácuo entre paredes impede condução e convecção; paredes espelhadas refletem a irradiação.","id":"fis32"},{"t":"P","top":"Termologia","f":"Por que a panela de pressão cozinha mais rápido?","v":"Pressão maior eleva o ponto de ebulição da água (acima de 100 °C).","id":"fis33"},{"t":"P","top":"Termologia","f":"Brisa marítima x terrestre","v":"Dia: terra esquenta mais rápido, ar sobe sobre ela → brisa do mar para a terra. Noite: inverte (terra esfria mais rápido).","m":"De dia a brisa vem DO MAR (marítima); de noite vem DA TERRA (terrestre).","id":"fis34"},{"t":"P","top":"Termologia","f":"Dilatação térmica","v":"ΔL = L0·α·ΔT. Juntas de dilatação em pontes e trilhos. Água anômala: entre 0 e 4 °C contrai ao aquecer.","id":"fis35"},{"t":"P","top":"Termologia","f":"Transformações gasosas","v":"p·V/T = constante (T em kelvin). Isotérmica: pV constante. Isobárica: V/T constante. Isovolumétrica: p/T constante.","m":"\"PV sobre T é constante\" (\"Piviti\"). Temperatura sempre em KELVIN.","id":"fis36"},{"t":"P","top":"Termologia","f":"1ª Lei da Termodinâmica","v":"Q = τ + ΔU. O calor recebido vira trabalho e/ou aumento da energia interna.","id":"fis37"},{"t":"P","top":"Termologia","f":"2ª Lei e máquinas térmicas","v":"Nenhuma máquina converte todo calor em trabalho. Rendimento de Carnot: η = 1 - Tfria/Tquente (em K).","id":"fis38"},{"t":"P","top":"Termologia","f":"Como funciona a geladeira?","v":"Máquina térmica invertida: o compressor faz trabalho para retirar calor de dentro (evaporador) e liberar fora (serpentina atrás).","id":"fis39"},{"t":"P","top":"Ondulatória e óptica","f":"Equação fundamental da onda","v":"v = λ·f. A frequência não muda quando a onda troca de meio; muda velocidade e comprimento de onda.","m":"\"Vê-lambda-f\": v = λ·f. Mudou de meio, a frequência fica (é a \"identidade\" da onda).","img":"fis_onda","id":"fis40"},{"t":"P","top":"Ondulatória e óptica","f":"Ondas mecânicas x eletromagnéticas","v":"Mecânicas precisam de meio (som, ondas na água). Eletromagnéticas propagam-se no vácuo, a 3 x 10^8 m/s (luz, rádio, raios X).","id":"fis41"},{"t":"P","top":"Ondulatória e óptica","f":"Espectro eletromagnético em ordem crescente de frequência","v":"Rádio, micro-ondas, infravermelho, luz visível, ultravioleta, raios X, raios gama. Mais frequência = mais energia (E = h·f).","m":"\"Rádio Mostra Imagens Visíveis Usando Raios Gama\" (rádio, micro-ondas, infra, visível, UV, raios X, gama).","img":"fis_espectro","id":"fis42"},{"t":"P","top":"Ondulatória e óptica","f":"Qualidades do som: altura, intensidade, timbre","v":"Altura: frequência (agudo x grave). Intensidade: amplitude, volume (decibéis). Timbre: forma da onda, distingue instrumentos.","m":"Altura = frequência (agudo/grave). Intensidade = volume. Timbre = \"assinatura\" do instrumento.","id":"fis43"},{"t":"P","top":"Ondulatória e óptica","f":"Efeito Doppler","v":"Fonte se aproximando: som percebido mais agudo (frequência maior). Afastando: mais grave. Usado em radar e ultrassom.","m":"Ambulância chegando = mais aguda; indo embora = mais grave.","img":"fis_doppler","id":"fis44"},{"t":"P","top":"Ondulatória e óptica","f":"Ressonância","v":"Sistema recebe energia na sua frequência natural e vibra com amplitude máxima. Ex.: taça quebrando com a voz, sintonizar rádio.","id":"fis45"},{"t":"P","top":"Ondulatória e óptica","f":"Difração e interferência","v":"Difração: onda contorna obstáculos (ouvimos som atrás do muro). Interferência: superposição construtiva ou destrutiva (fone com cancelamento de ruído).","id":"fis46"},{"t":"P","top":"Ondulatória e óptica","f":"Polarização","v":"Só ocorre com ondas transversais (luz). Óculos polarizados filtram o brilho refletido.","id":"fis47"},{"t":"P","top":"Ondulatória e óptica","f":"Refração da luz: o que acontece?","v":"Mudança de meio altera a velocidade e pode desviar o raio. Lei de Snell: n1·sen θ1 = n2·sen θ2. n = c/v.","id":"fis48"},{"t":"P","top":"Ondulatória e óptica","f":"Reflexão total: condição e aplicação","v":"Luz indo do meio mais refringente para o menos refringente com ângulo maior que o limite. Aplicação: fibra óptica, brilho do diamante.","m":"Só acontece saindo do meio \"mais denso opticamente\" para o \"menos denso\", com ângulo grande.","img":"fis_reflexao_total","id":"fis49"},{"t":"P","top":"Ondulatória e óptica","f":"Espelhos planos","v":"Imagem virtual, direita, do mesmo tamanho, simétrica (inverte esquerda-direita). Girar o espelho em α gira o raio refletido em 2α.","id":"fis50"},{"t":"P","top":"Ondulatória e óptica","f":"Lente convergente x divergente","v":"Convergente (bordas finas no ar): lupa, corrige hipermetropia. Divergente (bordas grossas): corrige miopia.","m":"Bordas FINAS convergem; bordas GROSSAS divergem (no ar).","id":"fis51"},{"t":"P","top":"Ondulatória e óptica","f":"Miopia x hipermetropia x presbiopia","v":"Miopia: imagem antes da retina, vê mal de longe → lente divergente. Hipermetropia: depois da retina, vê mal de perto → convergente. Presbiopia (\"vista cansada\"): perda de acomodação → convergente.","m":"MIOPia = vê Mal de longe, \"MÍOPE pede DIVERGENTE\" (lente que espalha). HIPERmetropia = foco \"passa do ponto\", pede CONVERGENTE.","img":"fis_olho","id":"fis52"},{"t":"P","top":"Ondulatória e óptica","f":"Equação dos pontos conjugados e aumento","v":"1/f = 1/p + 1/p'. A = -p'/p = i/o. Vergência V = 1/f (em dioptrias, f em metros: \"graus\").","id":"fis53"},{"t":"P","top":"Ondulatória e óptica","f":"Por que o céu é azul?","v":"A luz azul (menor comprimento de onda) é mais espalhada pelas moléculas do ar.","id":"fis54"},{"t":"P","top":"Ondulatória e óptica","f":"Cor dos objetos","v":"Um objeto reflete a cor que vemos e absorve as outras. Branco reflete todas; preto absorve todas (esquenta mais ao sol).","id":"fis55"},{"t":"P","top":"Eletricidade e magnetismo","f":"Corrente elétrica","v":"i = Q/Δt (ampère = C/s). Sentido convencional: do polo + para o -.","id":"fis56"},{"t":"P","top":"Eletricidade e magnetismo","f":"1ª Lei de Ohm","v":"U = R·i.","m":"\"URI\": U = R·i (como a URI de uma página).","id":"fis57"},{"t":"P","top":"Eletricidade e magnetismo","f":"2ª Lei de Ohm","v":"R = ρ·L/A. Fio mais longo → mais resistência; fio mais grosso → menos resistência.","id":"fis58"},{"t":"P","top":"Eletricidade e magnetismo","f":"Potência elétrica","v":"P = U·i = R·i² = U²/R.","m":"\"PUI\": P = U·i. Combine com U = R·i para achar P = R·i² e P = U²/R.","id":"fis59"},{"t":"P","top":"Eletricidade e magnetismo","f":"Energia elétrica consumida e conta de luz","v":"E = P·Δt. Em kWh: potência em kW x horas de uso. Ex.: chuveiro de 5.000 W por 0,5 h/dia em 30 dias = 75 kWh.","m":"Conta de luz: kW x h. Lembre de dividir os watts por 1.000.","id":"fis60"},{"t":"P","top":"Eletricidade e magnetismo","f":"Associação de resistores em série","v":"Mesma corrente; R eq = R1 + R2 + ... Se um queima, todos apagam (pisca-pisca antigo).","m":"","img":"fis_circuitos","id":"fis61"},{"t":"P","top":"Eletricidade e magnetismo","f":"Associação de resistores em paralelo","v":"Mesma tensão; 1/Req = 1/R1 + 1/R2 + ... Req menor que o menor resistor. Ligação das tomadas de casa.","m":"Paralelo: \"cada um tem sua própria estrada\", a tensão é a mesma para todos.","img":"fis_circuitos","id":"fis62"},{"t":"P","top":"Eletricidade e magnetismo","f":"Chuveiro elétrico: posição \"inverno\" x \"verão\"","v":"Inverno: resistência MENOR → mais corrente → mais potência (P = U²/R) → água mais quente.","m":"Inverno = menor resistência = mais corrente = mais quente (P = U²/R: R menor, P maior).","id":"fis63"},{"t":"P","top":"Eletricidade e magnetismo","f":"Função do fusível e do disjuntor","v":"Interromper o circuito quando a corrente passa do limite, evitando superaquecimento e incêndio.","id":"fis64"},{"t":"P","top":"Eletricidade e magnetismo","f":"Por que pássaros pousam em fios de alta tensão sem levar choque?","v":"As duas patas estão no mesmo fio, praticamente no mesmo potencial: não há ddp significativa sobre o corpo.","id":"fis65"},{"t":"P","top":"Eletricidade e magnetismo","f":"Função do fio terra","v":"Oferecer caminho de baixa resistência para a corrente de fuga, protegendo quem toca no aparelho.","id":"fis66"},{"t":"P","top":"Eletricidade e magnetismo","f":"Lei de Coulomb","v":"F = k·|Q1|·|Q2| / d². Cargas iguais se repelem, opostas se atraem.","id":"fis67"},{"t":"P","top":"Eletricidade e magnetismo","f":"Para-raios e gaiola de Faraday","v":"Cargas se concentram nas pontas (poder das pontas → para-raios). No interior de condutor fechado o campo é nulo (por isso o carro protege de raios).","id":"fis68"},{"t":"P","top":"Eletricidade e magnetismo","f":"Ímãs: propriedades básicas","v":"Polos iguais se repelem e opostos se atraem. Não existe monopolo: cortar um ímã gera dois ímãs. Bússola aponta para o polo sul magnético (perto do norte geográfico).","id":"fis69"},{"t":"P","top":"Eletricidade e magnetismo","f":"Corrente elétrica e campo magnético (Oersted)","v":"Corrente elétrica gera campo magnético ao redor do fio. Base dos eletroímãs e motores.","id":"fis70"},{"t":"P","top":"Eletricidade e magnetismo","f":"Indução eletromagnética (Faraday)","v":"Variação do fluxo magnético induz corrente. Base dos geradores (usinas), transformadores, carregador por indução e cartão por aproximação.","m":"Faraday: \"campo que MUDA gera corrente\". Ímã parado não induz nada.","id":"fis71"},{"t":"P","top":"Eletricidade e magnetismo","f":"Transformador","v":"U1/U2 = N1/N2. Só funciona com corrente ALTERNADA. Usado para elevar a tensão na transmissão (menos perda) e baixar no consumo.","m":"Só funciona com corrente ALTERNADA (precisa de fluxo VARIANDO).","img":"fis_transformador","id":"fis72"},{"t":"P","top":"Eletricidade e magnetismo","f":"Usinas: transformações de energia","v":"Hidrelétrica: potencial gravitacional → cinética → elétrica. Termelétrica: química → térmica → cinética → elétrica. Eólica: cinética do vento → elétrica. Todas (menos solar fotovoltaica) usam gerador com indução.","id":"fis73"},{"t":"P","top":"Eletricidade e magnetismo","f":"Vantagens e desvantagens da hidrelétrica","v":"Renovável, baixa emissão na operação. Mas alaga grandes áreas, desloca populações, afeta peixes e emite metano da vegetação submersa.","id":"fis74"},{"t":"P","top":"Eletricidade e magnetismo","f":"Efeito fotoelétrico","v":"Luz de frequência suficiente arranca elétrons de um metal; depende da frequência, não da intensidade. Base das células solares e explicação de Einstein para o fóton.","id":"fis75"},{"t":"F","top":"Cinemática","f":"Como saber o deslocamento e a aceleração no gráfico v × t?","v":"<b>Deslocamento</b> = área sob a curva. <b>Aceleração</b> = inclinação da reta. No s × t, MU dá reta e MUV dá parábola.","img":"fis_graficos_mov","id":"fis76"},{"t":"F","top":"Cinemática","f":"Por que 30° e 60° têm o mesmo alcance?","v":"Porque são <b>ângulos complementares</b> (somam 90°): o alcance depende de sen(2θ), e sen 60° = sen 120°. O máximo é em <b>45°</b>.","img":"fis_obliquo","id":"fis77"},{"t":"C","top":"Cinemática","f":"Velocidade de 72 km/h equivale a ⟦1⟧ m/s (divide por ⟦2⟧).","l":{"1":"20","2":"3,6"},"id":"fis78"},{"t":"C","top":"Cinemática","f":"Equação de Torricelli: v² = ⟦1⟧.","l":{"1":"v0² + 2·a·Δs"},"id":"fis79"},{"t":"C","top":"Cinemática","f":"Em queda livre, desprezando o ar, todos os corpos caem com a mesma aceleração, ⟦1⟧, independentemente da ⟦2⟧.","l":{"1":"g ≈ 10 m/s²","2":"massa"},"id":"fis80"},{"t":"C","top":"Cinemática","f":"No movimento circular, v = ⟦1⟧ e a aceleração centrípeta vale ⟦2⟧.","l":{"1":"ω·R","2":"v²/R"},"id":"fis81"},{"t":"D","top":"Cinemática","f":"Converta 108 km/h para m/s.","v":"30","x":"108 ÷ 3,6 = 30.","id":"fis82"},{"t":"D","top":"Cinemática","f":"Um carro parte do repouso com a = 2 m/s². Qual sua velocidade (m/s) após 5 s?","v":"10","x":"v = v0 + a·t = 0 + 2·5.","id":"fis83"},{"t":"V","top":"Cinemática","f":"No lançamento oblíquo, a velocidade horizontal diminui até o ponto mais alto.","ok":false,"x":"A componente horizontal é constante (MU). Quem diminui até zero, no ponto mais alto, é a componente VERTICAL.","id":"fis84"},{"t":"C","top":"Dinâmica e energia","f":"2ª lei de Newton: F resultante = ⟦1⟧. Peso: P = ⟦2⟧.","l":{"1":"m·a","2":"m·g"},"id":"fis85"},{"t":"C","top":"Dinâmica e energia","f":"Energia cinética: Ec = ⟦1⟧. Energia potencial gravitacional: Ep = ⟦2⟧. Energia elástica: ⟦3⟧.","l":{"1":"m·v²/2","2":"m·g·h","3":"k·x²/2"},"id":"fis86"},{"t":"C","top":"Dinâmica e energia","f":"Potência = ⟦1⟧ / ⟦2⟧, medida em watts (W = J/s).","l":{"1":"energia","2":"tempo"},"id":"fis87"},{"t":"C","top":"Dinâmica e energia","f":"Quantidade de movimento: Q = ⟦1⟧; impulso: I = ⟦2⟧ = ΔQ.","l":{"1":"m·v","2":"F·Δt"},"id":"fis88"},{"t":"D","top":"Dinâmica e energia","f":"Um corpo de 2 kg está a 5 m de altura (g = 10). Qual sua energia potencial em joules?","v":"100","x":"Ep = m·g·h = 2·10·5.","id":"fis89"},{"t":"D","top":"Dinâmica e energia","f":"Um corpo cai de 20 m (g = 10, sem atrito). Velocidade (m/s) ao chegar ao chão?","v":"20","x":"v = √(2gh) = √400.","id":"fis90"},{"t":"D","top":"Dinâmica e energia","f":"Força resultante (N) sobre um corpo de 4 kg com aceleração de 3 m/s²?","v":"12","x":"F = m·a.","id":"fis91"},{"t":"V","top":"Dinâmica e energia","f":"As forças de ação e reação se anulam porque têm mesma intensidade e sentidos opostos.","ok":false,"x":"Elas atuam em corpos DIFERENTES, então não se anulam.","id":"fis92"},{"t":"V","top":"Dinâmica e energia","f":"Na estação espacial, os astronautas flutuam porque lá não existe gravidade.","ok":false,"x":"A gravidade lá é ~90% da da superfície. Eles flutuam porque estão em queda livre contínua junto com a estação.","id":"fis93"},{"t":"C","top":"Hidrostática","f":"Empuxo: E = ⟦1⟧ · ⟦2⟧ · g.","l":{"1":"d(líquido)","2":"V(submerso)"},"id":"fis94"},{"t":"C","top":"Hidrostática","f":"Um corpo flutua quando sua densidade é ⟦1⟧ que a do líquido.","l":{"1":"menor"},"id":"fis95"},{"t":"D","top":"Hidrostática","f":"Na prensa hidráulica, A2 = 10·A1. Se F1 = 50 N, quanto vale F2 (N)?","v":"500","x":"F1/A1 = F2/A2.","id":"fis96"},{"t":"C","top":"Termologia","f":"Calor sensível: Q = ⟦1⟧. Calor latente: Q = ⟦2⟧.","l":{"1":"m·c·ΔT","2":"m·L"},"id":"fis97"},{"t":"C","top":"Termologia","f":"A transmissão de calor que ocorre no vácuo é a ⟦1⟧; a que ocorre por correntes em fluidos é a ⟦2⟧.","l":{"1":"irradiação","2":"convecção"},"id":"fis98"},{"t":"C","top":"Termologia","f":"Rendimento máximo de uma máquina térmica (Carnot): η = 1 − ⟦1⟧, com temperaturas em ⟦2⟧.","l":{"1":"T fria / T quente","2":"kelvin"},"id":"fis99"},{"t":"D","top":"Termologia","f":"Converta 27 °C para kelvin.","v":"300","x":"K = C + 273.","id":"fis100"},{"t":"D","top":"Termologia","f":"Quanto calor (cal) é preciso para aquecer 100 g de água de 20 °C a 70 °C? (c = 1 cal/g°C)","v":"5000","x":"Q = m·c·ΔT = 100·1·50.","id":"fis101"},{"t":"V","top":"Termologia","f":"Durante a fervura, a temperatura da água continua subindo enquanto houver aquecimento.","ok":false,"x":"Durante a mudança de estado a temperatura fica constante: o calor é usado para mudar o estado (calor latente).","id":"fis102"},{"t":"V","top":"Termologia","f":"Um casaco de lã esquenta o corpo porque produz calor.","ok":false,"x":"A lã é isolante: só dificulta a perda do calor do próprio corpo.","id":"fis103"},{"t":"F","top":"Ondulatória e óptica","f":"Qual defeito tem o foco antes da retina e qual lente o corrige?","v":"<b>Miopia</b>: o olho converge demais e o foco cai antes da retina. Corrige com <b>lente divergente</b>.","img":"fis_olho","id":"fis104"},{"t":"F","top":"Ondulatória e óptica","f":"Coloque em ordem crescente de energia: raios X, micro-ondas, luz visível, ultravioleta.","v":"<b>Micro-ondas → luz visível → ultravioleta → raios X.</b> Energia cresce com a frequência (E = h·f).","img":"fis_espectro","id":"fis105"},{"t":"F","top":"Ondulatória e óptica","f":"Por que a sirene parece mais aguda quando a ambulância se aproxima?","v":"As frentes de onda se <b>acumulam à frente</b> da fonte: menor comprimento de onda, <b>maior frequência</b> percebida, som mais agudo.","img":"fis_doppler","id":"fis106"},{"t":"F","top":"Ondulatória e óptica","f":"Uma onda tem λ = 2 m e f = 170 Hz. Qual sua velocidade?","v":"v = λ·f = 2 · 170 = <b>340 m/s</b> (a velocidade do som no ar).","img":"fis_onda","id":"fis107"},{"t":"C","top":"Ondulatória e óptica","f":"Equação fundamental da onda: v = ⟦1⟧. Ao mudar de meio, a ⟦2⟧ não muda.","l":{"1":"λ·f","2":"frequência"},"id":"fis108"},{"t":"C","top":"Ondulatória e óptica","f":"O som é onda ⟦1⟧ e não se propaga no ⟦2⟧; a luz é onda ⟦3⟧.","l":{"1":"mecânica","2":"vácuo","3":"eletromagnética"},"id":"fis109"},{"t":"C","top":"Ondulatória e óptica","f":"A miopia é corrigida com lente ⟦1⟧; a hipermetropia e a presbiopia, com lente ⟦2⟧.","l":{"1":"divergente","2":"convergente"},"id":"fis110"},{"t":"C","top":"Ondulatória e óptica","f":"Lei de Snell: ⟦1⟧. Índice de refração: n = ⟦2⟧.","l":{"1":"n1·sen θ1 = n2·sen θ2","2":"c/v"},"id":"fis111"},{"t":"D","top":"Ondulatória e óptica","f":"Lente de vergência +2 di tem distância focal de quantos metros?","v":"0,5","x":"V = 1/f, então f = 1/2 m.","id":"fis112"},{"t":"V","top":"Ondulatória e óptica","f":"O efeito Doppler muda a frequência emitida pela fonte.","ok":false,"x":"A fonte emite sempre a mesma frequência; o que muda é a frequência PERCEBIDA pelo observador.","id":"fis113"},{"t":"V","top":"Ondulatória e óptica","f":"A luz se propaga com a mesma velocidade no ar e no vidro.","ok":false,"x":"No vidro ela é mais lenta (n maior). Essa mudança de velocidade é o que causa a refração.","id":"fis114"},{"t":"F","top":"Eletricidade e magnetismo","f":"Se uma lâmpada queimar, o que acontece em cada circuito?","v":"<b>Série:</b> todas apagam (o circuito abre). <b>Paralelo:</b> as outras continuam acesas, porque cada uma tem seu próprio caminho. É assim nas casas.","img":"fis_circuitos","id":"fis115"},{"t":"F","top":"Eletricidade e magnetismo","f":"O primário tem 100 espiras e 220 V; o secundário, 50 espiras. Qual a tensão de saída?","v":"U1/U2 = N1/N2 → 220/U2 = 100/50 → <b>U2 = 110 V</b>. Menos espiras, menos tensão.","img":"fis_transformador","id":"fis116"},{"t":"C","top":"Eletricidade e magnetismo","f":"1ª lei de Ohm: U = ⟦1⟧. Potência: P = ⟦2⟧.","l":{"1":"R·i","2":"U·i"},"id":"fis117"},{"t":"C","top":"Eletricidade e magnetismo","f":"Em série, a ⟦1⟧ é a mesma em todos os resistores; em paralelo, a ⟦2⟧ é a mesma.","l":{"1":"corrente","2":"tensão"},"id":"fis118"},{"t":"C","top":"Eletricidade e magnetismo","f":"Energia consumida: E = ⟦1⟧. Um aparelho de 2.000 W ligado 3 h consome ⟦2⟧ kWh.","l":{"1":"P·Δt","2":"6"},"id":"fis119"},{"t":"C","top":"Eletricidade e magnetismo","f":"Transformadores só funcionam com corrente ⟦1⟧, porque dependem da ⟦2⟧ (lei de Faraday).","l":{"1":"alternada","2":"variação do fluxo magnético"},"id":"fis120"},{"t":"D","top":"Eletricidade e magnetismo","f":"Resistência equivalente (Ω) de dois resistores de 10 Ω em paralelo?","v":"5","x":"Iguais em paralelo: R/n = 10/2.","id":"fis121"},{"t":"D","top":"Eletricidade e magnetismo","f":"Um chuveiro de 4.000 W fica ligado 30 min por dia. Quantos kWh consome em 30 dias?","v":"60","x":"4 kW x 0,5 h x 30.","id":"fis122"},{"t":"D","top":"Eletricidade e magnetismo","f":"Corrente (A) num resistor de 20 Ω ligado a 220 V?","v":"11","x":"i = U/R = 220/20.","id":"fis123"},{"t":"V","top":"Eletricidade e magnetismo","f":"Na posição \"inverno\" o chuveiro usa uma resistência maior.","ok":false,"x":"Usa resistência MENOR: com tensão fixa, P = U²/R aumenta.","id":"fis124"},{"t":"V","top":"Eletricidade e magnetismo","f":"Pássaros pousados em fios de alta tensão não levam choque porque seus pés são isolantes.","ok":false,"x":"Não há ddp entre as duas patas no mesmo fio, então quase não passa corrente pelo corpo.","id":"fis125"}]},{"id":"mat","nome":"Matemática","ic":"📐","cards":[{"t":"P","top":"Matemática básica e proporção","f":"Regra de três: como saber se é direta ou inversa?","v":"Direta: as grandezas aumentam juntas (mais produtos, mais preço). Inversa: uma aumenta e a outra diminui (mais operários, menos dias). Na inversa, inverta uma das razões.","m":"Teste das setas: se \"mais → mais\", direta (multiplica cruzado). Se \"mais → menos\", inversa (inverte uma fração antes).","id":"mat0"},{"t":"P","top":"Matemática básica e proporção","f":"Grandeza diretamente proporcional a A e inversamente a B: como montar?","v":"x = k·A/B. Ex.: tempo de obra é proporcional à área e inversamente proporcional ao número de pessoas.","id":"mat1"},{"t":"P","top":"Matemática básica e proporção","f":"Escala: fórmula e cuidado com unidades","v":"Escala = medida no desenho / medida real (mesma unidade). 1:50.000 → 1 cm = 500 m. Para área, a escala vai ao quadrado; para volume, ao cubo.","m":"\"Comprimento: k. Área: k². Volume: k³.\"","id":"mat2"},{"t":"P","top":"Matemática básica e proporção","f":"Se um mapa tem escala 1:100, como se relacionam as áreas?","v":"Razão das áreas = (1/100)² = 1/10.000.","id":"mat3"},{"t":"P","top":"Matemática básica e proporção","f":"Conversões de unidades que mais caem","v":"1 m³ = 1.000 L; 1 dm³ = 1 L; 1 cm³ = 1 mL; 1 km² = 100 hectares; 1 ha = 10.000 m².","m":"\"1 litro cabe num cubo de 10 cm de lado\" (1 dm³ = 1 L).","id":"mat4"},{"t":"P","top":"Matemática básica e proporção","f":"Média aritmética ponderada","v":"Soma de (valor x peso) / soma dos pesos. É como o Sisu calcula a nota com pesos por área.","id":"mat5"},{"t":"P","top":"Matemática básica e proporção","f":"Razão x proporção","v":"Razão é a divisão a/b. Proporção é a igualdade entre duas razões: a/b = c/d → a·d = b·c (produto dos meios = produto dos extremos).","id":"mat6"},{"t":"P","top":"Matemática básica e proporção","f":"Divisão proporcional","v":"Para dividir N em partes proporcionais a a, b, c: cada parte = N·(seu valor)/(a+b+c).","id":"mat7"},{"t":"P","top":"Matemática básica e proporção","f":"MMC e MDC: quando usar cada um?","v":"MMC: eventos que se repetem e voltam a coincidir (ônibus, remédios, luzes piscando). MDC: dividir em pedaços iguais do maior tamanho possível.","m":"MMC = \"quando se encontram de novo\" (tempo). MDC = \"maior pedaço igual\" (corte).","id":"mat8"},{"t":"P","top":"Matemática básica e proporção","f":"Notação científica","v":"Número entre 1 e 10 vezes potência de 10. Ex.: 0,00052 = 5,2 x 10^-4. Na multiplicação somam-se os expoentes.","id":"mat9"},{"t":"P","top":"Matemática básica e proporção","f":"Critérios de divisibilidade por 3, 4, 9","v":"3 e 9: soma dos algarismos divisível por 3 ou 9. 4: os dois últimos algarismos formam número divisível por 4.","id":"mat10"},{"t":"P","top":"Porcentagem e matemática financeira","f":"Aumento e desconto como fator multiplicativo","v":"Aumento de i% → multiplique por (1 + i). Desconto de i% → por (1 - i). Aumento de 20% = x1,2; desconto de 15% = x0,85.","m":"\"Aumentou? 1 + taxa. Diminuiu? 1 − taxa. Vários seguidos? Multiplica os fatores.\"","id":"mat11"},{"t":"P","top":"Porcentagem e matemática financeira","f":"Aumento de 10% seguido de desconto de 10%: volta ao preço original?","v":"Não. 1,1 x 0,9 = 0,99: fica 1% mais barato.","id":"mat12"},{"t":"P","top":"Porcentagem e matemática financeira","f":"Variação percentual","v":"(valor novo - valor antigo) / valor antigo x 100.","id":"mat13"},{"t":"P","top":"Porcentagem e matemática financeira","f":"Diferença entre \"pontos percentuais\" e \"por cento\"","v":"Taxa que vai de 10% para 12% subiu 2 pontos percentuais, mas aumentou 20% em termos relativos.","id":"mat14"},{"t":"P","top":"Porcentagem e matemática financeira","f":"Juros simples","v":"J = C·i·t; Montante M = C·(1 + i·t). Crescimento linear (progressão aritmética).","m":"Simples = Soma sempre o mesmo valor (reta).","img":"mat_juros","id":"mat15"},{"t":"P","top":"Porcentagem e matemática financeira","f":"Juros compostos","v":"M = C·(1 + i)^t. Crescimento exponencial (progressão geométrica). Taxa e tempo na mesma unidade.","m":"Composto = juros sobre juros: Cresce Como bola de neve (curva).","img":"mat_juros","id":"mat16"},{"t":"P","top":"Porcentagem e matemática financeira","f":"Por que no ENEM aparecem logaritmos com juros compostos?","v":"Para achar o tempo: (1 + i)^t = M/C → t = log(M/C) / log(1 + i). Costumam dar os valores de log.","id":"mat17"},{"t":"P","top":"Funções","f":"Função afim (1º grau): forma e interpretação","v":"f(x) = a·x + b. a = taxa de variação (inclinação); b = valor inicial (onde corta o eixo y). Ex.: corrida de táxi = bandeirada + preço por km.","m":"\"a = quanto anda por unidade, b = de onde parte.\"","img":"mat_afim","id":"mat18"},{"t":"P","top":"Funções","f":"Como achar a função afim dados dois pontos?","v":"a = (y2 - y1)/(x2 - x1); depois substitua um ponto para achar b.","id":"mat19"},{"t":"P","top":"Funções","f":"Função quadrática: vértice","v":"f(x) = ax² + bx + c. xv = -b/(2a); yv = -Δ/(4a). a &gt; 0: concavidade para cima (ponto mínimo); a &lt; 0: para baixo (máximo).","m":"Vértice: \"X é menos b sobre dois a\". Boca para cima = sorriso = tem mínimo.","img":"mat_parabola","id":"mat20"},{"t":"P","top":"Funções","f":"Problemas de máximo e mínimo (lucro, área, altura)","v":"Monte a função quadrática e calcule o vértice. O yv dá o valor máximo/mínimo; o xv diz quando ocorre.","id":"mat21"},{"t":"P","top":"Funções","f":"Fórmula de Bhaskara","v":"Δ = b² - 4ac; x = (-b ± √Δ)/(2a). Δ &gt; 0: duas raízes; Δ = 0: uma; Δ &lt; 0: nenhuma real.","m":"Δ diz quantas raízes: positivo 2, zero 1, negativo nenhuma.","img":"mat_parabola","id":"mat22"},{"t":"P","top":"Funções","f":"Soma e produto das raízes","v":"Soma = -b/a; produto = c/a.","id":"mat23"},{"t":"P","top":"Funções","f":"Função exponencial: crescimento e decrescimento","v":"f(x) = a·b^x. b &gt; 1 cresce (bactérias, juros); 0 &lt; b &lt; 1 decresce (decaimento, depreciação).","m":"","img":"mat_exp_log","id":"mat24"},{"t":"P","top":"Funções","f":"Logaritmo: definição","v":"log_b a = x ⇔ b^x = a. log 1 = 0; log_b b = 1.","m":"\"O log é o EXPOENTE\": log₂ 8 = 3 porque 2³ = 8.","img":"mat_exp_log","id":"mat25"},{"t":"P","top":"Funções","f":"Propriedades dos logaritmos","v":"log(a·b) = log a + log b; log(a/b) = log a - log b; log a^n = n·log a; mudança de base: log_b a = log a / log b.","m":"\"Log transforma vezes em mais, dividir em menos, e o expoente pula para a frente.\"","id":"mat26"},{"t":"P","top":"Funções","f":"Interpretação de gráficos: dicas para o ENEM","v":"Leia título, eixos e unidades. Cuidado com eixo que não começa no zero. Inclinação maior = variação mais rápida.","id":"mat27"},{"t":"P","top":"Geometria plana","f":"Área do triângulo, retângulo, trapézio e losango","v":"Triângulo: b·h/2. Retângulo: b·h. Trapézio: (B + b)·h/2. Losango: D·d/2.","m":"Trapézio: \"base maior mais base menor, vezes altura, sobre dois\".","id":"mat28"},{"t":"P","top":"Geometria plana","f":"Área e comprimento do círculo","v":"Área: π·r². Comprimento: 2·π·r. No ENEM geralmente π ≈ 3 ou 3,14.","id":"mat29"},{"t":"P","top":"Geometria plana","f":"Área do triângulo equilátero e altura","v":"Altura: L√3/2. Área: L²√3/4. Hexágono regular = 6 triângulos equiláteros: 6·L²√3/4.","id":"mat30"},{"t":"P","top":"Geometria plana","f":"Teorema de Pitágoras e ternas comuns","v":"a² = b² + c². Ternas: 3-4-5, 5-12-13, 8-15-17 e múltiplos (6-8-10).","m":"Decore as ternas 3-4-5 e 5-12-13: poupam conta na prova.","img":"mat_pitagoras","id":"mat31"},{"t":"P","top":"Geometria plana","f":"Soma dos ângulos internos de um polígono","v":"S = (n - 2)·180°. Triângulo 180°, quadrilátero 360°. Ângulo interno do regular = S/n.","id":"mat32"},{"t":"P","top":"Geometria plana","f":"Quais polígonos regulares pavimentam o plano sozinhos?","v":"Triângulo equilátero (60°), quadrado (90°) e hexágono (120°): os ângulos fecham 360° em volta de um ponto.","id":"mat33"},{"t":"P","top":"Geometria plana","f":"Semelhança de triângulos","v":"Ângulos iguais → lados proporcionais. Razão k entre lados → razão k² entre áreas. Usada em sombras e alturas de prédios.","m":"Lados x k → área x k².","id":"mat34"},{"t":"P","top":"Geometria plana","f":"Teorema de Tales","v":"Retas paralelas cortadas por transversais determinam segmentos proporcionais.","id":"mat35"},{"t":"P","top":"Geometria plana","f":"Razões trigonométricas no triângulo retângulo","v":"sen = cateto oposto/hipotenusa; cos = adjacente/hipotenusa; tg = oposto/adjacente (\"SOH CAH TOA\").","m":"\"SOH CAH TOA\": Seno = Oposto/Hipotenusa, Cosseno = Adjacente/Hipotenusa, Tangente = Oposto/Adjacente.","img":"mat_trig","id":"mat36"},{"t":"P","top":"Geometria plana","f":"Valores notáveis: 30°, 45°, 60°","v":"sen: 1/2, √2/2, √3/2. cos: √3/2, √2/2, 1/2. tg: √3/3, 1, √3.","m":"Seno de 30, 45, 60: \"1, 2, 3\": √1/2, √2/2, √3/2. O cosseno é a mesma lista ao contrário.","id":"mat37"},{"t":"P","top":"Geometria plana","f":"Lei dos senos e lei dos cossenos","v":"Senos: a/sen A = b/sen B = c/sen C. Cossenos: a² = b² + c² - 2bc·cos A.","id":"mat38"},{"t":"P","top":"Geometria espacial","f":"Volume do prisma e do cilindro","v":"V = área da base x altura. Cilindro: π·r²·h.","m":"Volume de \"coluna reta\" = base x altura.","img":"mat_solidos","id":"mat39"},{"t":"P","top":"Geometria espacial","f":"Volume da pirâmide e do cone","v":"V = (área da base x altura)/3. Cone: π·r²·h/3. Um cone tem 1/3 do volume do cilindro de mesma base e altura.","m":"\"Ponta tira dois terços\": pirâmide e cone = 1/3 do prisma/cilindro.","img":"mat_solidos","id":"mat40"},{"t":"P","top":"Geometria espacial","f":"Volume e área da esfera","v":"V = 4/3·π·r³. Área = 4·π·r².","m":"\"Quatro terços pi erre cubo\".","img":"mat_solidos","id":"mat41"},{"t":"P","top":"Geometria espacial","f":"Relação de Euler","v":"V - A + F = 2 (vértices - arestas + faces) em poliedros convexos.","m":"\"Vai A Fazer 2\": V − A + F = 2.","id":"mat42"},{"t":"P","top":"Geometria espacial","f":"Planificação: o que o ENEM costuma pedir?","v":"Reconhecer qual molde forma o sólido (cubo, cilindro, cone, prisma). Cilindro planificado = 2 círculos + retângulo de lado 2πr.","id":"mat43"},{"t":"P","top":"Geometria espacial","f":"Se dobrarmos o raio de uma esfera, o que acontece com o volume?","v":"Fica 8 vezes maior (2³). A área fica 4 vezes maior (2²).","id":"mat44"},{"t":"P","top":"Geometria espacial","f":"Vistas e projeções ortogonais","v":"Vista superior, frontal e lateral: imagine o sólido \"achatado\" sobre cada plano. Tema frequente no ENEM.","id":"mat45"},{"t":"P","top":"Estatística e probabilidade","f":"Média, mediana e moda","v":"Média: soma/quantidade. Mediana: valor central dos dados ordenados (com n par, média dos dois centrais). Moda: valor mais frequente.","m":"MEDIana = MEIO da fila ordenada. MOda = o que está na MODA (mais aparece).","id":"mat46"},{"t":"P","top":"Estatística e probabilidade","f":"Quando a mediana representa melhor os dados que a média?","v":"Quando há valores extremos (outliers), como salários com alguns muito altos: a média é puxada, a mediana não.","m":"","img":"mat_media_mediana","id":"mat47"},{"t":"P","top":"Estatística e probabilidade","f":"Desvio padrão: o que mede?","v":"A dispersão dos dados em torno da média. Menor desvio padrão = dados mais homogêneos, mais regulares.","m":"Desvio pequeno = \"turma certinha\", notas parecidas. Desvio grande = \"turma bagunçada\".","img":"mat_desvio","id":"mat48"},{"t":"P","top":"Estatística e probabilidade","f":"Variância e desvio padrão: como calcular","v":"Variância = média dos quadrados dos desvios (xi - média)². Desvio padrão = √variância.","id":"mat49"},{"t":"P","top":"Estatística e probabilidade","f":"Probabilidade: definição","v":"P = casos favoráveis / casos possíveis. Valor entre 0 e 1.","id":"mat50"},{"t":"P","top":"Estatística e probabilidade","f":"Probabilidade de eventos independentes simultâneos","v":"Multiplica: P(A e B) = P(A)·P(B).","id":"mat51"},{"t":"P","top":"Estatística e probabilidade","f":"Probabilidade da união","v":"P(A ou B) = P(A) + P(B) - P(A e B).","id":"mat52"},{"t":"P","top":"Estatística e probabilidade","f":"Probabilidade complementar: quando usar?","v":"Quando \"pelo menos um\" aparece: P(pelo menos um) = 1 - P(nenhum).","m":"\"Pelo menos um\" → calcule o NENHUM e faça 1 menos.","id":"mat53"},{"t":"P","top":"Estatística e probabilidade","f":"Probabilidade condicional","v":"P(A|B) = P(A e B)/P(B). O espaço amostral se reduz ao que já se sabe que aconteceu.","id":"mat54"},{"t":"P","top":"Estatística e probabilidade","f":"Princípio fundamental da contagem","v":"Etapas independentes: multiplique as possibilidades. Ex.: 3 camisas x 4 calças = 12 combinações.","id":"mat55"},{"t":"P","top":"Estatística e probabilidade","f":"Permutação, arranjo e combinação","v":"Permutação: n! (todos, ordem importa). Arranjo: n!/(n-p)! (alguns, ordem importa: pódio, senhas). Combinação: n!/(p!(n-p)!) (ordem não importa: comissões, grupos).","m":"ARRanjo = ARRuma em ordem (pódio). COMBinação = COMBina em grupo (sem ordem).","img":"mat_contagem","id":"mat56"},{"t":"P","top":"Estatística e probabilidade","f":"Permutação com repetição (anagramas)","v":"n!/(a!·b!...), dividindo pelos fatoriais das letras repetidas. Ex.: ARARA = 5!/(3!·2!) = 10.","id":"mat57"},{"t":"P","top":"Estatística e probabilidade","f":"Como identificar se a ordem importa?","v":"Troque dois elementos de lugar: se vira outra coisa (senha, pódio), a ordem importa (arranjo). Se é a mesma (grupo, salada), não importa (combinação).","m":"","img":"mat_contagem","id":"mat58"},{"t":"P","top":"Sequências","f":"Progressão aritmética (PA)","v":"Termo geral: an = a1 + (n - 1)·r. Soma: Sn = (a1 + an)·n/2.","m":"PA soma sempre o mesmo número (razão r). Soma dos termos: \"(primeiro + último) x quantidade / 2\", como o truque de Gauss.","id":"mat59"},{"t":"P","top":"Sequências","f":"Progressão geométrica (PG)","v":"Termo geral: an = a1·q^(n-1). Soma finita: Sn = a1·(q^n - 1)/(q - 1). Soma infinita (|q| &lt; 1): a1/(1 - q).","m":"PG multiplica sempre pelo mesmo número (razão q). Juros compostos são uma PG.","id":"mat60"},{"t":"P","top":"Estratégia de prova","f":"Ordem recomendada na prova de matemática do ENEM","v":"Faça primeiro as questões rápidas (porcentagem, leitura de gráfico, proporção), marque as longas e volte depois. Pela TRI, acertar as fáceis é o que mais pesa.","id":"mat61"},{"t":"P","top":"Estratégia de prova","f":"Como funciona a TRI no ENEM?","v":"Questões fáceis, médias e difíceis valem diferente, e a coerência conta: errar fáceis e acertar difíceis sugere chute e reduz a nota. Nunca deixe em branco.","id":"mat62"},{"t":"C","top":"Matemática básica e proporção","f":"1 m³ = ⟦1⟧ L; 1 dm³ = ⟦2⟧ L; 1 cm³ = ⟦3⟧ mL.","l":{"1":"1.000","2":"1","3":"1"},"id":"mat63"},{"t":"C","top":"Matemática básica e proporção","f":"Em um mapa de escala 1:200.000, 1 cm representa ⟦1⟧ km.","l":{"1":"2"},"id":"mat64"},{"t":"C","top":"Matemática básica e proporção","f":"Se 4 operários fazem uma obra em 12 dias, 6 operários a fazem em ⟦1⟧ dias (grandezas ⟦2⟧ proporcionais).","l":{"1":"8","2":"inversamente"},"id":"mat65"},{"t":"D","top":"Matemática básica e proporção","f":"Um mapa tem escala 1:50.000. Uma distância de 4 cm no mapa equivale a quantos km?","v":"2","x":"4 x 50.000 = 200.000 cm = 2 km.","id":"mat66"},{"t":"D","top":"Matemática básica e proporção","f":"Uma maquete na escala 1:100 tem área de 2 m². Qual a área real em m²?","v":"20000","x":"Área usa escala ao quadrado: 2 x 100² = 20.000 m².","id":"mat67"},{"t":"D","top":"Matemática básica e proporção","f":"MMC de 6 e 8?","v":"24","x":"Dois remédios de 6 em 6 h e 8 em 8 h coincidem a cada 24 h.","id":"mat68"},{"t":"D","top":"Matemática básica e proporção","f":"Média ponderada das notas 600 (peso 2) e 800 (peso 3)?","v":"720","x":"(600·2 + 800·3)/5 = 3600/5.","id":"mat69"},{"t":"V","top":"Matemática básica e proporção","f":"Se a escala de um mapa dobra, a área representada também dobra.","ok":false,"x":"A área é multiplicada por 4 (2²). Comprimento escala por k, área por k², volume por k³.","id":"mat70"},{"t":"F","top":"Porcentagem e matemática financeira","f":"Por que a curva vermelha cresce cada vez mais rápido?","v":"Nos <b>juros compostos</b> os juros de cada mês entram no capital do mês seguinte (juros sobre juros): crescimento <b>exponencial</b> (PG). Nos simples, o acréscimo é sempre igual (PA, reta).","img":"mat_juros","id":"mat71"},{"t":"C","top":"Porcentagem e matemática financeira","f":"Aumento de 25% equivale a multiplicar por ⟦1⟧; desconto de 30% equivale a multiplicar por ⟦2⟧.","l":{"1":"1,25","2":"0,7"},"id":"mat72"},{"t":"C","top":"Porcentagem e matemática financeira","f":"Juros simples: M = ⟦1⟧. Juros compostos: M = ⟦2⟧.","l":{"1":"C·(1 + i·t)","2":"C·(1 + i)^t"},"id":"mat73"},{"t":"C","top":"Porcentagem e matemática financeira","f":"Dois aumentos sucessivos de 10% equivalem a um aumento de ⟦1⟧%, porque 1,1 x 1,1 = ⟦2⟧.","l":{"1":"21","2":"1,21"},"id":"mat74"},{"t":"D","top":"Porcentagem e matemática financeira","f":"Um produto de R$ 200 tem desconto de 15%. Qual o novo preço em reais?","v":"170","x":"200 x 0,85.","id":"mat75"},{"t":"D","top":"Porcentagem e matemática financeira","f":"R$ 1.000 a juros compostos de 10% ao mês. Montante em reais após 2 meses?","v":"1210","x":"1000 x 1,1².","id":"mat76"},{"t":"D","top":"Porcentagem e matemática financeira","f":"Um preço sobe de R$ 80 para R$ 100. Qual o aumento percentual?","v":"25","x":"(100 − 80)/80 = 0,25.","id":"mat77"},{"t":"V","top":"Porcentagem e matemática financeira","f":"Um desconto de 20% seguido de um aumento de 20% devolve o preço original.","ok":false,"x":"0,8 x 1,2 = 0,96: o preço final é 4% menor.","id":"mat78"},{"t":"F","top":"Funções","f":"Um táxi cobra R$ 5 de bandeirada e R$ 2 por km. Escreva a função e diga o que a e b significam.","v":"<b>f(x) = 2x + 5.</b> a = 2 é a taxa (preço por km, inclinação da reta). b = 5 é o valor inicial (bandeirada, onde a reta corta o eixo y).","img":"mat_afim","id":"mat79"},{"t":"F","top":"Funções","f":"Em qual caso a parábola não toca o eixo x, e por quê?","v":"Quando <b>Δ &lt; 0</b>: a equação ax² + bx + c = 0 não tem raiz real, então o gráfico não cruza o eixo x.","img":"mat_parabola","id":"mat80"},{"t":"C","top":"Funções","f":"O vértice da parábola tem x = ⟦1⟧ e y = ⟦2⟧.","l":{"1":"−b/(2a)","2":"−Δ/(4a)"},"id":"mat81"},{"t":"C","top":"Funções","f":"Se a &gt; 0, a parábola tem concavidade para ⟦1⟧ e o vértice é ponto de ⟦2⟧.","l":{"1":"cima","2":"mínimo"},"id":"mat82"},{"t":"C","top":"Funções","f":"Soma das raízes de ax² + bx + c = 0: ⟦1⟧. Produto: ⟦2⟧.","l":{"1":"−b/a","2":"c/a"},"id":"mat83"},{"t":"C","top":"Funções","f":"log(a·b) = ⟦1⟧; log(a^n) = ⟦2⟧.","l":{"1":"log a + log b","2":"n·log a"},"id":"mat84"},{"t":"D","top":"Funções","f":"Calcule log₂ 32.","v":"5","x":"2^5 = 32.","id":"mat85"},{"t":"D","top":"Funções","f":"Qual o x do vértice de f(x) = x² − 6x + 5?","v":"3","x":"xv = −b/(2a) = 6/2.","id":"mat86"},{"t":"D","top":"Funções","f":"Quantas raízes reais tem uma equação de 2º grau com Δ = 0?","v":"1","x":"Raiz dupla: a parábola só toca o eixo x.","id":"mat87"},{"t":"D","top":"Funções","f":"Para f(x) = −x² + 4x, qual o valor máximo?","v":"4","x":"xv = 2; f(2) = −4 + 8 = 4.","id":"mat88"},{"t":"V","top":"Funções","f":"A função f(x) = 0,8^x é crescente.","ok":false,"x":"Base entre 0 e 1 dá função exponencial DECRESCENTE (como depreciação).","id":"mat89"},{"t":"F","top":"Geometria plana","f":"Uma escada de 10 m faz 30° com o chão. A que altura ela toca a parede?","v":"A altura é o cateto <b>oposto</b> a 30° e a escada é a hipotenusa: sen 30° = h/10 → h = 10 · 1/2 = <b>5 m</b>.","img":"mat_trig","id":"mat90"},{"t":"F","top":"Geometria plana","f":"Um triângulo retângulo tem catetos 6 e 8. Qual a hipotenusa?","v":"<b>10</b> (terna 3-4-5 multiplicada por 2). Conferindo: 6² + 8² = 36 + 64 = 100.","img":"mat_pitagoras","id":"mat91"},{"t":"C","top":"Geometria plana","f":"sen 30° = ⟦1⟧; cos 60° = ⟦2⟧; tg 45° = ⟦3⟧.","l":{"1":"1/2","2":"1/2","3":"1"},"id":"mat92"},{"t":"C","top":"Geometria plana","f":"Área do círculo: ⟦1⟧. Comprimento da circunferência: ⟦2⟧.","l":{"1":"π·r²","2":"2·π·r"},"id":"mat93"},{"t":"C","top":"Geometria plana","f":"Soma dos ângulos internos de um polígono de n lados: ⟦1⟧. Num hexágono: ⟦2⟧.","l":{"1":"(n − 2)·180°","2":"720°"},"id":"mat94"},{"t":"D","top":"Geometria plana","f":"Área de um trapézio com bases 10 e 6 e altura 4?","v":"32","x":"(10 + 6)·4/2.","id":"mat95"},{"t":"D","top":"Geometria plana","f":"Área de um círculo de raio 5 (use π = 3)?","v":"75","x":"3 x 5².","id":"mat96"},{"t":"D","top":"Geometria plana","f":"Quanto mede cada ângulo interno de um hexágono regular (em graus)?","v":"120","x":"720/6.","id":"mat97"},{"t":"V","top":"Geometria plana","f":"Se dobrarmos os lados de um quadrado, sua área também dobra.","ok":false,"x":"A área quadruplica (2² = 4).","id":"mat98"},{"t":"F","top":"Geometria espacial","f":"Um cilindro e um cone têm mesmo raio e mesma altura. Quantos cones enchem o cilindro?","v":"<b>3 cones</b>, pois V(cone) = πr²h/3 = 1/3 do cilindro.","img":"mat_solidos","id":"mat99"},{"t":"C","top":"Geometria espacial","f":"Volume do cilindro: ⟦1⟧. Volume do cone: ⟦2⟧. Volume da esfera: ⟦3⟧.","l":{"1":"π·r²·h","2":"π·r²·h/3","3":"4/3·π·r³"},"id":"mat100"},{"t":"C","top":"Geometria espacial","f":"Relação de Euler: V − A + F = ⟦1⟧.","l":{"1":"2"},"id":"mat101"},{"t":"D","top":"Geometria espacial","f":"Volume (m³) de uma caixa de 2 m x 3 m x 4 m?","v":"24","x":"Comprimento x largura x altura.","id":"mat102"},{"t":"D","top":"Geometria espacial","f":"Quantos litros cabem nessa caixa de 24 m³?","v":"24000","x":"1 m³ = 1.000 L.","id":"mat103"},{"t":"D","top":"Geometria espacial","f":"Um cubo tem 8 vértices e 6 faces. Quantas arestas?","v":"12","x":"V − A + F = 2 → 8 − A + 6 = 2.","id":"mat104"},{"t":"V","top":"Geometria espacial","f":"Dobrar o raio de um cilindro (mantendo a altura) dobra seu volume.","ok":false,"x":"O volume quadruplica, pois depende de r².","id":"mat105"},{"t":"F","top":"Estatística e probabilidade","f":"Por que a mediana representa melhor esses salários?","v":"Há um <b>valor extremo</b> (30 mil) que puxa a média para 6,9 mil, acima de quase todos. A <b>mediana (3 mil)</b> fica no meio dos dados ordenados e não se deixa levar pelo outlier.","img":"mat_media_mediana","id":"mat106"},{"t":"F","top":"Estatística e probabilidade","f":"Duas turmas têm a mesma média. Qual é mais regular?","v":"A <b>verde</b>: desvio padrão menor, notas concentradas perto da média. A laranja tem notas mais espalhadas.","img":"mat_desvio","id":"mat107"},{"t":"F","top":"Estatística e probabilidade","f":"De quantas formas podemos formar uma comissão de 2 pessoas entre 5?","v":"Ordem não importa → <b>combinação</b>: C(5,2) = 5!/(2!·3!) = <b>10</b>.","img":"mat_contagem","id":"mat108"},{"t":"C","top":"Estatística e probabilidade","f":"Mediana de 3, 7, 1, 9, 5: ordenando (1, 3, 5, 7, 9), a mediana é ⟦1⟧.","l":{"1":"5"},"id":"mat109"},{"t":"C","top":"Estatística e probabilidade","f":"Probabilidade de sair \"cara\" em 3 lançamentos seguidos de uma moeda: ⟦1⟧. Probabilidade de sair pelo menos uma \"coroa\": ⟦2⟧.","l":{"1":"1/8","2":"7/8"},"id":"mat110"},{"t":"C","top":"Estatística e probabilidade","f":"P(A ou B) = P(A) + P(B) − ⟦1⟧.","l":{"1":"P(A e B)"},"id":"mat111"},{"t":"C","top":"Estatística e probabilidade","f":"Escolher presidente e vice entre 10 pessoas é ⟦1⟧ (10 x 9 = ⟦2⟧); escolher 2 representantes iguais é ⟦3⟧ (⟦4⟧).","l":{"1":"arranjo","2":"90","3":"combinação","4":"45"},"id":"mat112"},{"t":"D","top":"Estatística e probabilidade","f":"Quantos anagramas tem a palavra AMOR?","v":"24","x":"4! = 24.","id":"mat113"},{"t":"D","top":"Estatística e probabilidade","f":"Moda do conjunto 2, 3, 3, 5, 7, 3, 8?","v":"3","x":"Aparece 3 vezes.","id":"mat114"},{"t":"D","top":"Estatística e probabilidade","f":"Média de 4, 6, 8 e 10?","v":"7","x":"28/4.","id":"mat115"},{"t":"D","top":"Estatística e probabilidade","f":"Um dado é lançado. Qual a probabilidade de sair número par? (fração)","v":"1/2","x":"3 pares em 6 faces.","id":"mat116"},{"t":"D","top":"Estatística e probabilidade","f":"Quantas combinações de 3 camisas e 4 calças são possíveis?","v":"12","x":"Princípio multiplicativo: 3 x 4.","id":"mat117"},{"t":"D","top":"Estatística e probabilidade","f":"Quantos anagramas tem ARARA?","v":"10","x":"5!/(3!·2!) = 120/12.","id":"mat118"},{"t":"V","top":"Estatística e probabilidade","f":"Se a média de um grupo é 7, então metade das notas está acima de 7.","ok":false,"x":"Isso vale para a MEDIANA. A média pode ser puxada por valores extremos.","id":"mat119"},{"t":"V","top":"Estatística e probabilidade","f":"A probabilidade de \"pelo menos um 6\" em dois lançamentos de dado é 2/6.","ok":false,"x":"É 1 − (5/6)² = 11/36. Use o complementar (\"nenhum 6\").","id":"mat120"},{"t":"C","top":"Sequências","f":"Termo geral da PA: an = ⟦1⟧. Termo geral da PG: an = ⟦2⟧.","l":{"1":"a1 + (n − 1)·r","2":"a1·q^(n − 1)"},"id":"mat121"},{"t":"D","top":"Sequências","f":"Qual o 10º termo da PA 3, 7, 11, ...?","v":"39","x":"a10 = 3 + 9·4.","id":"mat122"},{"t":"D","top":"Sequências","f":"Soma dos números de 1 a 100?","v":"5050","x":"(1 + 100)·100/2.","id":"mat123"},{"t":"D","top":"Sequências","f":"Qual o 5º termo da PG 2, 6, 18, ...?","v":"162","x":"2 · 3⁴.","id":"mat124"}]},{"id":"red","nome":"Redação","ic":"✍️","cards":[{"t":"P","top":"As 5 competências","f":"Competência 1","v":"Domínio da norma padrão da língua escrita: ortografia, acentuação, concordância, regência, pontuação e estrutura sintática (sem frases fragmentadas ou truncadas).","m":"C1 = Correção (gramática).","id":"red0"},{"t":"P","top":"As 5 competências","f":"Competência 2","v":"Compreender a proposta e desenvolver o tema dentro do tipo dissertativo-argumentativo, usando repertório sociocultural legitimado, pertinente e PRODUTIVO.","m":"C2 = Compreender o tema + repertório.","id":"red1"},{"t":"P","top":"As 5 competências","f":"Competência 3","v":"Selecionar, relacionar, organizar e interpretar informações em defesa de um ponto de vista (projeto de texto e argumentação consistente).","m":"C3 = Coerência dos argumentos (projeto de texto).","id":"red2"},{"t":"P","top":"As 5 competências","f":"Competência 4","v":"Conhecimento dos mecanismos linguísticos de coesão: conectivos entre parágrafos e dentro deles, retomadas sem repetição.","m":"C4 = Conectivos (coesão).","id":"red3"},{"t":"P","top":"As 5 competências","f":"Competência 5","v":"Proposta de intervenção detalhada para o problema, respeitando os direitos humanos.","m":"C5 = Conserto do problema (proposta).","id":"red4"},{"t":"P","top":"As 5 competências","f":"Quanto vale cada competência?","v":"200 pontos cada (níveis 0, 40, 80, 120, 160, 200). Total 1000. Dois corretores; se a diferença for maior que 100 no total ou 80 em uma competência, um terceiro corrige.","m":"\"5 x 200 = 1000\". Níveis sobem de 40 em 40.","img":"red_competencias","id":"red5"},{"t":"P","top":"As 5 competências","f":"O que zera a redação?","v":"Fuga total ao tema, não ser dissertativo-argumentativo, até 7 linhas, parte desconectada (cópia de letra de música, receita), desrespeito aos direitos humanos, folha em branco, identificação, texto em outra língua.","id":"red6"},{"t":"P","top":"As 5 competências","f":"Diferença entre fuga ao tema e tangenciamento","v":"Fuga total zera. Tangenciar (abordar só o assunto amplo, não o recorte) limita a C2 a 40 pontos e afeta C3 e C5.","id":"red7"},{"t":"P","top":"Estrutura do texto","f":"Estrutura mais segura: quantos parágrafos e linhas?","v":"4 parágrafos: introdução, 2 de desenvolvimento, conclusão. Cerca de 28 a 30 linhas (mínimo 8, máximo 30).","m":"","img":"red_estrutura","id":"red8"},{"t":"P","top":"Estrutura do texto","f":"O que a introdução precisa ter?","v":"Contextualização (repertório de abertura), apresentação do tema com as palavras-chave do recorte e a tese, de preferência anunciando os dois argumentos.","m":"\"Contexto → Tema → Tese\": abra com repertório, apresente o recorte e diga o que vai defender.","id":"red9"},{"t":"P","top":"Estrutura do texto","f":"O que é tese?","v":"O ponto de vista que você vai defender sobre o tema. Ex.: \"os desafios decorrem da negligência estatal e da desinformação social\".","id":"red10"},{"t":"P","top":"Estrutura do texto","f":"Estrutura de um parágrafo de desenvolvimento","v":"Tópico frasal (ideia central ligada à tese) → repertório → explicação/análise (por quê, como, consequência) → fechamento ligando ao tema.","m":"\"TRAF\": Tópico frasal, Repertório, Análise, Fechamento.","id":"red11"},{"t":"P","top":"Estrutura do texto","f":"O que a conclusão precisa ter?","v":"Retomada breve da tese e a proposta de intervenção completa (os 5 elementos). Pode fechar com retomada do repertório da introdução.","id":"red12"},{"t":"P","top":"Estrutura do texto","f":"Tópico frasal","v":"Primeira frase do parágrafo, que anuncia o argumento. Ex.: \"Em primeiro lugar, a omissão governamental agrava o problema.\"","id":"red13"},{"t":"P","top":"Proposta de intervenção (C5)","f":"Os 5 elementos da proposta de intervenção","v":"Agente (quem), ação (o quê), modo/meio (como), finalidade (para quê) e detalhamento (mais informação sobre qualquer um deles).","m":"Pergunte: QUEM? O QUÊ? COMO? PARA QUÊ? + um DETALHE.","img":"red_proposta","id":"red14"},{"t":"P","top":"Proposta de intervenção (C5)","f":"Exemplo de proposta completa","v":"\"Cabe ao Ministério da Educação (agente) incluir educação digital no currículo (ação), por meio de oficinas nas escolas públicas (meio), a fim de reduzir a desinformação (finalidade). Essas oficinas, ministradas por especialistas, ... (detalhamento).\"","id":"red15"},{"t":"P","top":"Proposta de intervenção (C5)","f":"Agentes frequentes e úteis","v":"Ministérios (Educação, Saúde, Cidadania), Poder Legislativo, mídia/veículos de comunicação, escolas, ONGs, família, empresas. Evite agentes vagos como \"a sociedade\" ou \"alguém\".","m":"Um agente para cada argumento: assim a proposta conversa com o desenvolvimento.","id":"red16"},{"t":"P","top":"Proposta de intervenção (C5)","f":"Erro comum na proposta de intervenção","v":"Ser vaga (\"o governo deve resolver\") ou não se articular aos problemas apontados no desenvolvimento. Proponha uma solução para cada argumento.","id":"red17"},{"t":"P","top":"Proposta de intervenção (C5)","f":"O que significa \"respeitar os direitos humanos\" na proposta?","v":"Não propor violência, tortura, pena de morte, \"justiça com as próprias mãos\", exclusão de grupos. Desrespeito zera a C5.","id":"red18"},{"t":"P","top":"Repertório sociocultural","f":"O que torna um repertório \"produtivo\"?","v":"Ser legitimado (fonte reconhecível), pertinente ao tema e, sobretudo, articulado ao argumento: precisa ser explicado e usado, não só citado.","id":"red19"},{"t":"P","top":"Repertório sociocultural","f":"Constituição Federal de 1988: artigos coringas","v":"Art. 5º (igualdade e direitos individuais), art. 6º (direitos sociais: educação, saúde, moradia, lazer, segurança), art. 196 (saúde direito de todos e dever do Estado), art. 205 (educação).","id":"red20"},{"t":"P","top":"Repertório sociocultural","f":"Zygmunt Bauman","v":"Modernidade líquida: relações frágeis, efêmeras e consumistas. Serve para temas de redes sociais, consumo, solidão, relações.","m":"Bauman = \"tudo LÍQUIDO escorre\": relações que não duram.","id":"red21"},{"t":"P","top":"Repertório sociocultural","f":"Émile Durkheim","v":"Fato social (coercitivo, exterior, geral) e anomia (enfraquecimento das normas sociais). Bom para violência, desigualdade, instituições.","m":"Durkheim = \"fato social\" e \"anomia\" (sociedade sem regras firmes).","id":"red22"},{"t":"P","top":"Repertório sociocultural","f":"Pierre Bourdieu","v":"Violência simbólica e capital cultural: a escola e a cultura reproduzem desigualdades. Bom para educação, preconceito, acesso à cultura.","id":"red23"},{"t":"P","top":"Repertório sociocultural","f":"Hannah Arendt","v":"Banalidade do mal: pessoas comuns praticam atrocidades por obediência e falta de reflexão. Bom para violência, discurso de ódio, intolerância.","m":"Arendt = \"o mal pode ser BANAL\": gente comum obedecendo sem pensar.","id":"red24"},{"t":"P","top":"Repertório sociocultural","f":"Paulo Freire","v":"Educação libertadora e crítica (\"se a educação sozinha não transforma a sociedade, sem ela tampouco a sociedade muda\"). Coringa para educação.","id":"red25"},{"t":"P","top":"Repertório sociocultural","f":"Sérgio Buarque de Holanda","v":"\"Homem cordial\": confusão entre público e privado, personalismo. Bom para corrupção, patrimonialismo.","id":"red26"},{"t":"P","top":"Repertório sociocultural","f":"Gilberto Dimenstein","v":"\"O cidadão de papel\": direitos garantidos na lei, mas não na prática. Coringa para quase todo tema de direitos sociais.","m":"\"Cidadão de PAPEL\": o direito está no papel, não na vida real.","id":"red27"},{"t":"P","top":"Repertório sociocultural","f":"Michel Foucault","v":"Panóptico e sociedade disciplinar: vigilância e controle. Bom para tecnologia, privacidade, dados, sistema prisional.","id":"red28"},{"t":"P","top":"Repertório sociocultural","f":"Byung-Chul Han","v":"Sociedade do cansaço e da transparência: excesso de desempenho, esgotamento, exposição nas redes. Bom para saúde mental, trabalho, internet.","id":"red29"},{"t":"P","top":"Repertório sociocultural","f":"Djamila Ribeiro / racismo estrutural (Silvio Almeida)","v":"Racismo está nas estruturas (instituições, economia), não só em atos individuais. Bom para temas de raça, desigualdade e violência.","id":"red30"},{"t":"P","top":"Repertório sociocultural","f":"Repertório de dados: como usar com segurança?","v":"Use instituições reconhecidas (IBGE, OMS, ONU, Ipea) sem inventar números precisos. Melhor: \"segundo o IBGE, milhões de brasileiros...\" do que um número errado.","id":"red31"},{"t":"P","top":"Repertório sociocultural","f":"Temas das últimas redações do ENEM","v":"2019: democratização do acesso ao cinema. 2020: estigma associado às doenças mentais. 2021: invisibilidade e registro civil. 2022: povos e comunidades tradicionais. 2023: trabalho de cuidado realizado pela mulher. 2024: herança africana no Brasil.","id":"red32"},{"t":"P","top":"Coesão (C4)","f":"Conectivos para iniciar o 1º parágrafo de desenvolvimento","v":"Em primeiro lugar; Primeiramente; De início; Sob esse viés; Nesse sentido.","m":"","img":"red_conectivos","id":"red33"},{"t":"P","top":"Coesão (C4)","f":"Conectivos para iniciar o 2º parágrafo de desenvolvimento","v":"Além disso; Ademais; Paralelamente; Somado a isso; Outrossim; Em segundo plano.","id":"red34"},{"t":"P","top":"Coesão (C4)","f":"Conectivos de conclusão","v":"Portanto; Dessa forma; Logo; Diante do exposto; Assim; Em suma.","id":"red35"},{"t":"P","top":"Coesão (C4)","f":"Conectivos de oposição (adversativos e concessivos)","v":"Adversativos: mas, porém, contudo, todavia, no entanto, entretanto. Concessivos: embora, ainda que, mesmo que, apesar de (com verbo no subjuntivo nos três primeiros).","m":"\"Embora\" e \"ainda que\" pedem SUBJUNTIVO: \"Embora EXISTAM leis...\" (não \"existem\").","id":"red36"},{"t":"P","top":"Coesão (C4)","f":"Conectivos de causa e de consequência","v":"Causa: porque, visto que, já que, uma vez que, porquanto. Consequência: de modo que, de forma que, tanto que, por conseguinte.","id":"red37"},{"t":"P","top":"Coesão (C4)","f":"Conectivos de finalidade (úteis na proposta)","v":"A fim de, para que, com o intuito de, com o objetivo de, de modo a.","id":"red38"},{"t":"P","top":"Coesão (C4)","f":"Recursos de coesão referencial","v":"Pronomes (esse, tal, isso), sinônimos, hiperônimos (\"o problema\", \"essa conjuntura\"), elipse. Evitam repetir as palavras do tema várias vezes.","id":"red39"},{"t":"P","top":"Coesão (C4)","f":"Por que repetir \"isso\" e \"esse\" demais prejudica?","v":"Retomadas pouco variadas e ambíguas reduzem a nota na C4. Varie com expressões nominais: \"esse cenário\", \"tal panorama\", \"essa problemática\".","id":"red40"},{"t":"P","top":"Erros de norma (C1)","f":"Crase: regra básica","v":"A + a (preposição + artigo). Ocorre antes de palavra feminina quando o verbo ou nome exige \"a\". Nunca antes de verbo, masculino, pronomes pessoais e \"uma\". Ex.: \"Refiro-me à questão\".","m":"\"Troque por masculino\": se virar \"ao\", tem crase (\"vou à escola\" → \"vou ao colégio\").","id":"red41"},{"t":"P","top":"Erros de norma (C1)","f":"Vírgula entre sujeito e verbo","v":"Proibida. Errado: \"A desigualdade social, afeta o país.\" Certo: \"A desigualdade social afeta o país.\"","id":"red42"},{"t":"P","top":"Erros de norma (C1)","f":"\"Haver\" no sentido de existir","v":"Impessoal, fica no singular: \"Há muitos problemas\" / \"Havia dificuldades\" (não \"haviam\").","m":"\"HAVER = EXISTIR, fica no SINGULAR\": \"houve problemas\", \"havia leis\".","id":"red43"},{"t":"P","top":"Erros de norma (C1)","f":"Onde x aonde","v":"Onde: lugar fixo (verbo sem preposição a): \"onde você mora\". Aonde: movimento (a + onde): \"aonde você vai\". Na redação, use \"onde\" só para lugar físico; para ideias, prefira \"em que\".","id":"red44"},{"t":"P","top":"Erros de norma (C1)","f":"Mal x mau","v":"Mal é o oposto de bem (advérbio/substantivo). Mau é o oposto de bom (adjetivo). \"Mal-estar\", \"mau exemplo\".","m":"Mal x Bem; Mau x Bom (troque e veja qual faz sentido).","id":"red45"},{"t":"P","top":"Erros de norma (C1)","f":"Por que, porque, por quê, porquê","v":"Por que: pergunta ou \"pelo qual\". Porque: explicação (pois). Por quê: fim de frase. Porquê: substantivo (\"o porquê\").","id":"red46"},{"t":"P","top":"Erros de norma (C1)","f":"Período muito longo ou truncado","v":"Frases com mais de 3 ou 4 linhas sem pausa ou frases sem verbo principal prejudicam C1. Prefira períodos de 2 a 3 linhas.","id":"red47"},{"t":"P","top":"Erros de norma (C1)","f":"Registro informal a evitar","v":"Gírias, \"a gente\", \"tipo\", \"né\", primeira pessoa do singular (\"eu acho\"), perguntas retóricas em excesso e clichês (\"hoje em dia\", \"desde os primórdios\").","id":"red48"},{"t":"P","top":"Treino da reta final","f":"Como usar os 9 dias até a prova para a redação","v":"Escreva pelo menos 3 redações completas cronometradas (cerca de 1h10) e revise com as 5 competências. Monte 3 a 4 repertórios coringa e uma proposta de intervenção modelo.","id":"red49"},{"t":"P","top":"Treino da reta final","f":"Quanto tempo reservar para a redação no 1º dia?","v":"Cerca de 1h10 a 1h20 (rascunho rápido + passar a limpo). Muitos preferem fazer a redação logo depois de 1 bloco de questões, com a cabeça fresca.","id":"red50"},{"t":"R","top":"As 5 competências","f":"Competência 1","v":"Norma padrão: ortografia, concordância, regência, pontuação, crase.","m":"C1 = Correção (gramática).","id":"red51"},{"t":"R","top":"As 5 competências","f":"Competência 2","v":"Compreender a proposta, tipo dissertativo-argumentativo e repertório produtivo.","m":"C2 = Compreender o tema + repertório.","id":"red52"},{"t":"R","top":"As 5 competências","f":"Competência 3","v":"Selecionar e organizar argumentos em defesa de um ponto de vista.","m":"C3 = Coerência dos argumentos (projeto de texto).","id":"red53"},{"t":"R","top":"As 5 competências","f":"Competência 4","v":"Coesão: conectivos e retomadas.","m":"C4 = Conectivos (coesão).","id":"red54"},{"t":"R","top":"As 5 competências","f":"Competência 5","v":"Proposta de intervenção completa e que respeita os direitos humanos.","m":"C5 = Conserto do problema (proposta).","id":"red55"},{"t":"F","top":"As 5 competências","f":"Qual competência é afetada por conectivos repetidos ou mal usados?","v":"<b>C4</b> (coesão).","img":"red_competencias","id":"red56"},{"t":"V","top":"As 5 competências","f":"Tangenciar o tema zera a redação.","ok":false,"x":"Tangenciar limita a C2 (até 40 pontos) e prejudica outras competências. O que zera é a FUGA TOTAL ao tema.","id":"red57"},{"t":"V","top":"As 5 competências","f":"Uma redação com 8 linhas é zerada por ser curta demais.","ok":false,"x":"Zera com ATÉ 7 linhas. Com 8 já é corrigida, mas terá nota baixa por falta de desenvolvimento.","id":"red58"},{"t":"V","top":"As 5 competências","f":"Usar repertório só citando o nome do autor, sem explicar, já garante 200 na C2.","ok":false,"x":"O repertório precisa ser PRODUTIVO: articulado e explicado dentro do argumento.","id":"red59"},{"t":"F","top":"Estrutura do texto","f":"O que vai em cada um dos 4 parágrafos?","v":"<b>Introdução:</b> repertório + tema + tese (anuncia 2 argumentos). <b>D1 e D2:</b> tópico frasal + repertório + análise + fechamento. <b>Conclusão:</b> retoma a tese + proposta com os 5 elementos.","img":"red_estrutura","id":"red60"},{"t":"C","top":"Estrutura do texto","f":"Estrutura de um parágrafo de desenvolvimento: ⟦1⟧ → ⟦2⟧ → ⟦3⟧ → ⟦4⟧.","l":{"1":"tópico frasal","2":"repertório","3":"análise","4":"fechamento"},"id":"red61"},{"t":"C","top":"Estrutura do texto","f":"A introdução deve ter contextualização, apresentação do ⟦1⟧ e a ⟦2⟧, de preferência anunciando os dois ⟦3⟧.","l":{"1":"tema","2":"tese","3":"argumentos"},"id":"red62"},{"t":"C","top":"Estrutura do texto","f":"A redação do ENEM deve ter no mínimo ⟦1⟧ e no máximo ⟦2⟧ linhas.","l":{"1":"8","2":"30"},"id":"red63"},{"t":"D","top":"Estrutura do texto","f":"Quantas linhas no máximo pode ter a redação do ENEM?","v":"30","x":"E o ideal é usar de 25 a 30.","id":"red64"},{"t":"F","top":"Proposta de intervenção (C5)","f":"Monte uma proposta completa para \"desinformação nas redes\".","v":"Ex.: <b>O Ministério da Educação</b> (agente) deve <b>incluir educação midiática no currículo</b> (ação), <b>por meio de oficinas nas escolas públicas</b> (meio), <b>a fim de formar leitores críticos</b> (finalidade). Essas oficinas, <b>conduzidas por jornalistas e professores capacitados</b>, ... (detalhamento).","img":"red_proposta","id":"red65"},{"t":"C","top":"Proposta de intervenção (C5)","f":"Os 5 elementos da proposta de intervenção são ⟦1⟧, ⟦2⟧, ⟦3⟧, ⟦4⟧ e ⟦5⟧.","l":{"1":"agente","2":"ação","3":"meio/modo","4":"finalidade","5":"detalhamento"},"id":"red66"},{"t":"C","top":"Proposta de intervenção (C5)","f":"\"A fim de\", \"com o intuito de\" e \"para que\" introduzem a ⟦1⟧; \"por meio de\" e \"mediante\" introduzem o ⟦2⟧.","l":{"1":"finalidade","2":"meio"},"id":"red67"},{"t":"V","top":"Proposta de intervenção (C5)","f":"\"O governo deve resolver o problema da violência\" é uma proposta de intervenção completa.","ok":false,"x":"Falta ação concreta, meio, finalidade e detalhamento; o agente também é vago (\"governo\").","id":"red68"},{"t":"V","top":"Proposta de intervenção (C5)","f":"Propor pena de morte para criminosos garante pontos na C5 por ser uma solução.","ok":false,"x":"Desrespeita os direitos humanos: a C5 vai a ZERO.","id":"red69"},{"t":"R","top":"Repertório sociocultural","f":"Modernidade líquida","v":"Zygmunt Bauman","id":"red70"},{"t":"R","top":"Repertório sociocultural","f":"Banalidade do mal","v":"Hannah Arendt","id":"red71"},{"t":"R","top":"Repertório sociocultural","f":"Fato social e anomia","v":"Émile Durkheim","id":"red72"},{"t":"R","top":"Repertório sociocultural","f":"Violência simbólica e capital cultural","v":"Pierre Bourdieu","id":"red73"},{"t":"R","top":"Repertório sociocultural","f":"Educação libertadora e crítica","v":"Paulo Freire","id":"red74"},{"t":"R","top":"Repertório sociocultural","f":"Homem cordial (público x privado)","v":"Sérgio Buarque de Holanda","id":"red75"},{"t":"R","top":"Repertório sociocultural","f":"Cidadão de papel","v":"Gilberto Dimenstein","id":"red76"},{"t":"R","top":"Repertório sociocultural","f":"Sociedade do cansaço","v":"Byung-Chul Han","id":"red77"},{"t":"R","top":"Repertório sociocultural","f":"Panóptico e sociedade disciplinar","v":"Michel Foucault","id":"red78"},{"t":"R","top":"Repertório sociocultural","f":"Racismo estrutural","v":"Silvio Almeida","id":"red79"},{"t":"C","top":"Repertório sociocultural","f":"O artigo ⟦1⟧ da Constituição lista os direitos sociais: educação, saúde, alimentação, trabalho, moradia, lazer, segurança...","l":{"1":"6º"},"id":"red80"},{"t":"C","top":"Repertório sociocultural","f":"O artigo ⟦1⟧ da Constituição diz que a saúde é direito de todos e dever do ⟦2⟧.","l":{"1":"196","2":"Estado"},"id":"red81"},{"t":"D","top":"Repertório sociocultural","f":"Tema da redação do ENEM 2023 (palavra-chave do trabalho)?","v":"trabalho de cuidado","x":"\"Desafios para o enfrentamento da invisibilidade do trabalho de cuidado realizado pela mulher no Brasil\".","id":"red82"},{"t":"R","top":"Coesão (C4)","f":"Ademais","v":"Conectivo de adição (= além disso).","id":"red83"},{"t":"R","top":"Coesão (C4)","f":"Todavia","v":"Conectivo de oposição (= mas, porém).","id":"red84"},{"t":"R","top":"Coesão (C4)","f":"Porquanto","v":"Conectivo de causa (= porque, visto que).","id":"red85"},{"t":"R","top":"Coesão (C4)","f":"Por conseguinte","v":"Conectivo de conclusão/consequência (= portanto).","id":"red86"},{"t":"R","top":"Coesão (C4)","f":"Outrossim","v":"Conectivo de adição (= igualmente, também).","id":"red87"},{"t":"R","top":"Coesão (C4)","f":"Mediante","v":"Conectivo de meio/modo (= por meio de).","id":"red88"},{"t":"C","top":"Coesão (C4)","f":"Para iniciar a conclusão, use ⟦1⟧, ⟦2⟧ ou ⟦3⟧.","l":{"1":"Portanto","2":"Dessa forma","3":"Diante do exposto"},"id":"red89"},{"t":"C","top":"Coesão (C4)","f":"\"Embora\", \"ainda que\" e \"mesmo que\" são conectivos ⟦1⟧ e exigem verbo no ⟦2⟧.","l":{"1":"concessivos","2":"subjuntivo"},"id":"red90"},{"t":"V","top":"Coesão (C4)","f":"\"Porém\" e \"embora\" podem ser trocados livremente na mesma frase.","ok":false,"x":"\"Porém\" é adversativo (verbo no indicativo, nova oração). \"Embora\" é concessivo e exige subjuntivo: \"Embora haja leis, ...\" x \"Há leis; porém, ...\".","id":"red91"},{"t":"C","top":"Erros de norma (C1)","f":"\"⟦1⟧ muitos desafios\" (verbo haver = existir, singular). \"⟦2⟧ problemas\" (não \"haviam\").","l":{"1":"Há","2":"Havia"},"id":"red92"},{"t":"C","top":"Erros de norma (C1)","f":"Refiro-me ⟦1⟧ questão social. Refiro-me ⟦2⟧ esse problema. Fui ⟦3⟧ pé.","l":{"1":"à","2":"a","3":"a"},"id":"red93"},{"t":"D","top":"Erros de norma (C1)","f":"Corrija: \"Haviam muitas pessoas no local.\"","v":"Havia muitas pessoas no local.","x":"Haver no sentido de existir é impessoal: fica no singular.","id":"red94"},{"t":"D","top":"Erros de norma (C1)","f":"Corrija: \"A desigualdade social, afeta o país.\"","v":"A desigualdade social afeta o país.","x":"Nunca use vírgula entre sujeito e verbo.","id":"red95"},{"t":"V","top":"Erros de norma (C1)","f":"\"Ele chegou mau-humorado\" está correto.","ok":false,"x":"O certo é \"mal-humorado\": \"mal\" é o contrário de \"bem\" (bem-humorado).","id":"red96"},{"t":"V","top":"Erros de norma (C1)","f":"Na frase \"Assisti ao filme\", não há crase porque \"filme\" é masculino.","ok":true,"x":"Antes de palavra masculina não há crase; aqui há só preposição + artigo masculino (\"ao\").","id":"red97"}]},{"id":"ling","nome":"Linguagens","ic":"📚","cards":[{"t":"P","top":"Interpretação e funções da linguagem","f":"Função referencial (denotativa)","v":"Foco na informação, no assunto. Linguagem objetiva. Notícias, textos científicos, verbetes.","m":"Cada função = um elemento da comunicação: emissor-EMOTIVA, receptor-APELATIVA, mensagem-POÉTICA, referente-REFERENCIAL, canal-FÁTICA, código-METALINGUÍSTICA.","img":"ling_funcoes","id":"ling0"},{"t":"P","top":"Interpretação e funções da linguagem","f":"Função emotiva (expressiva)","v":"Foco no emissor: sentimentos e opiniões, 1ª pessoa, interjeições. Diários, poemas líricos, depoimentos.","id":"ling1"},{"t":"P","top":"Interpretação e funções da linguagem","f":"Função apelativa (conativa)","v":"Foco no receptor: convencer ou ordenar. Verbos no imperativo, vocativo, 2ª pessoa. Propagandas, discursos.","id":"ling2"},{"t":"P","top":"Interpretação e funções da linguagem","f":"Função metalinguística","v":"A linguagem fala de si mesma: poema sobre fazer poema, dicionário, filme sobre cinema.","m":"METAlinguagem = a linguagem olhando no espelho.","id":"ling3"},{"t":"P","top":"Interpretação e funções da linguagem","f":"Função fática","v":"Foco no canal: testar ou manter contato. \"Alô?\", \"Tá me ouvindo?\", \"Né?\".","m":"FÁTICA = testa o FIO (canal): \"alô, tá me ouvindo?\".","id":"ling4"},{"t":"P","top":"Interpretação e funções da linguagem","f":"Função poética","v":"Foco na mensagem e na sua forma: sonoridade, ritmo, jogos de palavras. Poemas, slogans criativos.","id":"ling5"},{"t":"P","top":"Interpretação e funções da linguagem","f":"Variação linguística: tipos","v":"Regional (diatópica), social (diastrática), histórica (diacrônica) e situacional (diafásica: formal x informal). O ENEM combate o preconceito linguístico.","id":"ling6"},{"t":"P","top":"Interpretação e funções da linguagem","f":"O que é preconceito linguístico?","v":"Considerar \"erradas\" ou inferiores as variedades não padrão. O ENEM defende adequação ao contexto, não \"certo\" x \"errado\".","id":"ling7"},{"t":"P","top":"Interpretação e funções da linguagem","f":"Gêneros textuais x tipos textuais","v":"Tipos: narração, descrição, dissertação, injunção, exposição (estrutura). Gêneros: formas concretas de uso social (crônica, receita, notícia, charge, artigo de opinião).","id":"ling8"},{"t":"P","top":"Interpretação e funções da linguagem","f":"Dica para questões de gênero textual","v":"Identifique o propósito comunicativo e o suporte (onde circula). O ENEM pergunta \"qual a finalidade\" do texto.","id":"ling9"},{"t":"P","top":"Interpretação e funções da linguagem","f":"Intertextualidade: paródia x paráfrase","v":"Paródia: retoma o texto com subversão, humor ou crítica. Paráfrase: reescreve mantendo o sentido original.","m":"PARÓDIA = zoa (subverte). PARÁFRASE = mesma frase com outras palavras.","id":"ling10"},{"t":"P","top":"Interpretação e funções da linguagem","f":"Charge x cartum","v":"Charge critica fato específico e datado, muitas vezes com personalidades. Cartum é atemporal e universal.","id":"ling11"},{"t":"P","top":"Figuras de linguagem","f":"Metáfora x comparação","v":"Comparação usa conectivo (\"Ela é forte como uma rocha\"). Metáfora é comparação implícita (\"Ela é uma rocha\").","m":"Comparação tem \"como\"; metáfora \"esconde o como\".","id":"ling12"},{"t":"P","top":"Figuras de linguagem","f":"Metonímia","v":"Troca de um termo por outro com relação de proximidade: autor pela obra (\"li Machado\"), parte pelo todo, marca pelo produto (\"Bombril\").","id":"ling13"},{"t":"P","top":"Figuras de linguagem","f":"Ironia","v":"Dizer o contrário do que se pensa, com intenção crítica ou humorística.","id":"ling14"},{"t":"P","top":"Figuras de linguagem","f":"Antítese x paradoxo","v":"Antítese: ideias opostas lado a lado (\"riso e choro\"). Paradoxo: ideias opostas que parecem impossíveis juntas (\"amor é fogo que arde sem se ver\").","m":"ANTÍtese = opostos lado a lado. PARAdoxo = opostos na mesma coisa, \"parece impossível\".","id":"ling15"},{"t":"P","top":"Figuras de linguagem","f":"Eufemismo x hipérbole","v":"Eufemismo: suaviza (\"ele partiu\" = morreu). Hipérbole: exagera (\"já te falei um milhão de vezes\").","id":"ling16"},{"t":"P","top":"Figuras de linguagem","f":"Prosopopeia (personificação)","v":"Atribuir características humanas a seres inanimados ou animais. \"O vento sussurrava.\"","id":"ling17"},{"t":"P","top":"Figuras de linguagem","f":"Aliteração x assonância","v":"Aliteração: repetição de consoantes (\"o rato roeu a roupa do rei de Roma\"). Assonância: repetição de vogais.","id":"ling18"},{"t":"P","top":"Literatura brasileira","f":"Quinhentismo (Literatura informativa e jesuítica)","v":"Carta de Pero Vaz de Caminha (visão do paraíso, interesse econômico) e José de Anchieta (catequese).","id":"ling19"},{"t":"P","top":"Literatura brasileira","f":"Barroco: características e autores","v":"Conflito fé x prazer, cultismo (jogo de palavras) e conceptismo (jogo de ideias), antíteses. Gregório de Matos (\"Boca do Inferno\", sátira) e Padre Antônio Vieira (sermões).","m":"Barroco = conflito (\"céu x pecado\").","img":"ling_escolas","id":"ling20"},{"t":"P","top":"Literatura brasileira","f":"Arcadismo: características e autores","v":"Bucolismo, \"fugere urbem\", \"carpe diem\", pastoralismo, simplicidade. Tomás Antônio Gonzaga (Marília de Dirceu), Cláudio Manuel da Costa. Ligado à Inconfidência Mineira.","m":"Arcadismo = \"fugir para o campo\" (fugere urbem) e \"aproveitar o dia\" (carpe diem).","id":"ling21"},{"t":"P","top":"Literatura brasileira","f":"Romantismo: as três gerações na poesia","v":"1ª: nacionalista/indianista (Gonçalves Dias, \"Canção do exílio\"). 2ª: ultrarromântica, mal do século (Álvares de Azevedo). 3ª: condoreira, social, abolicionista (Castro Alves, \"O navio negreiro\").","m":"\"Índio, Morte, Escravo\": 1ª indianista, 2ª ultrarromântica (mal do século), 3ª condoreira (abolicionista).","id":"ling22"},{"t":"P","top":"Literatura brasileira","f":"José de Alencar: principais obras","v":"Indianistas (O Guarani, Iracema, Ubirajara), urbanas (Senhora, Lucíola), regionalistas (O gaúcho, O sertanejo). Idealização do índio como herói nacional.","id":"ling23"},{"t":"P","top":"Literatura brasileira","f":"Realismo e Machado de Assis","v":"Crítica social, análise psicológica, ironia, narrador que conversa com o leitor. Memórias póstumas de Brás Cubas (1881, marco), Dom Casmurro (dúvida sobre Capitu), Quincas Borba.","m":"1881 = ano de Brás Cubas = começo do Realismo.","img":"ling_escolas","id":"ling24"},{"t":"P","top":"Literatura brasileira","f":"Naturalismo","v":"Determinismo (meio, raça, momento), personagens animalizados, temas patológicos, cortiços. Aluísio Azevedo: O cortiço.","id":"ling25"},{"t":"P","top":"Literatura brasileira","f":"Parnasianismo x Simbolismo","v":"Parnasianismo: \"arte pela arte\", forma perfeita, soneto (Olavo Bilac). Simbolismo: musicalidade, misticismo, sinestesia, subjetividade (Cruz e Sousa, Alphonsus de Guimaraens).","id":"ling26"},{"t":"P","top":"Literatura brasileira","f":"Pré-Modernismo: autores e temas","v":"Retrato do Brasil real e problemas sociais. Euclides da Cunha (Os sertões, Canudos), Lima Barreto (Triste fim de Policarpo Quaresma), Monteiro Lobato (Jeca Tatu), Augusto dos Anjos.","id":"ling27"},{"t":"P","top":"Literatura brasileira","f":"Semana de Arte Moderna de 1922","v":"Em São Paulo, ruptura com a arte acadêmica. Oswald de Andrade, Mário de Andrade, Anita Malfatti, Di Cavalcanti, Villa-Lobos. Valorização da cultura brasileira e linguagem coloquial.","m":"1922 = centenário da Independência: \"independência cultural\".","img":"ling_escolas","id":"ling28"},{"t":"P","top":"Literatura brasileira","f":"Antropofagia (Oswald de Andrade)","v":"Manifesto Antropófago (1928): \"devorar\" a cultura estrangeira e transformá-la em algo brasileiro. \"Tupi or not tupi\". Abaporu, de Tarsila do Amaral.","id":"ling29"},{"t":"P","top":"Literatura brasileira","f":"Macunaíma","v":"Rapsódia de Mário de Andrade (1928), \"o herói sem nenhum caráter\". Mistura lendas, línguas e regiões em busca de uma identidade nacional.","id":"ling30"},{"t":"P","top":"Literatura brasileira","f":"Geração de 1930 (romance regionalista)","v":"Denúncia social do Nordeste: seca, miséria, coronelismo. Graciliano Ramos (Vidas secas, São Bernardo), Rachel de Queiroz (O quinze), Jorge Amado, José Lins do Rego.","m":"Romance de 30 = SECA e NORDESTE (Vidas secas, O quinze).","id":"ling31"},{"t":"P","top":"Literatura brasileira","f":"Carlos Drummond de Andrade","v":"Poesia reflexiva, ironia, \"gauche\", engajamento social (A rosa do povo, contra a guerra), cotidiano (\"No meio do caminho tinha uma pedra\").","id":"ling32"},{"t":"P","top":"Literatura brasileira","f":"Geração de 1945: Clarice Lispector e Guimarães Rosa","v":"Clarice: fluxo de consciência, epifania, introspecção (A hora da estrela). Guimarães Rosa: sertão universal, neologismos (Grande sertão: veredas).","id":"ling33"},{"t":"P","top":"Literatura brasileira","f":"João Cabral de Melo Neto","v":"Poesia racional, \"antilírica\", concreta. Morte e vida severina: retirante nordestino.","id":"ling34"},{"t":"P","top":"Literatura brasileira","f":"Literatura contemporânea frequente no ENEM","v":"Conceição Evaristo (escrevivência, mulher negra), Carolina Maria de Jesus (Quarto de despejo), literatura indígena, poesia marginal, slam e rap.","id":"ling35"},{"t":"P","top":"Artes e corpo","f":"Movimentos de vanguarda europeia","v":"Cubismo (Picasso, formas geométricas, múltiplos ângulos), Expressionismo (emoção, distorção, Munch), Surrealismo (sonho, inconsciente, Dalí), Futurismo (velocidade, máquinas), Dadaísmo (anti-arte, Duchamp).","m":"\"Cubismo = cubos e ângulos; Surrealismo = sonho; Expressionismo = grito; Dadaísmo = deboche; Futurismo = velocidade\".","id":"ling36"},{"t":"P","top":"Artes e corpo","f":"Arte contemporânea: o que o ENEM cobra?","v":"Instalações, performance, arte conceitual, intervenção urbana, grafite: o conceito e a interação com o público importam mais que a técnica.","id":"ling37"},{"t":"P","top":"Artes e corpo","f":"Educação física no ENEM: temas comuns","v":"Práticas corporais como cultura, saúde x estética, padrões de beleza, esporte e inclusão, danças populares, capoeira, benefícios da atividade física.","id":"ling38"},{"t":"P","top":"Espanhol","f":"Falsos cognatos: \"embarazada\", \"exquisito\", \"oficina\"","v":"Embarazada = grávida. Exquisito = delicioso. Oficina = escritório.","id":"ling39"},{"t":"P","top":"Espanhol","f":"Falsos cognatos: \"rato\", \"polvo\", \"borracha\"","v":"Rato = momento, instante. Polvo = pó, poeira. Borracha = bêbada (borrador = borracha).","id":"ling40"},{"t":"P","top":"Espanhol","f":"Falsos cognatos: \"apellido\", \"salada\", \"vaso\"","v":"Apellido = sobrenome. Salada = salgada (ensalada = salada). Vaso = copo.","id":"ling41"},{"t":"P","top":"Espanhol","f":"Falsos cognatos: \"pelado\", \"cola\", \"zurdo\"","v":"Pelado = careca. Cola = rabo, fila. Zurdo = canhoto.","id":"ling42"},{"t":"P","top":"Espanhol","f":"Falsos cognatos: \"taller\", \"cena\", \"presunto\"","v":"Taller = oficina (mecânica, ateliê). Cena = jantar. Presunto = suposto (jamón = presunto).","id":"ling43"},{"t":"P","top":"Espanhol","f":"Falsos cognatos: \"largo\", \"acordarse\", \"brincar\"","v":"Largo = comprido. Acordarse = lembrar-se. Brincar = pular.","id":"ling44"},{"t":"P","top":"Espanhol","f":"Falsos cognatos: \"exprimir\", \"ganancia\", \"contestar\"","v":"Exprimir = espremer. Ganancia = lucro. Contestar = responder.","id":"ling45"},{"t":"P","top":"Espanhol","f":"\"Sin embargo\" e \"aunque\"","v":"Sin embargo = no entanto (adversativo). Aunque = embora, ainda que (concessivo).","id":"ling46"},{"t":"P","top":"Espanhol","f":"\"Mientras\", \"luego\", \"todavía\"","v":"Mientras = enquanto. Luego = depois, logo. Todavía = ainda.","id":"ling47"},{"t":"P","top":"Espanhol","f":"\"Muy\" x \"mucho\"","v":"Muy antes de adjetivo e advérbio (muy bonito). Mucho antes de substantivo ou depois de verbo (mucho dinero, trabaja mucho).","id":"ling48"},{"t":"P","top":"Espanhol","f":"Estratégia para a prova de espanhol","v":"Leia a pergunta primeiro, procure palavras transparentes e o contexto. A prova cobra interpretação, não gramática decorada. Atenção aos falsos cognatos.","id":"ling49"},{"t":"F","top":"Interpretação e funções da linguagem","f":"Um anúncio com \"Compre já! Você merece!\" tem foco em qual elemento e qual função?","v":"Foco no <b>receptor</b> → função <b>apelativa (conativa)</b>: imperativo e 2ª pessoa para convencer.","img":"ling_funcoes","id":"ling50"},{"t":"R","top":"Interpretação e funções da linguagem","f":"Função emotiva","v":"Foco no emissor: sentimentos, 1ª pessoa, interjeições.","id":"ling51"},{"t":"R","top":"Interpretação e funções da linguagem","f":"Função apelativa","v":"Foco no receptor: imperativo, vocativo, convencer.","id":"ling52"},{"t":"R","top":"Interpretação e funções da linguagem","f":"Função referencial","v":"Foco no assunto: informação objetiva (notícia).","m":"Cada função = um elemento da comunicação: emissor-EMOTIVA, receptor-APELATIVA, mensagem-POÉTICA, referente-REFERENCIAL, canal-FÁTICA, código-METALINGUÍSTICA.","img":"ling_funcoes","id":"ling53"},{"t":"R","top":"Interpretação e funções da linguagem","f":"Função poética","v":"Foco na forma da mensagem: ritmo, sonoridade, jogo de palavras.","id":"ling54"},{"t":"R","top":"Interpretação e funções da linguagem","f":"Função fática","v":"Foco no canal: testar ou manter o contato.","m":"FÁTICA = testa o FIO (canal): \"alô, tá me ouvindo?\".","id":"ling55"},{"t":"R","top":"Interpretação e funções da linguagem","f":"Função metalinguística","v":"Foco no código: a linguagem fala da própria linguagem.","m":"METAlinguagem = a linguagem olhando no espelho.","id":"ling56"},{"t":"V","top":"Interpretação e funções da linguagem","f":"O ENEM considera \"errado\" o uso de variedades regionais da língua.","ok":false,"x":"O ENEM valoriza a variação linguística e combate o preconceito linguístico: o critério é a adequação ao contexto.","id":"ling57"},{"t":"R","top":"Figuras de linguagem","f":"Metonímia","v":"Troca por proximidade: autor pela obra, marca pelo produto, parte pelo todo.","id":"ling58"},{"t":"R","top":"Figuras de linguagem","f":"Prosopopeia","v":"Dar características humanas a seres inanimados (\"o vento sussurrava\").","id":"ling59"},{"t":"R","top":"Figuras de linguagem","f":"Hipérbole","v":"Exagero (\"chorei rios de lágrimas\").","id":"ling60"},{"t":"R","top":"Figuras de linguagem","f":"Eufemismo","v":"Suavização (\"ele nos deixou\" = morreu).","id":"ling61"},{"t":"R","top":"Figuras de linguagem","f":"Ironia","v":"Dizer o contrário do que se pensa, com crítica ou humor.","id":"ling62"},{"t":"R","top":"Figuras de linguagem","f":"Aliteração","v":"Repetição de sons consonantais.","id":"ling63"},{"t":"C","top":"Figuras de linguagem","f":"\"Ela é uma flor\" é ⟦1⟧; \"ela é bela como uma flor\" é ⟦2⟧.","l":{"1":"metáfora","2":"comparação"},"id":"ling64"},{"t":"C","top":"Figuras de linguagem","f":"\"Li Machado de Assis inteiro\" é exemplo de ⟦1⟧ (autor pela obra).","l":{"1":"metonímia"},"id":"ling65"},{"t":"D","top":"Figuras de linguagem","f":"Qual figura há em \"já te falei um milhão de vezes\"?","v":"hipérbole","x":"Exagero intencional.","id":"ling66"},{"t":"F","top":"Literatura brasileira","f":"Ordene: Romantismo, Barroco, Modernismo, Arcadismo, Realismo.","v":"<b>Barroco (1601) → Arcadismo (1768) → Romantismo (1836) → Realismo (1881) → Modernismo (1922).</b>","img":"ling_escolas","id":"ling67"},{"t":"R","top":"Literatura brasileira","f":"Memórias póstumas de Brás Cubas","v":"Machado de Assis (Realismo)","id":"ling68"},{"t":"R","top":"Literatura brasileira","f":"O cortiço","v":"Aluísio Azevedo (Naturalismo)","id":"ling69"},{"t":"R","top":"Literatura brasileira","f":"Iracema / O Guarani","v":"José de Alencar (Romantismo indianista)","id":"ling70"},{"t":"R","top":"Literatura brasileira","f":"O navio negreiro","v":"Castro Alves (Romantismo, 3ª geração, condoreira)","id":"ling71"},{"t":"R","top":"Literatura brasileira","f":"Os sertões","v":"Euclides da Cunha (Pré-Modernismo, Canudos)","id":"ling72"},{"t":"R","top":"Literatura brasileira","f":"Macunaíma","v":"Mário de Andrade (Modernismo, 1ª fase)","id":"ling73"},{"t":"R","top":"Literatura brasileira","f":"Vidas secas","v":"Graciliano Ramos (Geração de 30)","id":"ling74"},{"t":"R","top":"Literatura brasileira","f":"O quinze","v":"Rachel de Queiroz (Geração de 30)","id":"ling75"},{"t":"R","top":"Literatura brasileira","f":"A hora da estrela","v":"Clarice Lispector (Geração de 45)","id":"ling76"},{"t":"R","top":"Literatura brasileira","f":"Grande sertão: veredas","v":"Guimarães Rosa (Geração de 45)","id":"ling77"},{"t":"R","top":"Literatura brasileira","f":"Morte e vida severina","v":"João Cabral de Melo Neto","id":"ling78"},{"t":"R","top":"Literatura brasileira","f":"Quarto de despejo","v":"Carolina Maria de Jesus","id":"ling79"},{"t":"R","top":"Literatura brasileira","f":"Triste fim de Policarpo Quaresma","v":"Lima Barreto (Pré-Modernismo)","id":"ling80"},{"t":"R","top":"Literatura brasileira","f":"Marília de Dirceu","v":"Tomás Antônio Gonzaga (Arcadismo)","id":"ling81"},{"t":"C","top":"Literatura brasileira","f":"O marco inicial do Realismo no Brasil é ⟦1⟧ (⟦2⟧), de Machado de Assis.","l":{"1":"Memórias póstumas de Brás Cubas","2":"1881"},"id":"ling82"},{"t":"C","top":"Literatura brasileira","f":"A Semana de Arte Moderna ocorreu em ⟦1⟧, em ⟦2⟧.","l":{"1":"1922","2":"São Paulo"},"id":"ling83"},{"t":"C","top":"Literatura brasileira","f":"O Manifesto Antropófago é de ⟦1⟧; o quadro Abaporu é de ⟦2⟧.","l":{"1":"Oswald de Andrade","2":"Tarsila do Amaral"},"id":"ling84"},{"t":"V","top":"Literatura brasileira","f":"Álvares de Azevedo é o principal nome da poesia abolicionista.","ok":false,"x":"Álvares de Azevedo é da 2ª geração (ultrarromântica, mal do século). O poeta abolicionista é Castro Alves (3ª geração).","id":"ling85"},{"t":"R","top":"Artes e corpo","f":"Cubismo","v":"Formas geométricas e vários ângulos ao mesmo tempo (Picasso).","id":"ling86"},{"t":"R","top":"Artes e corpo","f":"Surrealismo","v":"Sonho e inconsciente (Dalí).","id":"ling87"},{"t":"R","top":"Artes e corpo","f":"Expressionismo","v":"Emoção e distorção (Munch, \"O grito\").","id":"ling88"},{"t":"R","top":"Artes e corpo","f":"Dadaísmo","v":"Anti-arte, acaso, deboche (Duchamp, \"A fonte\").","id":"ling89"},{"t":"R","top":"Espanhol","f":"embarazada","v":"grávida","id":"ling90"},{"t":"R","top":"Espanhol","f":"exquisito","v":"delicioso","id":"ling91"},{"t":"R","top":"Espanhol","f":"oficina","v":"escritório","id":"ling92"},{"t":"R","top":"Espanhol","f":"rato","v":"momento, instante","id":"ling93"},{"t":"R","top":"Espanhol","f":"polvo","v":"pó, poeira","id":"ling94"},{"t":"R","top":"Espanhol","f":"borracha","v":"bêbada","id":"ling95"},{"t":"R","top":"Espanhol","f":"apellido","v":"sobrenome","id":"ling96"},{"t":"R","top":"Espanhol","f":"vaso","v":"copo","id":"ling97"},{"t":"R","top":"Espanhol","f":"pelado","v":"careca","id":"ling98"},{"t":"R","top":"Espanhol","f":"zurdo","v":"canhoto","id":"ling99"},{"t":"R","top":"Espanhol","f":"cena","v":"jantar","id":"ling100"},{"t":"R","top":"Espanhol","f":"presunto","v":"suposto","id":"ling101"},{"t":"R","top":"Espanhol","f":"largo","v":"comprido","id":"ling102"},{"t":"R","top":"Espanhol","f":"acordarse","v":"lembrar-se","id":"ling103"},{"t":"R","top":"Espanhol","f":"brincar","v":"pular","id":"ling104"},{"t":"R","top":"Espanhol","f":"sin embargo","v":"no entanto","id":"ling105"},{"t":"R","top":"Espanhol","f":"aunque","v":"embora","id":"ling106"},{"t":"R","top":"Espanhol","f":"todavía","v":"ainda","id":"ling107"},{"t":"R","top":"Espanhol","f":"luego","v":"depois, logo","id":"ling108"},{"t":"R","top":"Espanhol","f":"desarrollo","v":"desenvolvimento","id":"ling109"},{"t":"R","top":"Espanhol","f":"ahora","v":"agora","id":"ling110"},{"t":"R","top":"Espanhol","f":"hoy","v":"hoje","id":"ling111"},{"t":"R","top":"Espanhol","f":"ayer","v":"ontem","id":"ling112"},{"t":"R","top":"Espanhol","f":"mañana","v":"amanhã (ou manhã)","id":"ling113"},{"t":"R","top":"Espanhol","f":"quizás","v":"talvez","id":"ling114"},{"t":"D","top":"Espanhol","f":"Tradução de \"cena\" em espanhol?","v":"jantar","x":"Falso cognato; \"cena\" do teatro é \"escena\".","id":"ling115"},{"t":"D","top":"Espanhol","f":"Tradução de \"embarazada\"?","v":"grávida","x":"Falso cognato clássico.","id":"ling116"},{"t":"V","top":"Espanhol","f":"Em espanhol, \"exquisito\" significa estranho.","ok":false,"x":"Significa delicioso, requintado. \"Estranho\" é \"raro\" ou \"extraño\".","id":"ling117"}]},{"id":"hum","nome":"Humanas","ic":"🌎","cards":[{"t":"P","top":"História do Brasil","f":"Ciclo do açúcar no Brasil Colônia","v":"Séculos XVI e XVII, Nordeste (Pernambuco e Bahia). Plantation: latifúndio, monocultura, mão de obra escravizada africana, produção para exportação.","m":"Plantation = \"LMEE\": Latifúndio, Monocultura, Escravidão, Exportação.","img":"hist_brasil","id":"hum0"},{"t":"P","top":"História do Brasil","f":"Ciclo do ouro e suas consequências","v":"Século XVIII, Minas Gerais. Urbanização, deslocamento do eixo para o Sudeste, capital vai para o Rio (1763), impostos como o quinto e a derrama.","id":"hum1"},{"t":"P","top":"História do Brasil","f":"Inconfidência Mineira x Conjuração Baiana","v":"Mineira (1789): elite contra a derrama, Tiradentes executado. Baiana (1798): popular, com escravizados e alfaiates, defendia o fim da escravidão.","id":"hum2"},{"t":"P","top":"História do Brasil","f":"Vinda da família real (1808)","v":"Fugindo de Napoleão. Abertura dos portos às nações amigas, criação do Banco do Brasil, imprensa régia; em 1815 o Brasil vira Reino Unido a Portugal.","id":"hum3"},{"t":"P","top":"História do Brasil","f":"Independência do Brasil (1822)","v":"Conduzida pela elite, manteve monarquia, escravidão e latifúndio. Dom Pedro I. Constituição de 1824 com Poder Moderador e voto censitário.","id":"hum4"},{"t":"P","top":"História do Brasil","f":"Revoltas do Período Regencial","v":"Cabanagem (Pará), Balaiada (Maranhão), Sabinada (Bahia), Malês (escravizados muçulmanos, Bahia) e Farroupilha (RS, 1835-1845, estancieiros contra impostos sobre o charque).","id":"hum5"},{"t":"P","top":"História do Brasil","f":"Leis abolicionistas em ordem","v":"Eusébio de Queirós (1850, fim do tráfico), Ventre Livre (1871), Sexagenários (1885), Lei Áurea (1888). Lei de Terras (1850) dificultou o acesso à terra para ex-escravizados e imigrantes.","m":"\"Eu Vou Sair Logo\": Eusébio (1850), Ventre Livre (1871), Sexagenários (1885), Lei Áurea (1888).","img":"hist_abolicao","id":"hum6"},{"t":"P","top":"História do Brasil","f":"República Velha: política do café com leite e coronelismo","v":"Revezamento SP e MG, política dos governadores, voto de cabresto (aberto), coronéis controlando eleitores.","id":"hum7"},{"t":"P","top":"História do Brasil","f":"Revoltas da Primeira República","v":"Canudos (messiânica, Bahia), Contestado (SC/PR), Revolta da Vacina (1904, RJ), Revolta da Chibata (1910, marinheiros), Tenentismo (anos 1920).","id":"hum8"},{"t":"P","top":"História do Brasil","f":"Era Vargas: principais marcas","v":"Revolução de 1930, Estado Novo (1937-1945, ditadura), CLT (1943), salário mínimo, voto feminino (1932), CSN e Petrobras (1953), populismo e propaganda (DIP).","m":"Vargas = \"pai dos pobres e mãe dos ricos\": deu direitos trabalhistas (CLT) e governou com autoritarismo.","img":"hist_brasil","id":"hum9"},{"t":"P","top":"História do Brasil","f":"Ditadura militar (1964-1985): marcas","v":"Golpe de 1964, Atos Institucionais (AI-5 em 1968, o mais duro: censura, fechamento do Congresso), \"milagre econômico\", Lei da Anistia (1979), Diretas Já (1984).","m":"AI-5 em 68: \"o ano que não terminou\".","img":"hist_brasil","id":"hum10"},{"t":"P","top":"História do Brasil","f":"Constituição de 1988","v":"\"Constituição Cidadã\": redemocratização, voto para analfabetos e maiores de 16 anos, SUS, racismo como crime inafiançável, direitos indígenas e quilombolas.","m":"\"Constituição Cidadã\" = SUS, voto aos 16 e racismo inafiançável.","id":"hum11"},{"t":"P","top":"História geral","f":"Democracia ateniense: limites","v":"Democracia direta, mas só para cidadãos: excluía mulheres, estrangeiros (metecos) e escravizados.","id":"hum12"},{"t":"P","top":"História geral","f":"Feudalismo: características","v":"Economia agrária, autossuficiente, sociedade estamental (clero, nobreza, servos), relações de suserania e vassalagem, poder da Igreja.","id":"hum13"},{"t":"P","top":"História geral","f":"Renascimento","v":"Séculos XIV a XVI, Itália. Humanismo, antropocentrismo, racionalismo, retomada da cultura greco-romana. Leonardo da Vinci, Michelangelo.","id":"hum14"},{"t":"P","top":"História geral","f":"Reforma Protestante","v":"Lutero (1517, 95 teses contra a venda de indulgências). Calvinismo valorizou o trabalho e o lucro (Weber relaciona à ética capitalista). Contrarreforma: Concílio de Trento, Inquisição, jesuítas.","id":"hum15"},{"t":"P","top":"História geral","f":"Iluminismo: ideias e pensadores","v":"Razão contra o absolutismo. Locke (direitos naturais), Montesquieu (três poderes), Rousseau (contrato social, vontade geral), Voltaire (tolerância). Inspirou as revoluções liberais.","m":"Montesquieu = 3 poderes (\"Monte de 3\"). Rousseau = contrato social. Locke = direitos naturais.","id":"hum16"},{"t":"P","top":"História geral","f":"Revolução Francesa (1789)","v":"Liberdade, igualdade, fraternidade. Fim dos privilégios do Antigo Regime, Declaração dos Direitos do Homem e do Cidadão. Fases: Assembleia, Convenção (Terror jacobino), Diretório, Napoleão.","m":"Lema: \"Liberdade, Igualdade, Fraternidade\". 1789 = queda da Bastilha.","id":"hum17"},{"t":"P","top":"História geral","f":"Revolução Industrial","v":"Inglaterra, século XVIII. Máquina a vapor, fábricas, êxodo rural, proletariado, jornadas longas, trabalho infantil. Reações: ludismo (quebra de máquinas), cartismo, sindicatos.","id":"hum18"},{"t":"P","top":"História geral","f":"Imperialismo e neocolonialismo (século XIX)","v":"Potências europeias dividem África e Ásia (Conferência de Berlim, 1884-1885) em busca de matérias-primas e mercados. Justificativa: darwinismo social, \"fardo do homem branco\".","id":"hum19"},{"t":"P","top":"História geral","f":"Primeira Guerra Mundial (1914-1918)","v":"Causas: imperialismo, nacionalismo, alianças, corrida armamentista. Estopim: assassinato de Francisco Ferdinando. Tratado de Versalhes humilhou a Alemanha.","id":"hum20"},{"t":"P","top":"História geral","f":"Crise de 1929","v":"Quebra da bolsa de Nova York, superprodução. Resposta: New Deal (intervenção estatal, Keynes). No Brasil, derrubou o café e contribuiu para a Revolução de 1930.","id":"hum21"},{"t":"P","top":"História geral","f":"Totalitarismos: nazismo e fascismo","v":"Partido único, culto ao líder, nacionalismo extremo, propaganda, anticomunismo, perseguição a minorias (Holocausto). Mussolini (Itália) e Hitler (Alemanha).","id":"hum22"},{"t":"P","top":"História geral","f":"Guerra Fria","v":"EUA (capitalismo) x URSS (socialismo), sem confronto direto: corrida armamentista e espacial, Plano Marshall, Muro de Berlim (1961-1989), guerras da Coreia e do Vietnã, crise dos mísseis em Cuba.","m":"\"Fria\" porque EUA e URSS nunca se enfrentaram diretamente.","id":"hum23"},{"t":"P","top":"Geografia","f":"Clima do Brasil: quais tipos?","v":"Equatorial (Amazônia, quente e úmido), tropical (Brasil central, verão chuvoso e inverno seco), semiárido (sertão nordestino), tropical de altitude, subtropical (Sul, 4 estações, geadas).","id":"hum24"},{"t":"P","top":"Geografia","f":"Massas de ar que atuam no Brasil","v":"Equatorial continental (mEc, quente e úmida, chuvas de verão), Polar atlântica (mPa, frentes frias e friagem), Tropical atlântica (mTa).","id":"hum25"},{"t":"P","top":"Geografia","f":"Ilha de calor","v":"Centros urbanos mais quentes que o entorno: asfalto, concreto, pouca vegetação e poluição retêm calor.","m":"ILHA de calor = cidade \"ilhada\" pelo concreto quente.","id":"hum26"},{"t":"P","top":"Geografia","f":"Inversão térmica","v":"Camada de ar frio fica presa embaixo de ar quente (comum em manhãs de inverno), impedindo a dispersão de poluentes nas cidades.","m":"Inversão = ar frio EMBAIXO (o normal é o contrário), poluição presa. Comum no inverno.","id":"hum27"},{"t":"P","top":"Geografia","f":"\"Rios voadores\"","v":"Vapor d'água da evapotranspiração da Amazônia levado por correntes de ar, que traz chuva ao Centro-Sul. Desmatamento ameaça esse fluxo.","id":"hum28"},{"t":"P","top":"Geografia","f":"Agentes do relevo: internos x externos","v":"Internos (endógenos): tectonismo, vulcanismo, terremotos (formam). Externos (exógenos): chuva, vento, rios, seres vivos (modelam, causam erosão).","id":"hum29"},{"t":"P","top":"Geografia","f":"Erosão, voçorocas e assoreamento","v":"Retirada da vegetação expõe o solo; a chuva carrega sedimentos, formando sulcos e voçorocas. Os sedimentos se acumulam nos rios (assoreamento).","id":"hum30"},{"t":"P","top":"Geografia","f":"Arenização no Pampa gaúcho x desertificação","v":"Arenização: formação de areais em solo arenoso, por processo natural agravado pelo pisoteio do gado e monocultura (sudoeste do RS). Desertificação: degradação em áreas áridas e semiáridas (Nordeste).","id":"hum31"},{"t":"P","top":"Geografia","f":"Matriz energética brasileira","v":"Muito renovável em comparação com o mundo: hidrelétricas dominam a eletricidade; cana (etanol), eólica (Nordeste) e solar crescendo.","id":"hum32"},{"t":"P","top":"Geografia","f":"Urbanização brasileira: problemas","v":"Rápida e desordenada (pós-1950, êxodo rural): favelização, segregação socioespacial, especulação imobiliária, mobilidade precária, enchentes.","id":"hum33"},{"t":"P","top":"Geografia","f":"Metrópole, conurbação e megalópole","v":"Conurbação: cidades que crescem e se juntam. Megalópole: união de metrópoles (eixo Rio-São Paulo).","id":"hum34"},{"t":"P","top":"Geografia","f":"Transição demográfica e pirâmide etária brasileira","v":"Queda da natalidade e da mortalidade → envelhecimento da população. Pirâmide com base mais estreita e topo mais largo; impacto na previdência.","id":"hum35"},{"t":"P","top":"Geografia","f":"Globalização: características","v":"Integração econômica e cultural, empresas transnacionais, fluxo de informação e capital (técnico-científico-informacional, Milton Santos), aumento das desigualdades.","id":"hum36"},{"t":"P","top":"Geografia","f":"Blocos econômicos: Mercosul","v":"Criado em 1991 (Tratado de Assunção): Brasil, Argentina, Uruguai, Paraguai (Bolívia em adesão). União aduaneira imperfeita.","id":"hum37"},{"t":"P","top":"Geografia","f":"Agronegócio x agricultura familiar","v":"Agronegócio: grandes propriedades, mecanização, monocultura para exportação (soja, carne). Agricultura familiar: pequenas propriedades, produz grande parte do alimento consumido no país.","id":"hum38"},{"t":"P","top":"Geografia","f":"Revolução Verde","v":"Modernização agrícola a partir dos anos 1960: sementes melhoradas, fertilizantes, agrotóxicos e máquinas. Aumentou a produção, mas concentrou terras e causou impactos ambientais.","id":"hum39"},{"t":"P","top":"Geografia","f":"Cartografia: escala grande x pequena","v":"Escala grande (1:1.000): área pequena, muito detalhe (planta de cidade). Escala pequena (1:10.000.000): área grande, pouco detalhe (mapa-múndi).","m":"Escala GRANDE = detalhe GRANDE, área pequena (denominador pequeno).","id":"hum40"},{"t":"P","top":"Geografia","f":"Projeções cartográficas: Mercator x Peters","v":"Mercator: conforme (preserva formas), distorce áreas perto dos polos (Europa grande), eurocêntrica. Peters: equivalente (preserva áreas), distorce formas.","m":"MERcator = conforMe (forma) e Europa grande. PETERS = Preserva árEa (equivalente).","id":"hum41"},{"t":"P","top":"Geografia","f":"Fusos horários","v":"15° de longitude = 1 hora. A leste a hora é adiantada; a oeste, atrasada.","m":"Leste = \"Lá o Sol nasce antes\": hora adiantada.","id":"hum42"},{"t":"P","top":"Filosofia","f":"Sócrates","v":"\"Só sei que nada sei\". Maiêutica (parto das ideias por perguntas) e ironia. Busca da verdade pelo diálogo; não deixou escritos.","id":"hum43"},{"t":"P","top":"Filosofia","f":"Platão","v":"Mundo das ideias (verdadeiro, eterno) x mundo sensível (cópias). Alegoria da caverna. A filosofia liberta da ignorância.","m":"A caverna: sombras = senso comum; sair da caverna = filosofia.","id":"hum44"},{"t":"P","top":"Filosofia","f":"Aristóteles","v":"Realismo, lógica, ética das virtudes (justo meio), \"o homem é um animal político\". Felicidade (eudaimonia) como fim.","id":"hum45"},{"t":"P","top":"Filosofia","f":"Maquiavel","v":"O príncipe: separa política da moral; o governante precisa de virtù e fortuna. \"Melhor ser temido que amado\" se não puder ser ambos.","id":"hum46"},{"t":"P","top":"Filosofia","f":"Contratualistas: Hobbes, Locke, Rousseau","v":"Hobbes: estado de natureza é guerra de todos contra todos, Estado absoluto (Leviatã). Locke: direitos naturais (vida, liberdade, propriedade), direito de resistência. Rousseau: o homem nasce bom, a sociedade o corrompe; vontade geral.","m":"Hobbes = Homem é lobo do homem (medo). Locke = Liberdade e propriedade. Rousseau = \"bom selvagem\".","img":"filo_contratualistas","id":"hum47"},{"t":"P","top":"Filosofia","f":"Racionalismo x empirismo","v":"Racionalismo (Descartes): conhecimento vem da razão, \"penso, logo existo\". Empirismo (Locke, Hume): vem da experiência, mente como \"tábula rasa\".","m":"RACIOnalismo = RAzão (Descartes). EMPIRismo = EXPERIência (Locke, Hume).","id":"hum48"},{"t":"P","top":"Filosofia","f":"Kant","v":"Imperativo categórico: aja de modo que sua ação possa virar lei universal; trate as pessoas como fim, nunca só como meio. Esclarecimento: \"ouse saber\".","id":"hum49"},{"t":"P","top":"Filosofia","f":"Nietzsche","v":"Crítica à moral cristã (\"moral de rebanho\"), \"Deus está morto\", vontade de potência, além-do-homem.","id":"hum50"},{"t":"P","top":"Filosofia","f":"Sartre (existencialismo)","v":"\"A existência precede a essência\": o ser humano é condenado a ser livre e responsável por suas escolhas.","id":"hum51"},{"t":"P","top":"Filosofia","f":"Escola de Frankfurt: indústria cultural","v":"Adorno e Horkheimer: a cultura vira mercadoria padronizada, que aliena e massifica o público.","id":"hum52"},{"t":"P","top":"Sociologia","f":"Karl Marx","v":"Luta de classes (burguesia x proletariado), mais-valia (exploração do trabalho não pago), alienação, materialismo histórico.","m":"Marx = Mais-valia (M com M): o trabalhador produz mais do que recebe.","id":"hum53"},{"t":"P","top":"Sociologia","f":"Max Weber","v":"Ação social, tipos de dominação (legal, tradicional, carismática), burocracia, \"A ética protestante e o espírito do capitalismo\".","m":"Weber = \"dominação\": legal, tradicional e carismática.","id":"hum54"},{"t":"P","top":"Sociologia","f":"Durkheim: solidariedade mecânica x orgânica","v":"Mecânica: sociedades simples, semelhança entre indivíduos. Orgânica: sociedades complexas, divisão do trabalho e interdependência.","id":"hum55"},{"t":"P","top":"Sociologia","f":"Taylorismo, fordismo e toyotismo","v":"Taylorismo: tempos e movimentos, especialização. Fordismo: linha de montagem, produção em massa. Toyotismo: produção flexível, just in time, trabalhador multifuncional.","m":"Ford = esteira (linha de montagem). Toyota = \"just in time\", estoque mínimo.","id":"hum56"},{"t":"P","top":"Sociologia","f":"Etnocentrismo x relativismo cultural","v":"Etnocentrismo: julgar outras culturas pela sua, como superior. Relativismo: compreender cada cultura em seus próprios termos.","id":"hum57"},{"t":"P","top":"Sociologia","f":"Cidadania segundo T. H. Marshall","v":"Direitos civis (séc. XVIII), políticos (XIX) e sociais (XX). No Brasil, segundo José Murilo de Carvalho, a ordem foi invertida (sociais com Vargas antes dos políticos plenos).","id":"hum58"},{"t":"P","top":"Sociologia","f":"Movimentos sociais e minorias no ENEM","v":"MST, movimentos negro, feminista, indígena, LGBTQIA+. \"Minoria\" é sobre falta de poder e representação, não sobre número.","id":"hum59"},{"t":"F","top":"História do Brasil","f":"Em que período estão a CLT, a Petrobras e o voto feminino?","v":"<b>Era Vargas (1930-1945, e o 2º governo, 1951-1954).</b> CLT em 1943, voto feminino em 1932, Petrobras em 1953 (2º governo).","img":"hist_brasil","id":"hum60"},{"t":"F","top":"História do Brasil","f":"Qual lei acabou com o tráfico negreiro e qual libertou os filhos de escravizadas?","v":"<b>Eusébio de Queirós (1850)</b> acabou com o tráfico. <b>Lei do Ventre Livre (1871)</b> declarou livres os filhos nascidos de mulheres escravizadas.","img":"hist_abolicao","id":"hum61"},{"t":"C","top":"História do Brasil","f":"A Lei Eusébio de Queirós (⟦1⟧) proibiu o tráfico; a Lei Áurea (⟦2⟧) aboliu a escravidão.","l":{"1":"1850","2":"1888"},"id":"hum62"},{"t":"C","top":"História do Brasil","f":"O AI-5 foi decretado em ⟦1⟧ e foi o ato mais duro da ditadura: fechou o ⟦2⟧ e ampliou a ⟦3⟧.","l":{"1":"1968","2":"Congresso","3":"censura"},"id":"hum63"},{"t":"C","top":"História do Brasil","f":"A Revolução Farroupilha (1835-1845) ocorreu no ⟦1⟧ e foi motivada pelos impostos sobre o ⟦2⟧.","l":{"1":"Rio Grande do Sul","2":"charque"},"id":"hum64"},{"t":"C","top":"História do Brasil","f":"Na República Velha, o revezamento entre SP e MG chamava-se política do ⟦1⟧; o controle de votos pelos coronéis, ⟦2⟧.","l":{"1":"café com leite","2":"voto de cabresto"},"id":"hum65"},{"t":"R","top":"História do Brasil","f":"Canudos","v":"Revolta messiânica na Bahia (Antônio Conselheiro), República Velha.","id":"hum66"},{"t":"R","top":"História do Brasil","f":"Revolta da Vacina","v":"Rio, 1904, contra a vacinação obrigatória e as reformas urbanas.","id":"hum67"},{"t":"R","top":"História do Brasil","f":"Revolta da Chibata","v":"1910, marinheiros contra castigos físicos (João Cândido).","id":"hum68"},{"t":"R","top":"História do Brasil","f":"Inconfidência Mineira","v":"1789, elite contra a derrama; Tiradentes executado.","id":"hum69"},{"t":"R","top":"História do Brasil","f":"Conjuração Baiana","v":"1798, popular, defendia o fim da escravidão.","id":"hum70"},{"t":"D","top":"História do Brasil","f":"Em que ano ocorreu a Independência do Brasil?","v":"1822","x":"Dom Pedro I.","id":"hum71"},{"t":"D","top":"História do Brasil","f":"Em que ano foi proclamada a República?","v":"1889","x":"Marechal Deodoro.","id":"hum72"},{"t":"D","top":"História do Brasil","f":"Em que ano foi promulgada a Constituição Cidadã?","v":"1988","x":"Redemocratização.","id":"hum73"},{"t":"V","top":"História do Brasil","f":"A Independência do Brasil acabou com a escravidão.","ok":false,"x":"A independência (1822) manteve escravidão, latifúndio e monarquia. A abolição só veio em 1888.","id":"hum74"},{"t":"C","top":"História geral","f":"A Reforma Protestante começou em ⟦1⟧ com as 95 teses de ⟦2⟧, contra a venda de ⟦3⟧.","l":{"1":"1517","2":"Lutero","3":"indulgências"},"id":"hum75"},{"t":"C","top":"História geral","f":"A Revolução Industrial começou na ⟦1⟧ no século ⟦2⟧; os trabalhadores que quebravam máquinas formaram o ⟦3⟧.","l":{"1":"Inglaterra","2":"XVIII","3":"ludismo"},"id":"hum76"},{"t":"C","top":"História geral","f":"Contra a crise de 1929, os EUA aplicaram o ⟦1⟧, inspirado nas ideias de ⟦2⟧.","l":{"1":"New Deal","2":"Keynes"},"id":"hum77"},{"t":"R","top":"História geral","f":"Ludismo","v":"Movimento de operários que quebravam máquinas na Revolução Industrial.","id":"hum78"},{"t":"R","top":"História geral","f":"Cartismo","v":"Movimento operário inglês por direitos políticos (voto).","id":"hum79"},{"t":"R","top":"História geral","f":"New Deal","v":"Plano de Roosevelt contra a crise de 1929, com intervenção estatal.","id":"hum80"},{"t":"R","top":"História geral","f":"Plano Marshall","v":"Ajuda dos EUA para reconstruir a Europa ocidental no pós-guerra.","id":"hum81"},{"t":"D","top":"História geral","f":"Em que ano caiu o Muro de Berlim?","v":"1989","x":"Fim simbólico da Guerra Fria.","id":"hum82"},{"t":"V","top":"História geral","f":"Na democracia ateniense, todos os moradores da cidade podiam votar.","ok":false,"x":"Só cidadãos homens livres nascidos em Atenas. Mulheres, estrangeiros (metecos) e escravizados estavam excluídos.","id":"hum83"},{"t":"C","top":"Geografia","f":"Cada fuso horário corresponde a ⟦1⟧° de longitude, porque 360° ÷ 24 h = 15°.","l":{"1":"15"},"id":"hum84"},{"t":"C","top":"Geografia","f":"A camada de ar frio presa sob ar quente, que retém poluentes, é a ⟦1⟧.","l":{"1":"inversão térmica"},"id":"hum85"},{"t":"C","top":"Geografia","f":"O Mercosul foi criado em ⟦1⟧ pelo Tratado de ⟦2⟧.","l":{"1":"1991","2":"Assunção"},"id":"hum86"},{"t":"R","top":"Geografia","f":"Conurbação","v":"Cidades que crescem e se juntam fisicamente.","id":"hum87"},{"t":"R","top":"Geografia","f":"Megalópole","v":"União de metrópoles (eixo Rio-São Paulo).","id":"hum88"},{"t":"R","top":"Geografia","f":"Arenização","v":"Formação de areais em solos arenosos (sudoeste do RS), agravada pelo pisoteio do gado.","id":"hum89"},{"t":"R","top":"Geografia","f":"Assoreamento","v":"Acúmulo de sedimentos no leito dos rios por causa da erosão.","id":"hum90"},{"t":"R","top":"Geografia","f":"Êxodo rural","v":"Migração do campo para a cidade.","id":"hum91"},{"t":"D","top":"Geografia","f":"Quantos graus de longitude correspondem a 1 hora de fuso?","v":"15","x":"360/24.","id":"hum92"},{"t":"D","top":"Geografia","f":"Se em Brasília (−3 h) são 12 h, que horas são em Londres (0 h)?","v":"15h","x":"Londres fica a leste: 3 h adiantada.","id":"hum93"},{"t":"V","top":"Geografia","f":"A projeção de Mercator representa corretamente o tamanho dos continentes.","ok":false,"x":"Mercator preserva as FORMAS, mas exagera áreas perto dos polos (Groenlândia parece do tamanho da África).","id":"hum94"},{"t":"V","top":"Geografia","f":"Um mapa de escala 1:1.000 tem escala menor que um de 1:1.000.000.","ok":false,"x":"1:1.000 é escala MAIOR (mais detalhe). Quanto menor o denominador, maior a escala.","id":"hum95"},{"t":"F","top":"Filosofia","f":"Qual contratualista defende o direito de resistência contra um governo que viola direitos?","v":"<b>John Locke</b>: o Estado existe para proteger vida, liberdade e propriedade; se as viola, o povo pode resistir.","img":"filo_contratualistas","id":"hum96"},{"t":"R","top":"Filosofia","f":"\"Só sei que nada sei\"","v":"Sócrates","id":"hum97"},{"t":"R","top":"Filosofia","f":"Alegoria da caverna","v":"Platão","id":"hum98"},{"t":"R","top":"Filosofia","f":"\"O homem é um animal político\" / justo meio","v":"Aristóteles","id":"hum99"},{"t":"R","top":"Filosofia","f":"\"Penso, logo existo\"","v":"Descartes","id":"hum100"},{"t":"R","top":"Filosofia","f":"Imperativo categórico","v":"Kant","id":"hum101"},{"t":"R","top":"Filosofia","f":"\"Deus está morto\" / vontade de potência","v":"Nietzsche","id":"hum102"},{"t":"R","top":"Filosofia","f":"\"A existência precede a essência\"","v":"Sartre","id":"hum103"},{"t":"R","top":"Filosofia","f":"Indústria cultural","v":"Adorno e Horkheimer (Escola de Frankfurt)","id":"hum104"},{"t":"R","top":"Filosofia","f":"O príncipe (virtù e fortuna)","v":"Maquiavel","id":"hum105"},{"t":"R","top":"Filosofia","f":"Leviatã (guerra de todos contra todos)","v":"Hobbes","id":"hum106"},{"t":"C","top":"Filosofia","f":"Para Hobbes, o estado de natureza é de ⟦1⟧; para Rousseau, o homem nasce ⟦2⟧ e a sociedade o corrompe.","l":{"1":"guerra de todos contra todos","2":"bom"},"id":"hum107"},{"t":"R","top":"Sociologia","f":"Mais-valia e luta de classes","v":"Karl Marx","id":"hum108"},{"t":"R","top":"Sociologia","f":"Ação social e tipos de dominação","v":"Max Weber","id":"hum109"},{"t":"R","top":"Sociologia","f":"Fato social e solidariedade orgânica","v":"Émile Durkheim","id":"hum110"},{"t":"R","top":"Sociologia","f":"Etnocentrismo","v":"Julgar outras culturas a partir da própria, como se fosse superior.","id":"hum111"},{"t":"R","top":"Sociologia","f":"Relativismo cultural","v":"Entender cada cultura em seus próprios termos.","id":"hum112"},{"t":"C","top":"Sociologia","f":"Weber identificou três tipos de dominação: ⟦1⟧, ⟦2⟧ e ⟦3⟧.","l":{"1":"legal","2":"tradicional","3":"carismática"},"id":"hum113"},{"t":"C","top":"Sociologia","f":"Linha de montagem e produção em massa caracterizam o ⟦1⟧; produção flexível e \"just in time\", o ⟦2⟧.","l":{"1":"fordismo","2":"toyotismo"},"id":"hum114"},{"t":"V","top":"Sociologia","f":"Para a sociologia, \"minoria\" significa sempre um grupo numericamente pequeno.","ok":false,"x":"Minoria se refere a menos poder e representação. Mulheres e negros são maioria numérica no Brasil e são estudados como minorias.","id":"hum115"}]}];
